INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对事物进行更深入、更细致的分析和处理，使其更加具体、明确。", "primary_collocate": null, "pronunciation": "xì huà", "ipa": "ɕi˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，其普及过程并非线性推进，而是伴随着各国本土化调整：例如在某些文化语境中，箭头形态被微调以避免宗教联想；而在另一些地区，则附加数字编码系统以细化分类标准。", "target_word": "细化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经理要求我们细化这个计划。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把评分标准细化成十条。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把工作分工再细化一下。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们细化了每个月的目标。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份方案太简单，需要进一步细化。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生细化了病人的检查项目。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议上大家细化了活动的每一步。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把预算细化到每一天。", "target_word": "细化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里没有细化问题的原因。", "target_word": "细化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "细化了", "label": "体标"}, {"form": "细化过", "label": "体标"}, {"form": "細化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "细化：把事物分析处理得更深入、更具体明确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细化", "is_correct": true, "explanation": "正确：细化是使分类标准更具体，与“以细化分类标准”的目的相符。"}, {"text": "粗化", "is_correct": false, "explanation": "语义：粗化是使事物变粗略，与“以细化分类标准”的目的相反。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：分类标准不能被“装饰”。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：粉刷用于墙面等表面，不能用于分类标准。"}], "explanations": {"细化": "正确：细化是使分类标准更具体，与“以细化分类标准”的目的相符。", "粗化": "语义：粗化是使事物变粗略，与“以细化分类标准”的目的相反。", "装饰": "搭配：分类标准不能被“装饰”。", "粉刷": "搭配：粉刷用于墙面等表面，不能用于分类标准。"}, "sentence_index": 0, "correct_answer": "细化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要把这份报告细化，使它变得更简短。", "explanation": "这里应该用〈简化〉。细化是使事物更具体，不是使其变短；使报告变短要用〈简化〉。"}, {"text": "公司今年细化了两名员工。", "explanation": "这里应该用〈增加〉。细化是使事物更具体，不能表示增加人数；增加员工要用〈增加〉。"}, {"text": "这盏灯太暗了，我要细化一个灯泡。", "explanation": "这里应该用〈更换〉。细化是使事物更具体，不表示换掉物品；换灯泡要用〈更换〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细化", "is_correct": true, "explanation": "正确：细化是使检查项目更具体，“医生细化了检查项目”语境相符。"}, {"text": "感染", "is_correct": false, "explanation": "语义：感染指病原体侵入，不能用来处理检查项目。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割是农作物的动作，与检查项目无关。"}, {"text": "剥削", "is_correct": false, "explanation": "搭配：“剥削”的对象是人或劳动，不能用于检查项目。"}], "explanations": {"细化": "正确：细化是使检查项目更具体，“医生细化了检查项目”语境相符。", "感染": "语义：感染指病原体侵入，不能用来处理检查项目。", "收割": "语义：收割是农作物的动作，与检查项目无关。", "剥削": "搭配：“剥削”的对象是人或劳动，不能用于检查项目。"}, "sentence_index": 6, "correct_answer": "细化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要把这份报告细化成一页纸，方便大家阅读。", "explanation": "这里应该用〈精简〉。细化是使事物更具体，不是使内容变短；把报告缩成一页要用〈精简〉。"}, {"text": "我们把视频细化了，传输更快。", "explanation": "这里应该用〈压缩〉。细化不能减小文件的体积；让视频传得更快要用〈压缩〉。"}, {"text": "他把墙细化成了白色。", "explanation": "这里应该用〈刷〉。细化是使事物更具体，不表示改变颜色；把墙刷成白色要用〈刷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把计划细化很清楚。", "corrected_sentence": "他把计划细化得很清楚。", "error_description": "补语错：表示程度的补语前要加“得”，应说“细化得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这份分工细化的很具体。", "corrected_sentence": "请把这份分工细化得很具体。", "error_description": "补语错：程度补语前应用“得”，不能用“的”，应说“细化得很具体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
