INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12535, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物在规格、性能或条件上符合某种要求或能够协调配合。", "primary_collocate": null, "pronunciation": "shì pèi", "ipa": "ʂɨ˥˩ pʰei̯˥˩", "syllable_count": 2, "sentences": [{"text": "这种“全球原型-本地适配”的双重逻辑，正是现代环境符号学的核心特征。", "target_word": "适配", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "该框架采用模块化设计，能够适配多种硬件平台，显著降低了跨平台开发的重复劳动。", "target_word": "适配", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这款充电器可以适配多种手机。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件需要适配新的系统。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在适配这台新电脑的驱动程序。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏已经适配了平板电脑。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个镜头可以适配不同品牌的相机。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新版网站能适配不同大小的屏幕。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的产品需要适配当地的电压标准。", "target_word": "适配", "complexity_tier": "T3", "furigana": "gōngsī de chǎnpǐn xūyào shìpèi dāngdì de diànyā biāozhǔn", "sentence_source": "generated"}, {"text": "这套系统很难适配老式机器。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适配器", "label": "复合"}, {"form": "适配性", "label": "复合"}, {"form": "适配了", "label": "体标"}], "register": "书面", "sense_fingerprint": "调整产品或系统，使其符合规格或要求并能配合使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适配", "is_correct": true, "explanation": "适配：使事物符合本地条件、彼此协调，与“全球原型—本地”的调整逻辑相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫使其不受损害，与“全球原型—本地”的调整逻辑不合。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：撤销指取消，与“全球原型—本地”的对应关系不合。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：停滞指不再前进，与“全球原型—本地”的调整逻辑不合。"}], "explanations": {"适配": "适配：使事物符合本地条件、彼此协调，与“全球原型—本地”的调整逻辑相合。", "保护": "语义：“保护”是护卫使其不受损害，与“全球原型—本地”的调整逻辑不合。", "撤销": "语义：撤销指取消，与“全球原型—本地”的对应关系不合。", "停滞": "语义：停滞指不再前进，与“全球原型—本地”的调整逻辑不合。"}, "sentence_index": 0, "correct_answer": "适配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快适配了新的环境。", "explanation": "这里应该用〈适应〉。适配多用于设备、软件、系统，人对环境的适应要用适应。"}, {"text": "大家要互相适配，才能完成任务。", "explanation": "这里应该用〈配合〉。适配指使器件、系统符合规格，人与人之间的协作要用配合。"}, {"text": "他适配了一个好消息给大家。", "explanation": "这里应该用〈传达〉。适配指使器件、系统符合规格，传递消息要用传达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适配", "is_correct": true, "explanation": "适配：使镜头能和不同品牌的相机配合使用，符合句意。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”是修好坏掉的东西，镜头并不能修理相机。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的施事要能付钱，“镜头”不能充当买的一方。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”指生产出物品，与镜头和相机之间的配合意思不合。"}], "explanations": {"适配": "适配：使镜头能和不同品牌的相机配合使用，符合句意。", "维修": "语义：“维修”是修好坏掉的东西，镜头并不能修理相机。", "购买": "配价：“购买”的施事要能付钱，“镜头”不能充当买的一方。", "制造": "语义：“制造”指生产出物品，与镜头和相机之间的配合意思不合。"}, "sentence_index": 6, "correct_answer": "适配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板适配了工作时间。", "explanation": "这里应该用〈调整〉。适配指使设备、系统符合规格或能配合，工作时间的改动要用调整。"}, {"text": "他适配了一个笑容。", "explanation": "这里应该用〈露出〉。适配指使器件、系统符合规格，表情要用露出。"}, {"text": "他们应该多适配，好解决误会。", "explanation": "这里应该用〈沟通〉。适配指使事物符合规格，人与人之间消除误会要用沟通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们认真的适配了新的系统。", "corrected_sentence": "他们认真地适配了新的系统。", "error_description": "“认真”修饰动词“适配”，应用“地”而不是“的”：应为“认真地适配”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统适配很好。", "corrected_sentence": "这套系统适配得很好。", "error_description": "补语前缺“得”：“适配”后带程度补语“很好”时应说“适配得很好”，漏掉“得”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
