INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "符号学是研究符号系统及其意义的学科，涵盖语言、图像、手势等各种符号。", "primary_collocate": null, "pronunciation": "fú hào xué", "ipa": "fu˧˥ xɑʊ˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "这种“全球原型-本地适配”的双重逻辑，正是现代环境符号学的核心特征。", "target_word": "符号学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "符号学研究语言、图像和手势的意义。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学时学的是符号学。", "target_word": "符号学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书介绍了符号学的基本概念。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "符号学老师在课上讲了交通标志。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用符号学分析这幅广告画。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "符号学认为，每个符号都有意义。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对符号学很感兴趣，常去听讲座。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "符号学能帮我们看懂广告里的图像。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门符号学课要读很多书。", "target_word": "符号学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號學", "label": "繁体"}, {"form": "符号学家", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "研究符号系统及其意义的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号学", "is_correct": true, "explanation": "正确：符号学是研究符号系统的学科，可与“现代环境”组成学科名。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是研究符号的学科，句中说的是学问。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱指菜谱，不是研究符号及其意义的学问。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“现代环境”后不能接“乐器”构成研究领域。"}], "explanations": {"符号学": "正确：符号学是研究符号系统的学科，可与“现代环境”组成学科名。", "天气": "语义：天气是自然现象，不是研究符号的学科，句中说的是学问。", "食谱": "语义：食谱指菜谱，不是研究符号及其意义的学问。", "乐器": "搭配：“现代环境”后不能接“乐器”构成研究领域。"}, "sentence_index": 0, "correct_answer": "符号学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个路口的符号学很醒目。", "explanation": "这里应该用〈符号〉。符号学是学科名，指路口的具体标志要说〈符号〉，两者容易混淆。"}, {"text": "他买了一只符号学。", "explanation": "这里应该用〈门〉。学科用“门”计量，不用“只”。"}, {"text": "他是一位著名的符号学。", "explanation": "这里应该用〈符号学家〉。符号学指学科，指人要说〈符号学家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号学", "is_correct": true, "explanation": "正确：符号学是学科，能够“认为”某种观点。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“认为”要求有认知能力的主语，石头不能认为。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是场所，不能持有“每个符号都有意义”的看法。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，无法表达观点。"}], "explanations": {"符号学": "正确：符号学是学科，能够“认为”某种观点。", "石头": "配价：“认为”要求有认知能力的主语，石头不能认为。", "食堂": "语义：食堂是场所，不能持有“每个符号都有意义”的看法。", "窗户": "语义：窗户是物件，无法表达观点。"}, "sentence_index": 6, "correct_answer": "符号学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给符号学加了点盐。", "explanation": "这里应该用〈汤〉。符号学是抽象的学问，不是食物，不能加盐调味；“加盐”只用于汤菜之类的食物。"}, {"text": "他把符号学摔碎了。", "explanation": "这里应该用〈瓶子〉。符号学是抽象学科，不能摔碎，“摔碎”只用于具体物件。"}, {"text": "他在符号学旁边坐了一下午。", "explanation": "这里应该用〈课桌〉。符号学是学科，不是可以坐在旁边的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校这学期开了一个符号学。", "corrected_sentence": "我们学校这学期开了一门符号学。", "error_description": "“符号学”是学科，量词应用“门”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他符号学很感兴趣。", "corrected_sentence": "他对符号学很感兴趣。", "error_description": "“感兴趣”前缺少介词“对”，应说“对符号学很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
