INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对着某个方向或目标示意或指示。", "primary_collocate": null, "pronunciation": "zhǐ xiàng", "ipa": "ʈʂɻ̩˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子举起小手，指向天空中最亮的星星。", "target_word": "指向", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "路牌指向火车站。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他伸出手，指向窗外。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "箭头指向右边，我们往右走。", "target_word": "指向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用笔指向黑板上的字。", "target_word": "指向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时钟的短针指向了三点。", "target_word": "指向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游指向远处的山谷，说那里风景很美。", "target_word": "指向", "complexity_tier": "T3", "furigana": "zhǐ xiàng", "sentence_source": "generated"}, {"text": "地图上的红线指向海边。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "指南针总是指向北方。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "侦探指向房间角落的那个人。", "target_word": "指向", "complexity_tier": "T3", "furigana": "zhǐ xiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "指向了", "label": "体标"}, {"form": "指向着", "label": "体标"}, {"form": "指向性", "label": "复合"}], "register": "中性", "sense_fingerprint": "对着某个方向或目标示意、指示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：zhǐ xiàng，对着某个方向或目标示意或指示。"}, {"text": "志向", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求，与指向意思不同。"}, {"text": "纸箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，纸箱指用纸做成的箱子。"}, {"text": "子项", "is_correct": false, "explanation": "zǐ（第三声）与 zhǐ（第三声）仅 z 与 zh 声母不同，子项指总项下的细目。"}, {"text": "事项", "is_correct": false, "explanation": "shì（第四声）与 zhǐ（第三声）声母和声调都不同（sh 与 zh），事项指事情或条目。"}], "explanations": {"指向": "指向：zhǐ xiàng，对着某个方向或目标示意或指示。", "志向": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求，与指向意思不同。", "纸箱": "xiāng（第一声）与 xiàng（第四声）声调不同，纸箱指用纸做成的箱子。", "子项": "zǐ（第三声）与 zhǐ（第三声）仅 z 与 zh 声母不同，子项指总项下的细目。", "事项": "shì（第四声）与 zhǐ（第三声）声母和声调都不同（sh 与 zh），事项指事情或条目。"}, "sentence_index": null, "correct_answer": "指向"}, "level_3": {"options": [{"text": "指向", "is_correct": true, "explanation": "正确：此处表示用手对着天空中的星星示意，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」指用牙齿啃，不能用于对着星星示意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」多用于器物或设备，不能用于示意天空中的星星。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：「冲洗」用于洗涤具体物体，不能用于示意天空中的星星。"}], "explanations": {"指向": "正确：此处表示用手对着天空中的星星示意，符合句意。", "咬": "语义：「咬」指用牙齿啃，不能用于对着星星示意。", "修理": "搭配：「修理」多用于器物或设备，不能用于示意天空中的星星。", "冲洗": "搭配：「冲洗」用于洗涤具体物体，不能用于示意天空中的星星。"}, "sentence_index": 0, "correct_answer": "指向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指向了我的心意。", "explanation": "这里应该用〈领会〉。领会是理解对方的意思，指向只表示用手或物体对着某个地方，不能用于心意这类无形之物。"}, {"text": "她指向了这次行动。", "explanation": "这里应该用〈指挥〉。指挥是调度、发号施令，指向只表示用手或物体对着某个地方，不能用于行动。"}, {"text": "妈妈指向了我乱花钱的习惯。", "explanation": "这里应该用〈纠正〉。纠正是改正别人的错误做法，指向只表示用手或物体对着某个地方，不能用于习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：zhǐ xiàng，对着某个方向或目标示意或指示。"}, {"text": "指望", "is_correct": false, "explanation": "wàng 与 xiàng 声母不同（w 与 x），指望意思是期望或依靠。"}, {"text": "纸样", "is_correct": false, "explanation": "yàng 与 xiàng 声母不同（y 与 x），纸样指纸制的样板。"}, {"text": "纸线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-an 与 -ang），纸线指用纸搓成的线。"}], "explanations": {"指向": "指向：zhǐ xiàng，对着某个方向或目标示意或指示。", "指望": "wàng 与 xiàng 声母不同（w 与 x），指望意思是期望或依靠。", "纸样": "yàng 与 xiàng 声母不同（y 与 x），纸样指纸制的样板。", "纸线": "xiàn 与 xiàng 韵母不同（-an 与 -ang），纸线指用纸搓成的线。"}, "sentence_index": null, "correct_answer": "指向"}, "level_3": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：此处表示用手或目光对着远处的山谷示意，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "语义：「搬」指移动可搬动的物品，不能搬动远处的山谷。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」用于擦拭物体表面，不能用于远处的山谷。"}, {"text": "推", "is_correct": false, "explanation": "语义：「推」是用力使物体移动，无法推动远处的山谷。"}], "explanations": {"指向": "指向：此处表示用手或目光对着远处的山谷示意，符合句意。", "搬": "语义：「搬」指移动可搬动的物品，不能搬动远处的山谷。", "擦": "搭配：「擦」用于擦拭物体表面，不能用于远处的山谷。", "推": "语义：「推」是用力使物体移动，无法推动远处的山谷。"}, "sentence_index": 6, "correct_answer": "指向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他指向了我的心情。", "explanation": "这里应该用〈体谅〉。体谅是设身处地为别人着想，指向只表示用手或物体对着某个地方，不能用于心情这类无形之物。"}, {"text": "他指向了这次胜利。", "explanation": "这里应该用〈庆祝〉。庆祝是为胜利而欢庆，指向只表示用手或物体对着某个地方，不能表示庆祝。"}, {"text": "朋友指向了这次旅行的快乐。", "explanation": "这里应该用〈分享〉。分享是与别人共同拥有快乐，指向只表示用手或物体对着某个地方，不能用于快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箭头指向向左边。", "corrected_sentence": "箭头指向左边。", "error_description": "「指向」已经包含“向”的方向义，后面不能再加“向”，应说「箭头指向左边」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他指向向远方的山峰。", "corrected_sentence": "他指向远方的山峰。", "error_description": "「指向」本身已含方向义，后面不能再加「向」。应说「他指向远方的山峰」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
