INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用旧材料制造新产品的过程", "primary_collocate": null, "pronunciation": "zài shēng", "ipa": "tsaɪ̯˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "它不再仅指向物理层面的材料再生，更被赋予伦理与政治维度——消费者通过识别此符号，参与一场隐性的公民实践，表达对过度生产模式的反思。", "target_word": "再生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "再生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "旧塑料经过处理可以再生，变成新的瓶子。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸再生需要很多水和电。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门做废金属的再生。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃可以反复再生，质量不会变差。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服再生以后，能做成新的布。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的废料再生，能减少很多垃圾。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料再生的成本很低。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧轮胎再生后可以铺在操场上。", "target_word": "再生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生纸", "label": "复合"}, {"form": "再生塑料", "label": "复合"}], "register": "中性", "sense_fingerprint": "旧材料经过加工，重新制成新产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d2e93ab-0075-4fa4-8695-09f8dab38044') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指用旧材料制造新产品。"}, {"text": "再争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。"}, {"text": "再称", "is_correct": false, "explanation": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次重量。"}, {"text": "再深", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。"}, {"text": "再省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。"}, {"text": "再胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指用旧材料制造新产品。", "再争": "zhēng 与 shēng 声母不同（zh／sh），意思是争取，不是再生。", "再称": "chēng 与 shēng 声母不同（ch／sh），意思是再称一次重量。", "再深": "shēn 与 shēng 韵尾不同（n／ng），意思是再深一些。", "再省": "shěng（第三声）与 shēng（第一声）声调不同，意思是再节省。", "再胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是再次获胜。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：“材料再生”指旧材料加工后重新成为可用材料，与前文的伦理与政治语境相符。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与“赋予伦理维度”所指的再利用意义相反。"}, {"text": "填埋", "is_correct": false, "explanation": "语义：填埋是丢弃处理，与消费者识别符号、参与公民实践的语境不符。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：报废多用于设备、车辆等，不说“材料报废”这样的搭配。"}], "explanations": {"再生": "正确：“材料再生”指旧材料加工后重新成为可用材料，与前文的伦理与政治语境相符。", "销毁": "语义：销毁是彻底毁掉，与“赋予伦理维度”所指的再利用意义相反。", "填埋": "语义：填埋是丢弃处理，与消费者识别符号、参与公民实践的语境不符。", "报废": "搭配：报废多用于设备、车辆等，不说“材料报废”这样的搭配。"}, "sentence_index": 0, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把脏衣服再生干净了。", "explanation": "这里应该用〈清洗〉。再生指旧材料加工成新产品，把脏衣服洗干净要用“清洗”，不能说“再生”。"}, {"text": "工人正在再生这套房子。", "explanation": "这里应该用〈装修〉。再生指旧材料加工成新产品，房子要“装修”，不能说“再生”。"}, {"text": "医生正在再生这位病人。", "explanation": "这里应该用〈治疗〉。再生指旧材料加工成新产品，对病人要“治疗”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确答案：再生（zài shēng），指用旧材料制造新产品。"}, {"text": "再扔", "is_correct": false, "explanation": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。"}, {"text": "再伸", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。"}, {"text": "再盛", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。"}], "explanations": {"再生": "正确答案：再生（zài shēng），指用旧材料制造新产品。", "再扔": "rēng 与 shēng 声母不同（r／sh），意思是再扔掉。", "再伸": "shēn 与 shēng 韵尾不同（n／ng），意思是再伸展。", "再盛": "shèng（第四声）与 shēng（第一声）声调不同，意思是再盛一碗饭。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "正确：旧衣服经加工重新成为材料，才能做成新的布，符合“再生”的意思。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与“能做成新的布”的结果矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃是扔掉，与“能做成新的布”的结果矛盾。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁会把衣服烧成灰，无法再做成布。"}], "explanations": {"再生": "正确：旧衣服经加工重新成为材料，才能做成新的布，符合“再生”的意思。", "销毁": "语义：销毁是彻底毁掉，与“能做成新的布”的结果矛盾。", "丢弃": "语义：丢弃是扔掉，与“能做成新的布”的结果矛盾。", "烧毁": "语义：烧毁会把衣服烧成灰，无法再做成布。"}, "sentence_index": 6, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的计划很快就再生了。", "explanation": "这里用“再生”表示计划重新复活，但“再生”只指旧材料加工成新产品或生物重新长出，不能用于计划等抽象事物。"}, {"text": "这幅古画经过修复，基本再生了。", "explanation": "这里应该用〈复原〉。再生是把旧材料制成新产品，古画受损后要“复原”，不能说“再生”。"}, {"text": "这条漏水的管子已经自己再生好了。", "explanation": "这里应该用〈修补〉。再生指旧材料加工成新产品，漏水的管子要“修补”，不能说“再生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种旧瓶子再生了新的杯子。", "corrected_sentence": "这种旧瓶子再生成了新的杯子。", "error_description": "“再生”后漏掉了结果补语“成”。表示加工成某种新物品，要说“再生成”，直接接宾语“新的杯子”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批旧纸还没再生了，先放在仓库里。", "corrected_sentence": "这批旧纸还没再生，先放在仓库里。", "error_description": "“了”用错了位置：“还没”表示尚未发生，否定结构中动词后不能加“了”，应说“这批旧纸还没再生”，不能说“还没再生了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把权利、责任、意义等抽象的东西交给别人或事物。", "primary_collocate": null, "pronunciation": "fù yǔ", "ipa": "fu˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "它不再仅指向物理层面的材料再生，更被赋予伦理与政治维度——消费者通过识别此符号，参与一场隐性的公民实践，表达对过度生产模式的反思。", "target_word": "赋予", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "父母给孩子起名字，也赋予了他们美好的希望。", "target_word": "赋予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律赋予每个公民平等的权利。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司赋予新经理很大的决定权。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个节日赋予了家人团聚的特别意义。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师赋予这个游戏新的教学意义。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家赋予学校更多自己做决定的权力。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术家赋予普通的石头生命和感情。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大自然赋予人类丰富的想象力。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会赋予了医生很重的责任。", "target_word": "赋予", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赋予了", "label": "体标"}, {"form": "赋予过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把权力、责任、意义等抽象的东西交给人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赋予", "is_correct": true, "explanation": "赋予：fù yǔ，把权利、责任、意义等抽象的东西交给人或事物。"}, {"text": "富裕", "is_correct": false, "explanation": "yù（第四声）与 yǔ（第三声）声调不同，富裕指财物充足。"}, {"text": "抚育", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同；yù（第四声）与 yǔ（第三声）声调也不同，抚育指养育、培养。"}, {"text": "富余", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，富余指有多余的。"}], "explanations": {"赋予": "赋予：fù yǔ，把权利、责任、意义等抽象的东西交给人或事物。", "富裕": "yù（第四声）与 yǔ（第三声）声调不同，富裕指财物充足。", "抚育": "fǔ（第三声）与 fù（第四声）声调不同；yù（第四声）与 yǔ（第三声）声调也不同，抚育指养育、培养。", "富余": "yú（第二声）与 yǔ（第三声）声调不同，富余指有多余的。"}, "sentence_index": null, "correct_answer": "赋予"}, "level_3": {"options": [{"text": "赋予", "is_correct": true, "explanation": "赋予：此处指把伦理与政治的意义交给这一符号，符合句意。"}, {"text": "剥夺", "is_correct": false, "explanation": "语义：「剥夺」表示夺去，与「更被……」所表达的给予方向相反。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：「摧毁」表示毁坏，无法与「伦理与政治维度」这样的意义搭配。"}, {"text": "清除", "is_correct": false, "explanation": "语义：「清除」表示去掉，与句中「更被」所说的正面引申不符。"}], "explanations": {"赋予": "赋予：此处指把伦理与政治的意义交给这一符号，符合句意。", "剥夺": "语义：「剥夺」表示夺去，与「更被……」所表达的给予方向相反。", "摧毁": "语义：「摧毁」表示毁坏，无法与「伦理与政治维度」这样的意义搭配。", "清除": "语义：「清除」表示去掉，与句中「更被」所说的正面引申不符。"}, "sentence_index": 0, "correct_answer": "赋予"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈赋予我一个苹果。", "explanation": "这里应该用〈送〉。赋予用于权利、责任、意义等抽象事物，苹果是具体物品，不能用赋予。"}, {"text": "老板把文件赋予秘书。", "explanation": "这里应该用〈交给〉。文件是具体物品，赋予只用于抽象的权利或责任。"}, {"text": "他赋予了我一把伞。", "explanation": "这里应该用〈借〉。赋予用于权利、责任、意义等抽象事物，伞是具体物品，不能用赋予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赋予", "is_correct": true, "explanation": "赋予：fù yǔ，把权利、责任、意义等抽象的东西交给人或事物。"}, {"text": "富裕", "is_correct": false, "explanation": "yù（第四声）与 yǔ（第三声）仅声调不同，富裕指财物充足。"}, {"text": "妇女", "is_correct": false, "explanation": "nǚ 与 yǔ 仅声母不同（n 与零声母），妇女指成年女性。"}, {"text": "富于", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，富于指具有很多，如富于想象。"}], "explanations": {"赋予": "赋予：fù yǔ，把权利、责任、意义等抽象的东西交给人或事物。", "富裕": "yù（第四声）与 yǔ（第三声）仅声调不同，富裕指财物充足。", "妇女": "nǚ 与 yǔ 仅声母不同（n 与零声母），妇女指成年女性。", "富于": "yú（第二声）与 yǔ（第三声）声调不同，富于指具有很多，如富于想象。"}, "sentence_index": null, "correct_answer": "赋予"}, "level_3": {"options": [{"text": "赋予", "is_correct": true, "explanation": "赋予：此处指国家把决定的权力交给学校，符合句意。"}, {"text": "收购", "is_correct": false, "explanation": "语义：「收购」是买进财物，无法用于权力。"}, {"text": "征收", "is_correct": false, "explanation": "搭配：「征收」用于税费或财物，不能用于决定的权力。"}, {"text": "掠夺", "is_correct": false, "explanation": "语义：「掠夺」是强行夺取，与国家给予学校权力的语境相反。"}], "explanations": {"赋予": "赋予：此处指国家把决定的权力交给学校，符合句意。", "收购": "语义：「收购」是买进财物，无法用于权力。", "征收": "搭配：「征收」用于税费或财物，不能用于决定的权力。", "掠夺": "语义：「掠夺」是强行夺取，与国家给予学校权力的语境相反。"}, "sentence_index": 6, "correct_answer": "赋予"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生赋予了我一块糖。", "explanation": "这里应该用〈给〉。赋予用于权利、责任、意义等抽象事物，糖是日常的具体物品，不能用赋予。"}, {"text": "他赋予了一份礼物。", "explanation": "这里应该用〈赠送〉。赋予用于权利、责任、意义等抽象事物，礼物是具体物品，不宜用赋予。"}, {"text": "他赋予了我的道歉。", "explanation": "这里应该用〈接受〉。接受是收下对方的道歉；赋予是把东西交给别人，句中「他」是给出的一方，且道歉不能被赋予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校赋予给学生选择课程的权利。", "corrected_sentence": "学校赋予学生选择课程的权利。", "error_description": "「赋予」与「给」同义，不能连用。应去掉「给」，说「学校赋予学生选择课程的权利」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份荣誉赋予他了继续努力的动力。", "corrected_sentence": "这份荣誉赋予了他继续努力的动力。", "error_description": "「了」应紧跟动词「赋予」，表示动作完成，不能放在宾语「他」之后。应说「赋予了他」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
