INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指从事科学研究、高等教育等学术活动的群体和领域。", "primary_collocate": null, "pronunciation": "xué shù jiè", "ipa": "ɕɥe˧˥ ʂu˥˩ tɕje˥˩", "syllable_count": 3, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "学术界", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学术界对这个问题还有不同的看法。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授在学术界很有名。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的朋友常常一起开会讨论。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业后想留在学术界工作。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书在学术界得到了很高的评价。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界需要自由的研究环境。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人进入学术界并不容易。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开公司，回到学术界当研究员。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个研究结果在学术界引起了很大的关注。", "target_word": "学术界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "学术研究", "label": "复合"}, {"form": "学术会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "学术研究和高等教育这一领域及其整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32eff56-4792-44c1-a9a0-d093cf3792f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学术界", "is_correct": true, "explanation": "正确：「学术界」指学术研究领域，与“视觉修辞”的探讨语境一致。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不是能探讨“效力”的主体。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：“动物园”是场所，不能作“探讨”的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能作“探讨”的主体。"}], "explanations": {"学术界": "正确：「学术界」指学术研究领域，与“视觉修辞”的探讨语境一致。", "厨房": "语义：“厨房”是场所，不是能探讨“效力”的主体。", "动物园": "语义：“动物园”是场所，不能作“探讨”的主语。", "冰箱": "语义：“冰箱”是家电，不能作“探讨”的主体。"}, "sentence_index": 0, "correct_answer": "学术界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位学术界很有名。", "explanation": "这里应该用〈学者〉。学术界指领域，不能当作具体的人来说“这位……很有名”。"}, {"text": "学术界在这条河的东边。", "explanation": "这里应该用〈大学城〉。学术界指领域，不是有位置的地方，不能说“在……东边”。"}, {"text": "他是一位学术界。", "explanation": "这里应该用〈学者〉。学术界指整个领域，不能当作一个人来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学术界", "is_correct": true, "explanation": "正确：「学术界」指学术研究领域，与“需要自由的研究环境”相符。"}, {"text": "工地", "is_correct": false, "explanation": "语义：“工地”是施工场所，不需要“自由的研究环境”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形外貌，与“研究环境”的需要搭不上。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：“菜市场”是买卖蔬菜的地方，与学术研究无关。"}], "explanations": {"学术界": "正确：「学术界」指学术研究领域，与“需要自由的研究环境”相符。", "工地": "语义：“工地”是施工场所，不需要“自由的研究环境”。", "身材": "体貌：“身材”指体形外貌，与“研究环境”的需要搭不上。", "菜市场": "语义：“菜市场”是买卖蔬菜的地方，与学术研究无关。"}, "sentence_index": 6, "correct_answer": "学术界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅就在学术界附近。", "explanation": "这里应该用〈大学〉。学术界是领域，不是地点，不能说“附近”。"}, {"text": "学术界，请您先坐下。", "explanation": "这里应该用〈教授〉作称呼。学术界指领域，不能当作人来称呼。"}, {"text": "这张桌子是用学术界做的。", "explanation": "这里应该用〈木头〉。学术界是领域，不能当作制作桌子的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学术界有很多朋友。", "corrected_sentence": "我在学术界有很多朋友。", "error_description": "“学术界”作处所时前面要加介词“在”。应说“我在学术界有很多朋友”，漏掉“在”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学者毕业后想进入学术界的。", "corrected_sentence": "这位学者毕业后想进入学术界。", "error_description": "“学术界的”不能直接收尾，句末须删去“的”，应说“想进入学术界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd44810c-5072-498e-95e3-d835a6290ca0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
