INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "修饰文字或语言，使表达更生动、有力或更具艺术性的技巧。", "primary_collocate": null, "pronunciation": "xiū cí", "ipa": "ɕjoʊ˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "修辞", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这篇文章用了很多修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比喻是一种常见的修辞。", "target_word": "修辞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的演讲没有太多修辞，但很真诚。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诗人善于运用修辞。", "target_word": "修辞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "广告里常常有夸张的修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的作文不只靠修辞，也要有内容。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课上我们学了比喻和拟人这两种修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话的修辞很巧妙，读起来很有力。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一件小事写得很美，全靠修辞。", "target_word": "修辞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "修辞：名词，修饰语言文字、增强表达效果的技巧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b13fca-7ff9-4ad7-86d0-6347cd2ffa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修辞", "is_correct": true, "explanation": "正确答案。修辞是名词，指修饰文字的技巧，与“视觉修辞的效力”的语境相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱指菜谱，与“视觉”及“效力”的语境不合，不能作为视觉的效力。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：“视觉账本”不是常见搭配，账本与这里讨论的视觉表达无关。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤指食物，与句中关于符号化呈现和回收系统的论述不合。"}], "explanations": {"修辞": "正确答案。修辞是名词，指修饰文字的技巧，与“视觉修辞的效力”的语境相符。", "食谱": "语义：食谱指菜谱，与“视觉”及“效力”的语境不合，不能作为视觉的效力。", "账本": "搭配：“视觉账本”不是常见搭配，账本与这里讨论的视觉表达无关。", "汤": "语义：汤指食物，与句中关于符号化呈现和回收系统的论述不合。"}, "sentence_index": 0, "correct_answer": "修辞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学了一个修辞。", "explanation": "这里应该用〈种〉。修辞是一类表达技巧，用“种”来计量，不用“个”。"}, {"text": "这篇文章很修辞。", "explanation": "这里应该用〈文采〉。修辞是名词，不能受“很”修饰；应说“很有文采”。"}, {"text": "他修辞了一辆旧自行车。", "explanation": "这里应该用〈修理〉。修辞指修饰文字或语言的技巧，不能用于修理器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修辞", "is_correct": true, "explanation": "正确答案。修辞指修饰文字的技巧，与“不只靠”之后“也要有内容”的对比相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是书写工具，与作文的写作手法无关，不能说不只靠黑板。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，与作文的好坏无关，句子意思不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“靠鞋子”不是常见搭配，鞋子与写作的成败没有关系。"}], "explanations": {"修辞": "正确答案。修辞指修饰文字的技巧，与“不只靠”之后“也要有内容”的对比相符。", "黑板": "语义：黑板是书写工具，与作文的写作手法无关，不能说不只靠黑板。", "厨房": "语义：厨房是场所，与作文的好坏无关，句子意思不通。", "鞋子": "搭配：“靠鞋子”不是常见搭配，鞋子与写作的成败没有关系。"}, "sentence_index": 6, "correct_answer": "修辞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把头发修辞得很漂亮。", "explanation": "修辞的意思是修饰文字或语言，只用于文字语言，不能用于头发。"}, {"text": "这双鞋的修辞很合脚。", "explanation": "修辞只指修饰文字或语言的技巧，不能用来说鞋子合不合脚。"}, {"text": "这台电脑的修辞坏了。", "explanation": "修辞指语言表达的技巧，不是能坏的器物，不能用于电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了几个修辞。", "corrected_sentence": "我们学了几种修辞。", "error_description": "错误形式“几个修辞”中量词“个”与抽象名词“修辞”搭配错误，应用“种”来计量。正确形式为“几种修辞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用修辞了让文章更生动。", "corrected_sentence": "他用修辞让文章更生动。", "error_description": "错误形式“用修辞了让文章更生动”在名词“修辞”后加了“了”，名词不能带“了”。正确形式“用修辞让文章更生动”不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
