INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "效力指事物或行为所产生的积极作用或效果。", "primary_collocate": null, "pronunciation": "xiào lì", "ipa": "ɕjaʊ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这种药的效力很强，吃一次就够了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一年，这瓶药已经没有效力了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告的效力很大，很多人都去买了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种疫苗的效力不太好。", "target_word": "效力", "complexity_tier": "T3", "furigana": "xiào lì", "sentence_source": "generated"}, {"text": "这种清洁剂的效力能保持一个月。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，药的效力会变弱。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杀虫剂的效力很强，蚊子都不见了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想知道这种新药有没有效力。", "target_word": "效力", "complexity_tier": "T3", "furigana": "xiào lì", "sentence_source": "generated"}, {"text": "药放太久，效力会慢慢变小。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不信这种保健品有什么效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "药、方法等事物产生的积极作用或效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425de479-e790-4eba-b065-e6117f93c8ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指事物产生的积极作用，即正确答案。"}, {"text": "效率", "is_correct": false, "explanation": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率（单位时间内的工作量）。"}, {"text": "效益", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母与 l），意思是效益（经济上的收益）。"}, {"text": "小利", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利（微小的好处）。"}, {"text": "下力", "is_correct": false, "explanation": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。"}], "explanations": {"效力": "效力指事物产生的积极作用，即正确答案。", "效率": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率（单位时间内的工作量）。", "效益": "yì 与 lì 声母不同（零声母与 l），意思是效益（经济上的收益）。", "小利": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利（微小的好处）。", "下力": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指药物等产生的作用，“很强”形容作用的大小，与语境相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“强”形容力量或作用，不能形容价格，这里应说“价格高”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“很强”不用于形容数量，数量多应说“很多”或“很大”。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装指外面的包裹，与药的作用无关，“很强”说的是药效。"}], "explanations": {"效力": "效力指药物等产生的作用，“很强”形容作用的大小，与语境相符。", "价格": "搭配：“强”形容力量或作用，不能形容价格，这里应说“价格高”。", "数量": "搭配：“很强”不用于形容数量，数量多应说“很多”或“很大”。", "包装": "语义：包装指外面的包裹，与药的作用无关，“很强”说的是药效。"}, "sentence_index": 0, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器每小时的效力是五百个，一天就能做完一万个。", "explanation": "这里应该用〈产量〉。产量指生产的数量，可以计件；效力指事物产生的作用，不能用件数来表示。"}, {"text": "这家工厂去年的效力是三百万，利润增加了一倍。", "explanation": "这里应该用〈效益〉。效益指经济上的收益；效力指事物产生的作用，不能用金额来表示。"}, {"text": "这位新员工的效力很强，三天就学会了所有的操作。", "explanation": "这里应该用〈能力〉。能力指做事的本领，用于人；效力指事物产生的作用，不用来形容人的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指事物产生的积极作用，即正确答案。"}, {"text": "笑料", "is_correct": false, "explanation": "liào（第四声）与 lì（第四声）韵母不同（iao 与 i），意思是笑料（引人发笑的材料）。"}, {"text": "小吏", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏（级别低的官员）。"}, {"text": "小粒", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小粒（细小的颗粒）。"}], "explanations": {"效力": "效力指事物产生的积极作用，即正确答案。", "笑料": "liào（第四声）与 lì（第四声）韵母不同（iao 与 i），意思是笑料（引人发笑的材料）。", "小吏": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏（级别低的官员）。", "小粒": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小粒（细小的颗粒）。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指杀虫剂产生的作用，“很强”和“蚊子都不见了”都指向药效。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“强”不能形容重量，重量大应说“重”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字只是称呼，与“蚊子都不见了”的杀虫作用无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“强”形容力量，不能用来形容年龄，年龄应说“大”或“小”。"}], "explanations": {"效力": "效力指杀虫剂产生的作用，“很强”和“蚊子都不见了”都指向药效。", "重量": "搭配：“强”不能形容重量，重量大应说“重”。", "名字": "语义：名字只是称呼，与“蚊子都不见了”的杀虫作用无关。", "年龄": "搭配：“强”形容力量，不能用来形容年龄，年龄应说“大”或“小”。"}, "sentence_index": 6, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用尽全身的效力推开了门。", "explanation": "这里应该用〈力气〉。力气指人的体力，用于推、举等动作；效力指事物产生的作用，不能用来说人的体力。"}, {"text": "这套新系统每天的效力是两千份，比旧的多一倍。", "explanation": "这里应该用〈处理量〉。处理量指系统能处理的数量；效力指事物产生的作用，不能用份数来表示。"}, {"text": "我不信这座效力有什么用。", "explanation": "“效力”是抽象名词，应该用量词〈种〉。〈座〉用于山、房屋等大型固定的东西，不能用来修饰效力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种喷雾很效力强，能保持一个星期。", "corrected_sentence": "这种喷雾的效力强，能保持一个星期。", "error_description": "“效力”是名词，前面不能直接加副词“很”修饰；应在“效力”前用“的”连接，说“的效力强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药不有效力，我们不要再买了。", "corrected_sentence": "这种药没有效力，我们不要再买了。", "error_description": "“有”的否定要用“没”，不用“不”；应说“没有效力”，不说“不有效力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物质在环境中被分解并重新利用的过程", "primary_collocate": null, "pronunciation": "dài xiè", "ipa": "taɪ̯⁵¹ ɕjɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这标志着材料科学正从“制造-废弃”线性模式，转向与自然代谢系统深度融合的生态文明范式。", "target_word": "代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林里的落叶，通过自然代谢变成了肥料。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里的物质代谢很快，水才能保持干净。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然界的物质代谢，让资源可以重复使用。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地里的微生物能加快有机物的代谢。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "tǔdì lǐ de wēishēngwù néng jiākuài yǒujīwù de dàixiè", "sentence_source": "generated"}, {"text": "木材埋在地里，代谢很慢，要很多年才能完成。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "mùcái mái zài dì lǐ, dàixiè hěn màn, yào hěn duō nián cái néng wánchéng", "sentence_source": "generated"}, {"text": "海洋里的物质代谢，需要阳光和合适的温度。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把落叶放进土里，能加快物质的代谢。", "target_word": "代谢", "complexity_tier": "T3", "furigana": "bǎ luòyè fàng jìn tǔ lǐ, néng jiākuài wùzhì de dàixiè", "sentence_source": "generated"}, {"text": "森林是地球上物质代谢最快的地方之一。", "target_word": "代谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新陈代谢", "label": "复合"}, {"form": "代謝", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自然环境中物质分解并循环再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd209268f-53f6-4de8-8192-9154cf70cf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢”指物质被分解并重新利用的过程，与“资源”搭配，符合句意。"}, {"text": "修辞", "is_correct": false, "explanation": "语义：资源不是修辞的过程，前文已用“视觉修辞”，此处不合。"}, {"text": "美学", "is_correct": false, "explanation": "搭配：“资源美学”不成立，“美学”不能用来修饰“资源”作定语。"}, {"text": "标签", "is_correct": false, "explanation": "语义：标签是符号，不是资源被分解的过程，与“过程”搭配不合。"}], "explanations": {"代谢": "“代谢”指物质被分解并重新利用的过程，与“资源”搭配，符合句意。", "修辞": "语义：资源不是修辞的过程，前文已用“视觉修辞”，此处不合。", "美学": "搭配：“资源美学”不成立，“美学”不能用来修饰“资源”作定语。", "标签": "语义：标签是符号，不是资源被分解的过程，与“过程”搭配不合。"}, "sentence_index": 0, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块铁在水里放了很久，代谢得很快。", "explanation": "这里应该用〈生锈〉。代谢指物质被分解并重新利用的过程，铁被锈蚀不是重新利用，不能用代谢来说。"}, {"text": "这台发电机每天代谢大量的煤。", "explanation": "这里应该用〈消耗〉。煤被烧掉是能源的消耗，不是物质在环境中被分解并重新利用，不能用代谢。"}, {"text": "这家工厂排出的废气让周围的空气代谢了。", "explanation": "这里应该用〈污染〉。废气使空气变脏是有害的改变，不是物质被分解并重新利用，代谢不能用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "“代谢”是过程，可以用“很慢”来描述其快慢，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会“很慢”，与句中描述的分解过程不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说“高”“低”，不说“很慢”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不存在快慢之分，句子说的是分解过程。"}], "explanations": {"代谢": "“代谢”是过程，可以用“很慢”来描述其快慢，符合句意。", "天气": "语义：天气不会“很慢”，与句中描述的分解过程不合。", "价格": "搭配：“价格”一般说“高”“低”，不说“很慢”。", "身高": "语义：身高不存在快慢之分，句子说的是分解过程。"}, "sentence_index": 6, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库的粮食代谢很充足，所以从不缺货。", "explanation": "这里应该用〈储备〉。代谢指物质被分解并重新利用的过程，不指存放的数量，用它说粮食充足是误用。"}, {"text": "这条马路的代谢很快，每天都要修补。", "explanation": "这里应该用〈磨损〉。代谢指物质被分解并重新利用的过程，马路的损耗需要修补，不能说代谢。"}, {"text": "这块电池的代谢很快，充一次电只能用两小时。", "explanation": "这里应该用〈耗电〉。电池放电是能量的消耗，不是物质被分解并重新利用，不能用代谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湿地里发生着一只物质代谢。", "corrected_sentence": "这片湿地里发生着一种物质代谢。", "error_description": "错误形式：“一只物质代谢”。正确形式：“一种物质代谢”。原因：“只”多用于动物或成对的物件，抽象过程名词“代谢”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草原的物质代谢的很快，植物长得很茂盛。", "corrected_sentence": "这片草原的物质代谢很快，植物长得很茂盛。", "error_description": "错误形式：「代谢的很快」。正确形式：「代谢很快」。原因：「很快」作谓语直接跟在主语「物质代谢」后，中间不能插入结构助词「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂化", "is_correct": true, "explanation": "复杂化指使事物变得复杂，与“简化”意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与“简化”没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存指留存不丢失，与“简化”没有反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大指使范围变大，不是“简化”的反义词。"}], "correct_answer": "复杂化", "explanations": {"复杂化": "复杂化指使事物变得复杂，与“简化”意思相反。", "研究": "研究指深入探讨，与“简化”没有反义关系。", "保存": "保存指留存不丢失，与“简化”没有反义关系。", "扩大": "扩大指使范围变大，不是“简化”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂化", "is_correct": true, "explanation": "复杂化指使事物变得复杂，与“简化”意思相反。"}, {"text": "打开", "is_correct": false, "explanation": "打开指使封闭的东西敞开，与“简化”没有反义关系。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰指美化外表，与“简化”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交流意见，与“简化”没有反义关系。"}], "correct_answer": "复杂化", "explanations": {"复杂化": "复杂化指使事物变得复杂，与“简化”意思相反。", "打开": "打开指使封闭的东西敞开，与“简化”没有反义关系。", "装饰": "装饰指美化外表，与“简化”没有反义关系。", "讨论": "讨论指交流意见，与“简化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把复杂的事物变得简单，减少不必要的部分。", "primary_collocate": null, "pronunciation": "jiǎn huà", "ipa": "tɕjɛn˨˩˦ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "简化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们应该简化这张复杂的地图。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把难懂的句子简化了。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司简化了复杂的办事手续。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这个故事简化一点儿。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太复杂的图案可以简化成几条线。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份报告简化成一页纸。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流程太长了，必须简化。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉字简化后，写起来更容易。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把复杂的计算简化成了三步。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "简化了", "label": "体标"}, {"form": "简化过", "label": "体标"}, {"form": "簡化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把复杂的事物变得简单，去掉多余部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425de479-e790-4eba-b065-e6117f93c8ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指把复杂的事物变简单，此处指把复杂的过程变成符号，符合语境。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：扩大与“简化”意思相反，“扩大为符号”不通。"}, {"text": "删除", "is_correct": false, "explanation": "配价：“删除”要求直接带宾语，不能用“为”引出结果。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量变多，不能用来说过程变成符号。"}], "explanations": {"简化": "简化指把复杂的事物变简单，此处指把复杂的过程变成符号，符合语境。", "扩大": "语义：扩大与“简化”意思相反，“扩大为符号”不通。", "删除": "配价：“删除”要求直接带宾语，不能用“为”引出结果。", "增加": "搭配：“增加”说数量变多，不能用来说过程变成符号。"}, "sentence_index": 0, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司简化了三分之一的员工，效率提高了。", "explanation": "这里应该用〈精简〉。精简指减少人员或机构，用于人员；简化指把复杂的事变简单，不能说“简化员工”。"}, {"text": "这个月我们简化了这块地的面积，现在小了不少。", "explanation": "这里应该用〈缩小〉。缩小指使面积变小，用于面积、范围；简化指把复杂的事变简单，不用来说面积变小。"}, {"text": "他简化了这杯水的温度，现在可以喝了。", "explanation": "这里应该用〈降低〉。降低指使温度、数量变低，用于温度、价格；简化指把复杂的事变简单，不说“简化温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指把复杂的报告变短，“成一页纸”是它的结果，符合句意。"}, {"text": "扩充", "is_correct": false, "explanation": "语义：扩充指增加内容使变多，与“简化”意思相反，不能说“扩充成一页纸”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰指美化外表，与报告变成一页纸无关。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、灯等，不能用于报告。"}], "explanations": {"简化": "简化指把复杂的报告变短，“成一页纸”是它的结果，符合句意。", "扩充": "语义：扩充指增加内容使变多，与“简化”意思相反，不能说“扩充成一页纸”。", "装饰": "语义：装饰指美化外表，与报告变成一页纸无关。", "点燃": "搭配：“点燃”用于火、灯等，不能用于报告。"}, "sentence_index": 6, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件简化了文件的大小，传输更快。", "explanation": "这里应该用〈压缩〉。压缩指减小体积，用于文件、空间；简化指把复杂的事变简单，不能用于说文件大小的减小。"}, {"text": "这次改革简化了办手续的时间。", "explanation": "这里应该用〈缩短〉。缩短指使时间变少，用于时间、距离；简化指把复杂的事变简单，不说“简化时间”。"}, {"text": "老师简化了作业里的错误。", "explanation": "这里应该用〈改正〉。改正指把错误改对；简化指把复杂的事变简单，不能用来说处理错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把这套规则简化。", "corrected_sentence": "他已经把这套规则简化了。", "error_description": "“把”字句中动词后面要有“了”或补语等成分，说明动作完成或结果；“简化”后应加“了”，说“简化了”，不能只说“把这套规则简化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你这些资料简化成一页纸。", "corrected_sentence": "请你把这些资料简化成一页纸。", "error_description": "“简化”是处置类动词，“这些资料”作受处置的宾语要放在动词前，需要用“把”引出，应说“请你把这些资料简化成一页纸”，漏掉“把”就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "批评者指对某人或某事提出负面评价、指出缺点或错误的人。", "primary_collocate": null, "pronunciation": "pī píng zhě", "ipa": "pʰi˥ pʰiŋ˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "批评者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "批评者说这个计划有很多问题。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位认真的批评者。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者的话有时很难听。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位批评者指出了书中的错误。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者们对新电影不太满意。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长很少听批评者的意见。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些批评者只说缺点，不说优点。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从一个批评者变成了朋友。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者提出的问题，我们要认真想一想。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批评者们", "label": "复数"}, {"form": "位", "label": "量词"}, {"form": "批評者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事提出负面评价、指出缺点错误的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425de479-e790-4eba-b065-e6117f93c8ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“指出”的主语应是能提出意见的人，“批评者”指提出负面评价、指出局限的人，最合适。"}, {"text": "符号", "is_correct": false, "explanation": "语义：符号不能“指出”问题，“指出”的主语要能发表意见，与“符号”不合。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是机构或场所，不能发表意见或“指出”局限，此处讲不通。"}, {"text": "吃瓜群众", "is_correct": false, "explanation": "语域：“吃瓜群众”是网络口语，与这段学术语境的书面语体不合。"}], "explanations": {"批评者": "正确：“指出”的主语应是能提出意见的人，“批评者”指提出负面评价、指出局限的人，最合适。", "符号": "语义：符号不能“指出”问题，“指出”的主语要能发表意见，与“符号”不合。", "工厂": "语义：工厂是机构或场所，不能发表意见或“指出”局限，此处讲不通。", "吃瓜群众": "语域：“吃瓜群众”是网络口语，与这段学术语境的书面语体不合。"}, "sentence_index": 0, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们俱乐部最忠实的批评者，每场比赛都大声为球队加油。", "explanation": "这里应该用〈支持者〉。“批评者”指提出批评意见的人，不会为球队加油；“支持者”才指支持并为之加油的人。"}, {"text": "比赛的批评者宣布了最后的结果。", "explanation": "这里应该用〈评判者〉。宣布比赛结果是评判者的职责；“批评者”只提出看法，不负责裁决。"}, {"text": "妈妈是我最热情的批评者，总是夸我做得好。", "explanation": "这里应该用〈鼓励者〉。“批评者”重在指出缺点，不会一味夸奖；总是夸我的人应是鼓励者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“听……的意见”的对象应是能提出意见的人，“批评者”符合。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能提出意见，“听植物的意见”讲不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不会提出意见，与“听……的意见”的语义不合。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：“老铁”是网络口语，不用于书面陈述“市长听取意见”的语境。"}], "explanations": {"批评者": "正确：“听……的意见”的对象应是能提出意见的人，“批评者”符合。", "植物": "语义：植物不能提出意见，“听植物的意见”讲不通。", "水果": "语义：水果不会提出意见，与“听……的意见”的语义不合。", "老铁": "语域：“老铁”是网络口语，不用于书面陈述“市长听取意见”的语境。"}, "sentence_index": 6, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这起事故的唯一批评者，法庭上他出庭作证，说明了当时的经过。", "explanation": "这里应该用〈证人〉。“批评者”指提出负面评价的人，不负责出庭作证；出庭说明当时经过的是证人。"}, {"text": "他是我们公司最优秀的批评者，每个月都超额完成销售任务。", "explanation": "这里应该用〈销售员〉。“批评者”指提出负面意见的人，不负责销售；超额完成销售任务的是销售员。"}, {"text": "她是这家医院的优秀批评者，每天认真为病人看病。", "explanation": "这里应该用〈医生〉。“批评者”指指出缺点或错误的人，不负责诊治病人；为病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们公司一只严厉的批评者。", "corrected_sentence": "他是我们公司一位严厉的批评者。", "error_description": "量词错误。“批评者”指人，量词应用“位”或“个”，“只”多用于动物，不能用来修饰人。应说“一位严厉的批评者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几只批评者都很认真。", "corrected_sentence": "这几位批评者都很认真。", "error_description": "量词错误。“批评者”指人，量词应用“位”，不能用“只”。应说“这几位批评者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
