INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12549, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或目光朝某个方向让人注意。", "primary_collocate": null, "pronunciation": "zhǐ chū", "ipa": "ʈʂɨ˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他伸手指出湖边的那只白鸟。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游指出远处那座山，请大家看。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在地图上指出了北京的位置。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明抬起手，指出树上的小鸟。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察指出小偷跑走的方向。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抬手指出远处的灯塔，让我看。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子指出天上的星星，大声说：“看！”", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机指出前面的路口，说要右转。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你在照片上指出哪个是你哥哥。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他指出了河对面的那座房子。", "target_word": "指出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指出了", "label": "完成体"}, {"form": "指出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用手指或目光朝某个方向，让别人注意到某处（具体动作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 导游 (Zipf 3.88), 远处 (Zipf 3.84), 那座 (Zipf 3.06)','sentence 3 above tier T1: 4 words above tier T1 (max 2): 小明 (Zipf 3.37), 抬起 (Zipf 3.75), 树上 (Zipf 3.82), 小鸟 (Zipf 3.85)']::text[], 'f3b13fca-7ff9-4ad7-86d0-6347cd2ffa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指出", "is_correct": true, "explanation": "正确：指出用手或目光朝某个方向让人注意，与“伸手”和“湖边的白鸟”的语境相符。"}, {"text": "撰写", "is_correct": false, "explanation": "语义：撰写指写作文字，与“伸手”的动作和“白鸟”这一实物都不相符。"}, {"text": "评价", "is_correct": false, "explanation": "搭配：评价的对象是人或作品，不能与“伸手”搭配来评价一只白鸟。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：翻译需要语言或文本作宾语，“白鸟”不是可以翻译的对象。"}], "explanations": {"指出": "正确：指出用手或目光朝某个方向让人注意，与“伸手”和“湖边的白鸟”的语境相符。", "撰写": "语义：撰写指写作文字，与“伸手”的动作和“白鸟”这一实物都不相符。", "评价": "搭配：评价的对象是人或作品，不能与“伸手”搭配来评价一只白鸟。", "翻译": "配价：翻译需要语言或文本作宾语，“白鸟”不是可以翻译的对象。"}, "sentence_index": 0, "correct_answer": "指出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明抬起手，指出给我树上的小鸟。", "explanation": "这里应该用〈指给〉。指出是及物动词，后面不能直接带“给我”这样的间接对象，表示指给某人看要用指给。"}, {"text": "小明抬起手，指出了树上小鸟的快乐。", "explanation": "这里应该用〈感受〉。指出是让人看见某样东西，快乐是心里的感受，不能用手指或目光指给别人看。"}, {"text": "小明抬起手，指出了那只小鸟的气味。", "explanation": "这里应该用〈闻到〉。指出是让人看见某样东西，气味不能用手指或目光指给别人看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指出", "is_correct": true, "explanation": "正确：指出表示用手指或目光让人注意天上的星星，与“大声说：看！”的语境相符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是遮掩起来不让人看见，与后面“大声说：看！”的意思相反。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：遗忘是忘记，与孩子大声让别人去看的动作相矛盾。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭多用于灯火，不用于星星，且与“大声说：看！”的语境不符。"}], "explanations": {"指出": "正确：指出表示用手指或目光让人注意天上的星星，与“大声说：看！”的语境相符。", "隐藏": "语义：隐藏是遮掩起来不让人看见，与后面“大声说：看！”的意思相反。", "遗忘": "语义：遗忘是忘记，与孩子大声让别人去看的动作相矛盾。", "熄灭": "搭配：熄灭多用于灯火，不用于星星，且与“大声说：看！”的语境不符。"}, "sentence_index": 6, "correct_answer": "指出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他指出了河对面的那座房子的声音。", "explanation": "这里应该用〈听到〉。指出是让人看见某样东西，声音不能用手指或目光指给别人看。"}, {"text": "他指出了河对面的那座房子的香味。", "explanation": "这里应该用〈闻到〉。指出是让人看见某样东西，香味不能用手指或目光指给别人看。"}, {"text": "他指出了河对面的那座房子的温暖。", "explanation": "这里应该用〈感到〉。温暖是感觉，不能用手指或目光指给别人看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师抬手指出得窗外的那只鸟。", "corrected_sentence": "老师抬手指出窗外的那只鸟。", "error_description": "错误在于“指出”后误加“得”。“得”只能接在动词后引出补语，这里没有补语，应删去“得”，写作“老师抬手指出窗外的那只鸟。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸抬手了指出河边的那只鸭子。", "corrected_sentence": "爸爸抬手指出河边的那只鸭子。", "error_description": "错误在于“了”放在了“指出”之前（“抬手了指出”）。“了”是完成标记，不能放在动词前面；“指出”是连写的复合动词，应删去“了”，写作“爸爸抬手指出河边的那只鸭子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
