INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "美学是一个哲学分支，探讨美、艺术以及审美体验的本质和规律。", "primary_collocate": null, "pronunciation": "měi xué", "ipa": "meɪ̯˨˩˦ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这位学者长期致力于美学研究，主张从美的本质与审美体验出发，重新审视视觉修辞的效力。", "target_word": "美学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "美学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "美学是哲学的一个分支。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大学里学美学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国古代的美学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美学研究什么是美。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对日本美学很感兴趣。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师给我们讲美学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美学告诉我们怎样欣赏艺术。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师需要懂一点美学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美學", "label": "繁体"}, {"form": "美学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究美、艺术和审美体验的哲学学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d2e93ab-0075-4fa4-8695-09f8dab38044') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美学", "is_correct": true, "explanation": "正确：美学研究美的本质与审美体验，与句中“美的本质与审美体验”相符。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成与变化，与美的本质和审美体验无关。"}, {"text": "地质学", "is_correct": false, "explanation": "语义：地质学研究地球的构造与历史，与美的本质和审美体验无关。"}, {"text": "人口学", "is_correct": false, "explanation": "语义：人口学研究人口的结构与变动，与美的本质和审美体验无关。"}], "explanations": {"美学": "正确：美学研究美的本质与审美体验，与句中“美的本质与审美体验”相符。", "化学": "语义：化学研究物质的组成与变化，与美的本质和审美体验无关。", "地质学": "语义：地质学研究地球的构造与历史，与美的本质和审美体验无关。", "人口学": "语义：人口学研究人口的结构与变动，与美的本质和审美体验无关。"}, "sentence_index": 0, "correct_answer": "美学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌让人感到一种美学。", "explanation": "这里应该用〈美感〉。美学是学科名称，不能指人感受到的美，应说“美感”。"}, {"text": "这家博物馆收藏了很多美学作品。", "explanation": "这里应该用〈美术〉。美学是研究美的学问，不指艺术作品本身，收藏的画作要说“美术作品”。"}, {"text": "这座桥修得很美学，大家都喜欢。", "explanation": "这里应该用〈美观〉。美学是学科，不能用来形容桥的外观，应说“美观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美学", "is_correct": true, "explanation": "正确：日本美学指日本的审美理论与艺术研究，能与“感兴趣”搭配。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“感兴趣”的对象一般是学问或事物，不能说“对日本眼泪感兴趣”。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：发烧是症状，不能作为“感兴趣”的对象。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：感冒是疾病，不能作为“感兴趣”的对象。"}], "explanations": {"美学": "正确：日本美学指日本的审美理论与艺术研究，能与“感兴趣”搭配。", "眼泪": "搭配：“感兴趣”的对象一般是学问或事物，不能说“对日本眼泪感兴趣”。", "发烧": "搭配：发烧是症状，不能作为“感兴趣”的对象。", "感冒": "搭配：感冒是疾病，不能作为“感兴趣”的对象。"}, "sentence_index": 6, "correct_answer": "美学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们正在美学校园的环境。", "explanation": "这里应该用〈美化〉。美学是学科名称，不能作动词表示“使…变美”，美化校园要说“美化”。"}, {"text": "她每周都去美学护理皮肤。", "explanation": "这里应该用〈美容院〉。美学是学科名称，不能指护理皮肤的场所，应说“美容院”。"}, {"text": "这位明星有一副让人羡慕的美学。", "explanation": "这里应该用〈美貌〉。美学是学科，不能指容貌，应说“美貌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后专门美学。", "corrected_sentence": "他大学毕业后专门研究美学。", "error_description": "漏掉了动词“研究”。“专门”修饰的动词要说出来，应说“专门研究美学”；只说“专门美学”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲美学讲很生动。", "corrected_sentence": "他讲美学讲得很生动。", "error_description": "漏掉了补语前的“得”。“动词＋宾语＋动词＋得＋补语”的结构中间必须有“得”，不能说“讲很生动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd090b00c-c1ac-4f2e-a454-4e52eb5c893c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
