INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "废料指在生产或使用过程中产生的、没有用途的剩余材料或物品。", "primary_collocate": null, "pronunciation": "fèi liào", "ipa": "fei˥˩ liɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "废料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂每天都会产生很多废料。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把废料放进大箱子里。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废料可以再做成新的东西。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地上的废料要分类处理。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用旧木头废料做了一把椅子。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把废料运到了远处的工厂。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废料太多，院子里都放不下了。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司买废料来做纸。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理废料需要花很多钱。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廢料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：生产或使用中剩下的无用材料（处理废料）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425de479-e790-4eba-b065-e6117f93c8ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废料", "is_correct": true, "explanation": "“废料”指没用的剩余材料，“全球废料贸易”是常见的说法。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能作为贸易的对象，“全球年龄贸易”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用于“贸易”，不能说“全球颜色贸易”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能进行贸易，“全球天气贸易”没有意义。"}], "explanations": {"废料": "“废料”指没用的剩余材料，“全球废料贸易”是常见的说法。", "年龄": "语义：“年龄”不能作为贸易的对象，“全球年龄贸易”说不通。", "颜色": "搭配：“颜色”不能用于“贸易”，不能说“全球颜色贸易”。", "天气": "语义：“天气”不能进行贸易，“全球天气贸易”没有意义。"}, "sentence_index": 0, "correct_answer": "废料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇论文是很好的废料，大家都很喜欢。", "explanation": "这里应该用〈作品〉。废料指没用的剩余材料，好的论文不能说是废料，应说作品。"}, {"text": "他是班上的废料，成绩总是第一。", "explanation": "这里应该用〈优等生〉。废料指没用的剩余材料，不能用来指人，应说优等生。"}, {"text": "工厂买了一批新废料，效率很高。", "explanation": "这里应该用〈设备〉。废料指没有用途的剩余材料，不能买来提高生产效率，应说“设备”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废料", "is_correct": true, "explanation": "“废料”可以用卡车运输，符合“卡车把……运到了远处的工厂”的语境。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：卡车不能运输阳光，“卡车把阳光运到了工厂”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是实物，不能用卡车运到工厂。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”不能被卡车运输，“运到工厂”不能与考试搭配。"}], "explanations": {"废料": "“废料”可以用卡车运输，符合“卡车把……运到了远处的工厂”的语境。", "阳光": "语义：卡车不能运输阳光，“卡车把阳光运到了工厂”说不通。", "歌曲": "语义：歌曲不是实物，不能用卡车运到工厂。", "考试": "搭配：“考试”不能被卡车运输，“运到工厂”不能与考试搭配。"}, "sentence_index": 6, "correct_answer": "废料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个厨师做菜用的废料很新鲜。", "explanation": "这里应该用〈食材〉。废料是没用的剩余材料，不能用来形容新鲜的食物。"}, {"text": "妈妈做的废料很好吃。", "explanation": "这里应该用〈饭菜〉。废料没有用处，不能说做出来的东西很好吃。"}, {"text": "这筐废料很甜，大家都爱吃。", "explanation": "这里应该用〈水果〉。废料没有用途，不能说甜、让人爱吃，这些话只用于水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工地上有三只废料，需要尽快清理。", "corrected_sentence": "工地上有三堆废料，需要尽快清理。", "error_description": "量词错误：“废料”的量词要用“堆”或“块”，“只”多用于动物等。应说“三堆废料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里的废料堆得很甜了。", "corrected_sentence": "院子里的废料堆得很高了。", "error_description": "形容词搭配错误：“废料”堆起来说“高”，不说“甜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b917c6-72a7-4a18-9138-303f699cf318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
