INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指人与人之间在地位、权利、机会等方面没有差别。", "primary_collocate": null, "pronunciation": "píng děng", "ipa": "pʰiŋ˧˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "法律面前，人人平等。", "target_word": "平等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师对每个学生都很平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男人和女人应该平等。", "target_word": "平等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要平等地对待每个人。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样对孩子们不平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这家公司，大家的机会是平等的。", "target_word": "平等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子和大人应该平等相处。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，兄弟之间要平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平等的关系让我们成了好朋友。", "target_word": "平等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望得到平等的机会。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不平等", "label": "复合"}, {"form": "平等地", "label": "复合"}, {"form": "男女平等", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：人与人在地位、权利、机会上没有差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“人人平等”说明法律面前人人地位相同，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：法律面前讲的是地位与权利，“聪明”说智力，与句意不合。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”形容外貌，与法律面前的地位和权利无关。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体状况，与法律面前的地位和权利无关。"}], "explanations": {"平等": "正确：“人人平等”说明法律面前人人地位相同，符合句意。", "聪明": "语义：法律面前讲的是地位与权利，“聪明”说智力，与句意不合。", "美丽": "体貌：“美丽”形容外貌，与法律面前的地位和权利无关。", "健康": "语义：“健康”说身体状况，与法律面前的地位和权利无关。"}, "sentence_index": 0, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两根绳子的粗细很平等。", "explanation": "这里应该用〈均匀〉。平等指人在地位、权利上的相同；粗细一致要用均匀。"}, {"text": "蛋糕要平等地切成三份。", "explanation": "这里应该用〈平均〉。平等指人与人之间地位、权利相同，切分物品要用平均。"}, {"text": "这两条边的长度平等。", "explanation": "这里应该用〈相等〉。平等不用于说明长度或数量的相同，长度相同要用相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“平等相处”表示双方地位相同地交往，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来说两代人“高大地相处”。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“应该相处”的要求相反。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指经济条件，与人际相处的方式无关。"}], "explanations": {"平等": "正确：“平等相处”表示双方地位相同地交往，符合句意。", "高大": "体貌：“高大”形容身材，不能用来说两代人“高大地相处”。", "陌生": "语义：“陌生”指彼此不熟悉，与“应该相处”的要求相反。", "富裕": "语义：“富裕”指经济条件，与人际相处的方式无关。"}, "sentence_index": 6, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家的帽子很平等。", "explanation": "这里应该用〈相同〉。平等指地位、权利相同，不用来描述物品。"}, {"text": "两个人的想法很平等。", "explanation": "这里应该用〈相同〉。想法的相同要说相同，平等指地位、权利的相同。"}, {"text": "他们的身高很平等。", "explanation": "这里应该用〈相近〉。平等指地位、权利相同；身高接近要用相近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种规定对女性没平等。", "corrected_sentence": "这种规定对女性不平等。", "error_description": "错误：用“没”否定形容词“平等”。正确：应用“不”，说“不平等”。否定形容词要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩的地位很平等地。", "corrected_sentence": "我们俩的地位很平等。", "error_description": "错误：句末多加了“地”。“平等地”是状语形式，要修饰后面的动词，不能作谓语结尾。正确：应说“我们俩的地位很平等。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
