INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示已经发生或已经达到某种状态。", "primary_collocate": null, "pronunciation": "yǐ rán", "ipa": "i˨˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "由此，一个原本功能性的设计，已然升华为当代生态意识的文化镜像，折射出技术理想、消费现实与道德诉求之间的张力。", "target_word": "已然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天已然黑了，我们该回家了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已然成为这家公司的经理。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天已然来到，花都开了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题已然解决，不用再担心。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家已然做好了准备。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她已然忘记了那件小事。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车已然开走了，我们没赶上。", "target_word": "已然", "complexity_tier": "T3", "furigana": "chē yǐrán kāizǒu le, wǒmen méi gǎnshàng.", "sentence_source": "generated"}, {"text": "城市已然变得很热闹。", "target_word": "已然", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛已然结束，观众慢慢离开了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "已然：副词，表示事情已经发生或已经达到某种状态，用在动词或形容词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3b13fca-7ff9-4ad7-86d0-6347cd2ffa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然是副词，表示已经发生或已经达到某种状态。"}, {"text": "依然", "is_correct": false, "explanation": "依然 yīrán 与 已然 yǐrán 第一个音节声调不同（第一声与第三声），意思是仍旧，不表示已经发生。"}, {"text": "怡然", "is_correct": false, "explanation": "怡然 yírán 与 已然 yǐrán 第一个音节声调不同（第二声与第三声），意思是安适愉快的样子。"}, {"text": "易燃", "is_correct": false, "explanation": "易燃 yìrán 与 已然 yǐrán 第一个音节声调不同（第四声与第三声），意思是容易燃烧。"}], "explanations": {"已然": "正确答案。已然是副词，表示已经发生或已经达到某种状态。", "依然": "依然 yīrán 与 已然 yǐrán 第一个音节声调不同（第一声与第三声），意思是仍旧，不表示已经发生。", "怡然": "怡然 yírán 与 已然 yǐrán 第一个音节声调不同（第二声与第三声），意思是安适愉快的样子。", "易燃": "易燃 yìrán 与 已然 yǐrán 第一个音节声调不同（第四声与第三声），意思是容易燃烧。"}, "sentence_index": null, "correct_answer": "已然"}, "level_3": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然表示设计已经升华为文化镜像，与“由此”后面的结论相符。"}, {"text": "尚未", "is_correct": false, "explanation": "体貌：尚未表示动作还没有实现，与“折射出”所述的既成结果相矛盾。"}, {"text": "必将", "is_correct": false, "explanation": "语义：必将表示未来必然发生，与句中已经成为结果的叙述不合。"}, {"text": "不必", "is_correct": false, "explanation": "语义：不必表示没有必要，与“原本功能性的设计”已经发生变化这一既成事实不合。"}], "explanations": {"已然": "正确答案。已然表示设计已经升华为文化镜像，与“由此”后面的结论相符。", "尚未": "体貌：尚未表示动作还没有实现，与“折射出”所述的既成结果相矛盾。", "必将": "语义：必将表示未来必然发生，与句中已经成为结果的叙述不合。", "不必": "语义：不必表示没有必要，与“原本功能性的设计”已经发生变化这一既成事实不合。"}, "sentence_index": 0, "correct_answer": "已然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已然明天去北京。", "explanation": "这里应该用〈将〉。已然表示已经发生或已经达到的状态，不能用来说尚未发生的将来行为。"}, {"text": "我每天已然吃早饭，身体很好。", "explanation": "这里应该用〈总是〉。已然表示某件事已经发生并完成，不用于每天重复的习惯。"}, {"text": "请你已然坐下来吧。", "explanation": "这里是请求，应直接说“请你坐下来吧”。已然表示已经达到的状态，不能用于要求对方去做的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然表示她已经忘记了那件小事，与后面的“了”所表示的完成相符。"}, {"text": "将", "is_correct": false, "explanation": "体貌：将表示将来，与后面的“了”所表示的完成相冲突。"}, {"text": "没", "is_correct": false, "explanation": "语义：没否定动作，与“了”所表示的已完成语义相矛盾。"}, {"text": "正", "is_correct": false, "explanation": "体貌：正表示动作进行中，与“了”所表示的完成相冲突。"}], "explanations": {"已然": "正确答案。已然表示她已经忘记了那件小事，与后面的“了”所表示的完成相符。", "将": "体貌：将表示将来，与后面的“了”所表示的完成相冲突。", "没": "语义：没否定动作，与“了”所表示的已完成语义相矛盾。", "正": "体貌：正表示动作进行中，与“了”所表示的完成相冲突。"}, "sentence_index": 6, "correct_answer": "已然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还在吃饭，已然吃完了。", "explanation": "已然表示动作已经完成，与“还在吃饭”所说的正在进行相矛盾。"}, {"text": "如果天气好，我们已然去公园。", "explanation": "这里应该用〈要〉。已然表示已经发生的事，与“如果天气好”这一尚未确定的假设相矛盾，应改用将来时。"}, {"text": "这件事我已然还没做完。", "explanation": "已然表示已经发生，与“还没做完”的否定结果相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很已然走了，我们别等了。", "corrected_sentence": "他已然走了，我们别等了。", "error_description": "错误形式“他很已然走了”在副词“已然”前加了程度副词“很”，副词不能再由“很”修饰。正确形式“他已然走了”直接用“已然”修饰动词“走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子已然的睡着了。", "corrected_sentence": "孩子已然睡着了。", "error_description": "错误形式“孩子已然的睡着了”在副词“已然”后多加了“的”，副词后不能加“的”。正确形式“孩子已然睡着了”直接用“已然”修饰动词“睡着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd040b09-4945-4685-bdd7-c85afdc8d767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
