INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12559, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻通过某种方式显示出（思想、情感或特征）。", "primary_collocate": null, "pronunciation": "zhé shè chū", "ipa": "ʈʂɤ˧˥ ʂɤ˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "由此，一个原本功能性的设计，已然升华为当代生态意识的文化镜像，折射出技术理想、消费现实与道德诉求之间的张力。", "target_word": "折射出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件小事折射出他的善良。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的画折射出他的心情。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影折射出社会的变化。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话折射出对工作的不满。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些数字折射出城市的发展。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笑容折射出内心的快乐。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一本旧日记折射出那个年代的生活。", "target_word": "折射出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛折射出球队的问题。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上新增的菜品折射出人们口味的变化。", "target_word": "折射出", "complexity_tier": "T3", "furigana": "cài dān shàng xīn zēng de cài pǐn zhé shè chū rén men kǒu wèi de biàn huà", "sentence_source": "generated"}], "morphological_forms": [{"form": "折射出了", "label": "体标"}, {"form": "折射出来", "label": "复合"}, {"form": "折射率", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：比喻事物显示出背后的思想、情感或特征", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折射出", "is_correct": true, "explanation": "正确：“折射出”可以带“理想、现实、诉求”这类抽象内容，表示透露出其中的张力。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”的对象是具体的东西，不能说“摘下技术理想”。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”多用于具体器物，不能用于“理想”。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”说把东西吞下去，与“理想、现实、诉求”并列的语义不合。"}], "explanations": {"折射出": "正确：“折射出”可以带“理想、现实、诉求”这类抽象内容，表示透露出其中的张力。", "摘下": "搭配：“摘下”的对象是具体的东西，不能说“摘下技术理想”。", "打碎": "搭配：“打碎”多用于具体器物，不能用于“理想”。", "吃掉": "语义：“吃掉”说把东西吞下去，与“理想、现实、诉求”并列的语义不合。"}, "sentence_index": 0, "correct_answer": "折射出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在橱窗里折射出新产品。", "explanation": "这里应该用〈展示〉。展示是把东西摆出来给人看；折射出是通过现象透露思想或情况，不能用来摆放商品。"}, {"text": "博物馆折射出许多古代文物。", "explanation": "这里应该用〈陈列〉。陈列是把物品摆放出来供人参观；折射出不用于具体文物的展出。"}, {"text": "这台机器折射出刺耳的噪音。", "explanation": "这里应该用〈发出〉。发出指声音由物体散出；折射出是比喻地显示思想、情感或特征，不用于声音的发出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折射出", "is_correct": true, "explanation": "正确：“笑容”能折射出内心的情感，符合句意。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”的对象是衣物，不能说“穿上内心的快乐”。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉内心的快乐”与“笑容”所表露的情绪相反。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损的物件，不能用于“快乐”。"}], "explanations": {"折射出": "正确：“笑容”能折射出内心的情感，符合句意。", "穿上": "搭配：“穿上”的对象是衣物，不能说“穿上内心的快乐”。", "扔掉": "语义：“扔掉内心的快乐”与“笑容”所表露的情绪相反。", "修补": "搭配：“修补”用于破损的物件，不能用于“快乐”。"}, "sentence_index": 6, "correct_answer": "折射出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电子屏幕折射出今天的气温。", "explanation": "这里应该用〈显示〉。显示是直接呈现数据、内容；折射出是间接透露思想或情况，不能用于屏幕显示气温。"}, {"text": "舞台上折射出精彩的表演。", "explanation": "这里应该用〈呈现〉。呈现指表演、景象等具体展现在人前；折射出不用于这类具体展现。"}, {"text": "展柜里折射出一排精致的茶具。", "explanation": "这里应该用〈摆出〉。摆出指把物件摆放出来；折射出不能用于具体物件的摆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事被折射出社会的问题。", "corrected_sentence": "这件事折射出社会的问题。", "error_description": "错误：多用了“被”。正确：“折射出”是主动式，表示通过事情显示出问题，不加“被”，应说“这件事折射出社会的问题。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告折射出去行业的问题。", "corrected_sentence": "这份报告折射出行业的问题。", "error_description": "错误：“折射出”后多加了补语“去”。正确：“折射出”已表示显示出，后面不加“去”，应说“这份报告折射出行业的问题。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心中向往的美好目标相对。"}, {"text": "石头", "is_correct": false, "explanation": "石头：与“理想”没有反义关系，是具体的岩石，与此义无关。"}, {"text": "河流", "is_correct": false, "explanation": "河流：与“理想”没有反义关系，是自然地理事物，与此义无关。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子：与“理想”没有反义关系，是家具，与此义无关。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心中向往的美好目标相对。", "石头": "石头：与“理想”没有反义关系，是具体的岩石，与此义无关。", "河流": "河流：与“理想”没有反义关系，是自然地理事物，与此义无关。", "桌子": "桌子：与“理想”没有反义关系，是家具，与此义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心中向往的美好目标相对。"}, {"text": "房子", "is_correct": false, "explanation": "房子：与“理想”没有反义关系，是具体的建筑，与此义无关。"}, {"text": "大海", "is_correct": false, "explanation": "大海：与“理想”没有反义关系，是自然地理事物，与此义无关。"}, {"text": "书包", "is_correct": false, "explanation": "书包：与“理想”没有反义关系，是装书的用品，与此义无关。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心中向往的美好目标相对。", "房子": "房子：与“理想”没有反义关系，是具体的建筑，与此义无关。", "大海": "大海：与“理想”没有反义关系，是自然地理事物，与此义无关。", "书包": "书包：与“理想”没有反义关系，是装书的用品，与此义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心中希望实现的美好目标或未来图景", "primary_collocate": null, "pronunciation": "lǐ xiǎng", "ipa": "li˨˩˦ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的理想是当医生。", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为理想努力工作。", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人都有自己的理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她终于实现了理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人要有远大的理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现实和理想不一样。", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候，我的理想是开飞机。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了理想，他离开了家乡。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的理想是教出好学生。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有什么理想？", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "理想主义", "label": "复合"}, {"form": "理想化", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：心中希望实现的美好目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "理想：心中希望实现的美好目标，与“当医生”搭配，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不是人生的目标，“我的工资是当医生”句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能作为“当医生”的目标。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，不是要去实现的志向，“我的名字是当医生”句意不通。"}], "explanations": {"理想": "理想：心中希望实现的美好目标，与“当医生”搭配，句意通顺。", "工资": "语义：“工资”是劳动报酬，不是人生的目标，“我的工资是当医生”句意不通。", "身高": "体貌：“身高”是身体特征，不能作为“当医生”的目标。", "名字": "语义：“名字”是称呼，不是要去实现的志向，“我的名字是当医生”句意不通。"}, "sentence_index": 0, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这周我的理想是复习数学。", "explanation": "这里应该用〈计划〉。理想指长远的美好目标，不用来安排一周之内的具体任务。"}, {"text": "她终于把理想摆在了桌子上。", "explanation": "这里应该用〈书〉。理想是抽象的心中目标，不能摆在桌面上；摆放实物要用书。"}, {"text": "她终于实现了一颗理想。", "explanation": "量词不对。理想是抽象名词，应该用“个”或“种”，“颗”用于圆粒状的东西，不能修饰理想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "理想：这里指心中向往的人生目标，与“开飞机”搭配，句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的重量，不能作为“是开飞机”的目标。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不是可以去实现的志向，“我的脾气是开飞机”句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是岁数，不是希望达到的目标，“我的年龄是开飞机”句意不通。"}], "explanations": {"理想": "理想：这里指心中向往的人生目标，与“开飞机”搭配，句意通顺。", "体重": "体貌：“体重”是身体的重量，不能作为“是开飞机”的目标。", "脾气": "语义：“脾气”指性情，不是可以去实现的志向，“我的脾气是开飞机”句意不通。", "年龄": "语义：“年龄”是岁数，不是希望达到的目标，“我的年龄是开飞机”句意不通。"}, "sentence_index": 6, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的理想是今晚吃火锅。", "explanation": "这里应该用〈想法〉。理想指长远的美好目标，不用来指今晚的安排。"}, {"text": "这次的理想是打扫教室。", "explanation": "这里应该用〈任务〉。理想指长远的追求，不用来指一次性的具体工作。"}, {"text": "我的理想是明天考试及格。", "explanation": "这里应该用〈愿望〉。理想指长远的人生目标，不用于眼前的短期心愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应该有一条理想。", "corrected_sentence": "每个人都应该有一个理想。", "error_description": "量词错误：“理想”是抽象名词，应该用量词“个”，“条”用于细长的东西，不能修饰“理想”。正确说法是“一个理想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有远大的理想的。", "corrected_sentence": "他有远大的理想。", "error_description": "错误：句末多加了“的”。正确：应说“他有远大的理想。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
