INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们想要达到某个目标或希望满足某种需要的想法、要求。", "primary_collocate": null, "pronunciation": "sù qiú", "ipa": "su˥˩ tɕʰioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "由此，一个原本功能性的设计，已然升华为当代生态意识的文化镜像，折射出技术理想、消费现实与道德诉求之间的张力。", "target_word": "诉求", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人们提出了合理的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司认真听取了员工的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的诉求其实很简单。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要尽快回应市民的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们通过信箱表达诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大家的诉求写在了本子上。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个诉求很正常，应该得到重视。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民的诉求终于得到了解决。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "利益诉求", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：人们提出的目标或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诉求", "is_correct": true, "explanation": "sù qiú 为正确答案，指人们提出的要求或希望。"}, {"text": "送球", "is_correct": false, "explanation": "sòng 与 sù 韵母不同（ong 与 u），送球指把球传给别人，与“诉求”不同。"}, {"text": "所求", "is_correct": false, "explanation": "suǒ（第三声）与 sù（第四声）声调不同，所求指想要得到的东西，与“诉求”不同。"}, {"text": "搜求", "is_correct": false, "explanation": "sōu（第一声）与 sù 韵母和声调都不同，搜求指寻找搜集，与“诉求”不同。"}], "explanations": {"诉求": "sù qiú 为正确答案，指人们提出的要求或希望。", "送球": "sòng 与 sù 韵母不同（ong 与 u），送球指把球传给别人，与“诉求”不同。", "所求": "suǒ（第三声）与 sù（第四声）声调不同，所求指想要得到的东西，与“诉求”不同。", "搜求": "sōu（第一声）与 sù 韵母和声调都不同，搜求指寻找搜集，与“诉求”不同。"}, "sentence_index": null, "correct_answer": "诉求"}, "level_3": {"options": [{"text": "诉求", "is_correct": true, "explanation": "诉求：指人们提出的要求和希望，与“道德”搭配，句意通顺。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”是空间的大小，不是价值或要求，“道德面积”句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，与“道德”之间的张力无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“道德”不能与“颜色”组合成可以产生张力的对象，搭配不当。"}], "explanations": {"诉求": "诉求：指人们提出的要求和希望，与“道德”搭配，句意通顺。", "面积": "语义：“面积”是空间的大小，不是价值或要求，“道德面积”句意不通。", "体温": "语义：“体温”是身体的温度，与“道德”之间的张力无关，句意不通。", "颜色": "搭配：“道德”不能与“颜色”组合成可以产生张力的对象，搭配不当。"}, "sentence_index": 0, "correct_answer": "诉求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盘菜的诉求很辣。", "explanation": "这里应该用〈味道〉。诉求指人想要达到的目标或要求，不用来描述菜的味道。"}, {"text": "他提出了一杯诉求。", "explanation": "量词不对。诉求是抽象名词，应该用“项”或“个”，“杯”用于盛放液体的容器，不能修饰诉求。"}, {"text": "学校发出了一份诉求。", "explanation": "这里应该用〈通知〉。诉求是提出者的要求，由学校发出、用于告知的文件应说“通知”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诉求", "is_correct": true, "explanation": "诉求：指想要得到的要求或希望，可以“表达”，句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不是可以表达的内容，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体的高度，不能被“表达”，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“表达”要求带可以表述的内容，不能带“汽车”作宾语。"}], "explanations": {"诉求": "诉求：指想要得到的要求或希望，可以“表达”，句意通顺。", "体重": "语义：“体重”是身体的重量，不是可以表达的内容，句意不通。", "身高": "语义：“身高”是身体的高度，不能被“表达”，句意不通。", "汽车": "配价：“表达”要求带可以表述的内容，不能带“汽车”作宾语。"}, "sentence_index": 6, "correct_answer": "诉求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说出了迟到的诉求。", "explanation": "这里应该用〈理由〉。诉求指想要得到的东西或希望达成的事，不用来指解释原因。"}, {"text": "老师给出了正确的诉求。", "explanation": "这里应该用〈回答〉。诉求是提出的要求，不是对问题的解答。"}, {"text": "这道题的诉求是三。", "explanation": "这里应该用〈答案〉。诉求指人们想要得到的东西，不用来指题目的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们提出了一条正当的诉求。", "corrected_sentence": "学生们提出了一项正当的诉求。", "error_description": "量词错误：“诉求”应该用量词“项”，“条”用于细长的东西，不能修饰“诉求”。正确说法是“一项正当的诉求”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民把诉求讲很清楚。", "corrected_sentence": "村民把诉求讲得很清楚。", "error_description": "补语错误：“讲”后带程度补语“很清楚”时，要用“得”连接，说“讲得很清楚”；漏掉“得”，说“讲很清楚”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
