INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示把某人或某事当作最重要的部分。", "primary_collocate": null, "pronunciation": "wéi zhǔ", "ipa": "weɪ˧˥ ʈʂu˨˩", "syllable_count": 2, "sentences": [{"text": "它见证了从早期以清理行动为主的“浅绿”思潮，向强调系统变革的“深绿”哲学的转型。", "target_word": "为主", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我的早饭以面包为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的菜以辣为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司的客人以年轻人为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天他吃饭以热汤为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书以图片为主，字很少。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作以写文章为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喝的饮料以茶为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个班的学生以女生为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学汉语应该以听说为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以……为主", "label": "固定格式"}], "register": "中性", "sense_fingerprint": "为主：以某人或某事为最重要、占多数的部分（以……为主）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8325ef-34ef-4733-8f7d-abd5f4dba8a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为主", "is_correct": true, "explanation": "「为主」与“以清理行动”构成“以……为主”，表示清理行动占主要地位，符合句意。"}, {"text": "为止", "is_correct": false, "explanation": "语义：「以……为止」表示以某事为终点，不能用来修饰“思潮”的内容。"}, {"text": "为期", "is_correct": false, "explanation": "配价：「为期」后须接时间段，不能接“清理行动”。"}, {"text": "为难", "is_correct": false, "explanation": "语义：「为难」表示使人感到困难，与句中描述不符。"}], "explanations": {"为主": "「为主」与“以清理行动”构成“以……为主”，表示清理行动占主要地位，符合句意。", "为止": "语义：「以……为止」表示以某事为终点，不能用来修饰“思潮”的内容。", "为期": "配价：「为期」后须接时间段，不能接“清理行动”。", "为难": "语义：「为难」表示使人感到困难，与句中描述不符。"}, "sentence_index": 0, "correct_answer": "为主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天的饭以天气为主。", "explanation": "这里的〈为主〉要求后接饭的主要构成，“天气”不是饭的构成；表示以天气为依据时应说〈以……为准〉。"}, {"text": "我们公司的客人以昨天为主。", "explanation": "这里的〈为主〉要求后接客人的主要构成，“昨天”是时间；表示以时间为依据时应说〈以……为准〉。"}, {"text": "我们公司的客人以下雨为主。", "explanation": "这里的〈为主〉要求后接客人的主要构成，“下雨”是天气；表示以天气为依据时应说〈以……为准〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为主", "is_correct": true, "explanation": "「为主」表示以写文章为主要内容，符合句意。"}, {"text": "为敌", "is_correct": false, "explanation": "语义：「为敌」表示把某事当作敌人，与“工作”的描述不符。"}, {"text": "为祸", "is_correct": false, "explanation": "语义：「为祸」指造成灾害，不能用来说明工作的内容。"}, {"text": "为仇", "is_correct": false, "explanation": "语义：「为仇」表示视为仇敌，与正常工作的描述不符。"}], "explanations": {"为主": "「为主」表示以写文章为主要内容，符合句意。", "为敌": "语义：「为敌」表示把某事当作敌人，与“工作”的描述不符。", "为祸": "语义：「为祸」指造成灾害，不能用来说明工作的内容。", "为仇": "语义：「为仇」表示视为仇敌，与正常工作的描述不符。"}, "sentence_index": 6, "correct_answer": "为主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学汉语应该以天气为主。", "explanation": "这里的〈为主〉要求后接学习的主要内容，“天气”不是学习内容；表示依据时应说〈以……为准〉。"}, {"text": "学汉语应该以桌子为主。", "explanation": "这里的〈为主〉要求后接学习的主要内容，“桌子”是物品，不是学习内容；表示以某物为依据时应说〈以……为准〉。"}, {"text": "学汉语应该以中午为主。", "explanation": "这里的〈为主〉要求后接学习的主要内容，“中午”是时间；表示以时间为依据时应说〈以……为准〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家的晚饭蔬菜为主。", "corrected_sentence": "我们家的晚饭以蔬菜为主。", "error_description": "“以……为主”的格式中不能省略“以”，应说“以蔬菜为主”，不能说“蔬菜为主”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的活动用唱歌为主。", "corrected_sentence": "我们班的活动以唱歌为主。", "error_description": "“以……为主”中的介词应为“以”，不能用“用”代替，应说“以唱歌为主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
