INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12571, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "混合、加入其中，成为整体的一部分。", "primary_collocate": null, "pronunciation": "róng rù", "ipa": "ɻʊŋ˧˥ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "他很快融入了新的班级。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想尽快融入这个城市的生活。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌融入了很多民族音乐。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白糖慢慢融入了热茶里。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师把新办法融入课堂里。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水融入大海，再也分不开了。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友很想融入我们的圈子。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音融入了合唱里。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事已经融入了我们的团队。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把自己的感情融入每一幅画。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "融入了", "label": "体标"}, {"form": "融入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "混合或加入某个整体之中，成为其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8325ef-34ef-4733-8f7d-abd5f4dba8a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融入", "is_correct": true, "explanation": "正确。“融入”表示进入某个整体并成为其中一部分，“很快融入了新的班级”句意通顺。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪的动作，不能用于人与班级之间的关系。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使物体掉落，与“很快……新的班级”的语义不相容。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”要求可擦拭的具体物体作宾语，班级是集体，不能被擦。"}], "explanations": {"融入": "正确。“融入”表示进入某个整体并成为其中一部分，“很快融入了新的班级”句意通顺。", "煮": "语义：“煮”是烹饪的动作，不能用于人与班级之间的关系。", "摔": "语义：“摔”指使物体掉落，与“很快……新的班级”的语义不相容。", "擦": "配价：“擦”要求可擦拭的具体物体作宾语，班级是集体，不能被擦。"}, "sentence_index": 0, "correct_answer": "融入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把钱融入了信封。", "explanation": "这里应该用〈放入〉。融入指混合或加入某个整体、成为其中一部分，不用于把东西放进容器。"}, {"text": "我的手机融入了口袋里。", "explanation": "这里应该用〈放进〉。融入指进入某个整体并成为其中一部分，把手机放进口袋应说放进。"}, {"text": "我把行李融入了汽车。", "explanation": "这里应该用〈搬进〉。融入指成为某个整体的一部分，把行李搬进车里应说搬进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融入", "is_correct": true, "explanation": "正确。“外国朋友很想融入我们的圈子”表示希望进入这个集体并成为其中一员，句意通顺。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连接布料，不能用于人与圈子之间的关系。"}, {"text": "削", "is_correct": false, "explanation": "配价：“削”要求可削的物体作宾语，圈子是人际集体，不能被削。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“想……我们的圈子”的愿望语义相反。"}], "explanations": {"融入": "正确。“外国朋友很想融入我们的圈子”表示希望进入这个集体并成为其中一员，句意通顺。", "缝": "语义：“缝”指用针线连接布料，不能用于人与圈子之间的关系。", "削": "配价：“削”要求可削的物体作宾语，圈子是人际集体，不能被削。", "扔": "语义：“扔”表示丢弃，与“想……我们的圈子”的愿望语义相反。"}, "sentence_index": 6, "correct_answer": "融入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在城市里融入了一套房子。", "explanation": "这里应该用〈买〉。融入指成为某个整体的一部分，买房子是获得物品，不能用融入。"}, {"text": "墙上融入了一幅画。", "explanation": "这里应该用〈挂〉。挂画是把画悬挂起来，融入表示进入整体并成为一部分，不用于悬挂。"}, {"text": "我给妈妈融入了一束花。", "explanation": "这里应该用〈送〉。送花是赠予，融入表示进入整体，不表示赠予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快被融入了大学的生活。", "corrected_sentence": "他很快融入了大学的生活。", "error_description": "“被”误用：“融入”表示主动进入并成为一部分，不能用于被动句，多加“被”是错误的。应说“他很快融入了大学的生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很快融入在新的环境。", "corrected_sentence": "她很快融入了新的环境。", "error_description": "“在”不能插在“融入”与宾语之间，应说“融入了新的环境”，不能说“融入在新的环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52fae7a-67ef-44c5-a47f-8897ab717241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
