INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "接口是不同系统、设备或软件之间进行连接、通信或交互的端口、规范或方式。", "primary_collocate": null, "pronunciation": "jiē kǒu", "ipa": "tɕjɛ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个软件的接口很容易用。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测试新的接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个系统用接口交换数据。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑要通过接口连接。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给开发者提供了一个接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接口出了问题，数据发不过去。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧系统的接口改好了。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的接口说明写得很清楚。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有接口，两个软件就不能交换数据。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员每天都在写接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络接口", "label": "复合"}], "register": "中性", "sense_fingerprint": "软件或系统之间用来连接和交换数据的规范或方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31a6e155-d6f3-4950-aee4-74d52c076b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”指软件之间连接、交换数据的规范，“很容易用”说的正是接口好用。"}, {"text": "插座", "is_correct": false, "explanation": "语义：“插座”是电源的插口，与软件之间的连接规范无关。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：“硬盘”是存储设备，与软件的连接或使用无关。"}, {"text": "键盘", "is_correct": false, "explanation": "搭配：“软件”一般说界面、功能，不说“软件的键盘”。"}], "explanations": {"接口": "“接口”指软件之间连接、交换数据的规范，“很容易用”说的正是接口好用。", "插座": "语义：“插座”是电源的插口，与软件之间的连接规范无关。", "硬盘": "语义：“硬盘”是存储设备，与软件的连接或使用无关。", "键盘": "搭配：“软件”一般说界面、功能，不说“软件的键盘”。"}, "sentence_index": 0, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衬衫的接口很漂亮，大家都喜欢。", "explanation": "这里应该用〈领口〉。“接口”指系统、设备之间连接的端口或规范，不指衣服的部位。"}, {"text": "这家银行设了十个接口，方便大家办理业务。", "explanation": "这里应该用〈窗口〉。“接口”指系统、设备之间连接的端口或规范，不指银行办理业务的营业窗口。"}, {"text": "他按了一下接口，屏幕就亮了。", "explanation": "这里应该用〈按钮〉。按钮是可以按下去的部件，“接口”是系统或设备之间连接的端口或规范，不能按。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”是系统的连接规范，能被“改好”，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“旧系统”不与“厨房”搭配，厨房不是软件系统的部分。"}, {"text": "座椅", "is_correct": false, "explanation": "语义：“座椅”是家具，与软件系统无关，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是房间的装饰品，与软件系统无关，句意不通。"}], "explanations": {"接口": "“接口”是系统的连接规范，能被“改好”，符合句意。", "厨房": "搭配：“旧系统”不与“厨房”搭配，厨房不是软件系统的部分。", "座椅": "语义：“座椅”是家具，与软件系统无关，句意不通。", "窗帘": "语义：“窗帘”是房间的装饰品，与软件系统无关，句意不通。"}, "sentence_index": 6, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的接口很多。", "explanation": "这里应该用〈人口〉。“接口”指系统或设备之间的连接，不指城市里居住的人数。"}, {"text": "这个接口有很多车。", "explanation": "这里应该用〈路口〉。“接口”指系统或设备之间连接的端口或规范，不指道路的交叉处。"}, {"text": "两个系统之间交换接口。", "explanation": "这里应该用〈数据〉。“接口”指连接的端口或规范，不是可以被交换的信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给这个系统写了一根接口。", "corrected_sentence": "我们给这个系统写了一个接口。", "error_description": "“接口”的量词用“个”，“根”多用于线、棍等细长物，应说“一个接口”，不说“一根接口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们刚发布了一个很新接口。", "corrected_sentence": "我们刚发布了一个新接口。", "error_description": "“很”修饰形容词“新”，作定语时应说“很新的接口”；“很新接口”缺少“的”，不自然，应去掉“很”，说“一个新接口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "达到最高程度，表示非常、特别。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "然而，无论形式如何变迁，其核心精神始终未变：以极简之形，承载文明对自我延续的深刻追问。", "target_word": "极", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天的天气极好。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法极有用。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得极快，没有人追得上。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我高兴极了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的风景极美。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对学汉语的人极有帮助。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的身体极好，每天都去走路。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务极差，我不会再去了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事极不满意。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，放在形容词或动词前，表示非常、特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31a6e155-d6f3-4950-aee4-74d52c076b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示达到最高程度，与听到的读音一致。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, {"text": "其", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是其他、它的。"}, {"text": "齐", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是整齐。"}], "explanations": {"极": "正确：极（jí）表示达到最高程度，与听到的读音一致。", "积": "jī（第一声）与 jí（第二声）声调不同，意思是积累。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是打击。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。", "其": "qí 与 jí 声母不同，意思是其他、它的。", "齐": "qí 与 jí 声母不同，意思是整齐。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "语义：“不简”与“极简”所说的追求简约相反，此处不成立。"}, {"text": "极", "is_correct": true, "explanation": "正确：“极简之形”表示达到最简约的程度，“极”修饰形容词“简”。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示“刚刚”，不能修饰形容词“简”作定语，“刚简之形”不通。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”表示并列或追加，不能直接修饰“简”，“也简之形”不通。"}], "explanations": {"不": "语义：“不简”与“极简”所说的追求简约相反，此处不成立。", "极": "正确：“极简之形”表示达到最简约的程度，“极”修饰形容词“简”。", "刚": "搭配：“刚”表示“刚刚”，不能修饰形容词“简”作定语，“刚简之形”不通。", "也": "搭配：“也”表示并列或追加，不能直接修饰“简”，“也简之形”不通。"}, "sentence_index": 0, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班跑得极快的是他，他拿了冠军。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一个范围内居首的比较，这里要说“最快的”。"}, {"text": "这件衣服极贵了，我们还是别买了。", "explanation": "这里应该用“太”。“极”表示达到最高程度，不用于表示超出合适范围的抱怨，这里要用“太”。"}, {"text": "这次比赛中，他极快，是全场第一的那位选手。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一群选手中居首的比较，这里要用“最快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示达到最高程度，与听到的读音一致。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是计算。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}, {"text": "奇", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是奇怪。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}], "explanations": {"极": "正确：极（jí）表示达到最高程度，与听到的读音一致。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "计": "jì（第四声）与 jí（第二声）声调不同，意思是计算。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。", "奇": "qí 与 jí 声母不同，意思是奇怪。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去的经历，与这里对“学汉语的人”的当下价值说明不符。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“只有”或“刚刚”，与前文泛指的积极评价不符。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，前文没有这样的转折语境。"}, {"text": "极", "is_correct": true, "explanation": "正确：“极有帮助”表示帮助的程度达到最高，“极”修饰“有”。"}], "explanations": {"曾": "语义：“曾”指过去的经历，与这里对“学汉语的人”的当下价值说明不符。", "才": "语义：“才”表示“只有”或“刚刚”，与前文泛指的积极评价不符。", "竟": "语义：“竟”表示出乎意料，前文没有这样的转折语境。", "极": "正确：“极有帮助”表示帮助的程度达到最高，“极”修饰“有”。"}, "sentence_index": 6, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件大衣极贵了，我们都买不起。", "explanation": "这里应该用“太”。“极”表示达到最高程度，不用于表示超出合适范围的抱怨，这里要用“太”。"}, {"text": "这座山在全省极高，是第一。", "explanation": "这里应该用〈最〉。“极”表示程度，不用于在一个范围内居首的比较，这里要说“最高”。"}, {"text": "他是我们班极聪明的那一个。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一个班的人中居首的比较，这里要用“最聪明的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的夏天很极热。", "corrected_sentence": "这里的夏天极热。", "error_description": "“极”与“很”都是程度副词，不能同时修饰同一个形容词，应只用“极”，说“极热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做饭做极好。", "corrected_sentence": "她做饭做得极好。", "error_description": "补语前要用“得”，应说“做得极好”；“做极好”少了“得”，不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "“中断”与“延续”在“持续不断”这一义上构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“延续”既非反义也非近义，不构成对应关系。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”与“延续”没有反义或近义关系。"}, {"text": "询问", "is_correct": false, "explanation": "“询问”与“延续”没有反义或近义关系。"}], "correct_answer": "中断", "explanations": {"中断": "“中断”与“延续”在“持续不断”这一义上构成反义。", "散步": "“散步”与“延续”既非反义也非近义，不构成对应关系。", "打扫": "“打扫”与“延续”没有反义或近义关系。", "询问": "“询问”与“延续”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "“中断”与“延续”在“持续不断”这一义上构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“延续”没有反义或近义关系。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”与“延续”没有反义或近义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”与“延续”没有反义或近义关系。"}], "correct_answer": "中断", "explanations": {"中断": "“中断”与“延续”在“持续不断”这一义上构成反义。", "思考": "“思考”与“延续”没有反义或近义关系。", "整理": "“整理”与“延续”没有反义或近义关系。", "观察": "“观察”与“延续”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续不断，一直保持下去。", "primary_collocate": null, "pronunciation": "yán xù", "ipa": "jɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "然而，无论形式如何变迁，其核心精神始终未变：以极简之形，承载文明对自我延续的深刻追问。", "target_word": "延续", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个村子的老传统一直延续到今天。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷希望家里的好习惯能延续下去。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的友谊从小学一直延续着。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年吃饺子的习俗延续了几百年。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望大家把这个好习惯延续下去。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店延续着一百年前的做法。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用新办法延续这门老手艺。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日的传统在我们家延续过很多年。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的老文化至今还在延续。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延续着", "label": "体标（着）"}, {"form": "延续了", "label": "体标（了）"}, {"form": "延续过", "label": "体标（过）"}, {"form": "延续下去", "label": "复合（趋向补语）"}], "register": "中性", "sense_fingerprint": "延续：传统、习惯等事物持续不断，一直保持下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31a6e155-d6f3-4950-aee4-74d52c076b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指持续不断地保持下去，与“始终未变”“承载文明”的持续之义一致，只有它能填入此处。"}, {"text": "中断", "is_correct": false, "explanation": "语义：“中断”指半途停止，与“始终未变”的持续之义相反，句意不通。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”指算数，不能与“自我”构成“深刻追问”的对象，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是身体运动，与抽象的“自我延续”无关，句意不通。"}], "explanations": {"延续": "“延续”指持续不断地保持下去，与“始终未变”“承载文明”的持续之义一致，只有它能填入此处。", "中断": "语义：“中断”指半途停止，与“始终未变”的持续之义相反，句意不通。", "计算": "搭配：“计算”指算数，不能与“自我”构成“深刻追问”的对象，句意不通。", "游泳": "语义：“游泳”是身体运动，与抽象的“自我延续”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路延续到了山脚下。", "explanation": "这里应该用〈延伸〉。“延续”指事情或传统不间断地保持下去，不用于道路在空间上的伸展。"}, {"text": "他把绳子延续了三米。", "explanation": "这里应该用〈延长〉。“延长”指把长度或时间拉长，“延续”指事物不断保持下去，不用于绳子的加长。"}, {"text": "他把旧手机的屏幕延续了三次。", "explanation": "这里应该用〈更换〉。“延续”指持续保持，不用于屏幕的更换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指长久保持下去，与“一百年前的做法”相承接，符合句意。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指彻底否定，与老店沿用旧做法的意思相反。"}, {"text": "忘记", "is_correct": false, "explanation": "体貌：“忘记”是瞬间完成的动作，不能与表示持续的“着”搭配。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：“淘汰”指去掉不合适的事物，与“延续一百年前的做法”相反。"}], "explanations": {"延续": "“延续”指长久保持下去，与“一百年前的做法”相承接，符合句意。", "推翻": "语义：“推翻”指彻底否定，与老店沿用旧做法的意思相反。", "忘记": "体貌：“忘记”是瞬间完成的动作，不能与表示持续的“着”搭配。", "淘汰": "语义：“淘汰”指去掉不合适的事物，与“延续一百年前的做法”相反。"}, "sentence_index": 6, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的产量延续了三倍。", "explanation": "这里应该用〈增长〉。“延续”指事情持续进行或事物长久保持，不用于产量的成倍增加。"}, {"text": "今年报名的人数延续了一倍。", "explanation": "这里应该用〈增加〉。“延续”不表示数量的增加，人数增加要用“增加”。"}, {"text": "他的存款延续了一半。", "explanation": "这里应该用〈减少〉。“延续”不表示数量的减少，存款变少要用“减少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺在他家里一直延续了着。", "corrected_sentence": "这门手艺在他家里一直延续着。", "error_description": "“延续”后不能同时用“了”和“着”两个体标，表示持续状态只用“着”，应说“一直延续着”；“延续了着”的体标重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份习俗一直延续过。", "corrected_sentence": "这份习俗一直延续着。", "error_description": "“过”表示曾经有过的经历，不能表示正在持续进行，此处应用“着”，说“一直延续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ac3ec5-95ca-4cbf-9ae8-41008c4ac655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
