INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付出钱来购买商品或服务。", "primary_collocate": null, "pronunciation": "huā qián", "ipa": "xua˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "种菜和建花园都要花钱。", "target_word": "花钱", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "花钱可以让城市更好，也是赚钱的方法。", "target_word": "花钱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "去那家店理发要花钱，一次五十元。", "target_word": "花钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个公园玩不花钱，大家都可以来。", "target_word": "花钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看医生、买药都要花钱。", "target_word": "花钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学游泳要花钱，你想好了吗？", "target_word": "花钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢花钱请别人修电脑。", "target_word": "花钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐飞机比坐火车花钱多。", "target_word": "花钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这里吃饭花钱不多，我常常来。", "target_word": "花钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买书、买衣服都要花钱，所以我先看看。", "target_word": "花钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花了钱", "label": "体标（了）"}, {"form": "花过钱", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "付钱买商品或服务（看病、学习、理发等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8123548a-3e19-4ed4-b9a2-7a790a83fd3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12593, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花钱", "is_correct": true, "explanation": "正确：花钱，指付钱买服务或材料，与“种菜和建花园都要”所说的必要开销一致。"}, {"text": "赚钱", "is_correct": false, "explanation": "语义：“赚钱”表示获得钱，与“都要”所说的支出相反。"}, {"text": "数钱", "is_correct": false, "explanation": "搭配：“数钱”是点数钱款，不能表示种菜建园所需的开销。"}, {"text": "退钱", "is_correct": false, "explanation": "语义：“退钱”表示退还钱款，与“都要”所说的必要开销不符。"}], "explanations": {"花钱": "正确：花钱，指付钱买服务或材料，与“种菜和建花园都要”所说的必要开销一致。", "赚钱": "语义：“赚钱”表示获得钱，与“都要”所说的支出相反。", "数钱": "搭配：“数钱”是点数钱款，不能表示种菜建园所需的开销。", "退钱": "语义：“退钱”表示退还钱款，与“都要”所说的必要开销不符。"}, "sentence_index": 0, "correct_answer": "花钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠修车花钱。", "explanation": "这里应该用〈赚钱〉。花钱指用钱买东西，靠修车得钱要说赚钱。"}, {"text": "我花钱向他道歉了。", "explanation": "这里不是“用钱买东西”的意思，赔不是要靠认错，不能用钱买。"}, {"text": "她靠卖菜花钱。", "explanation": "这里应该用〈挣钱〉。花钱指用钱买东西，靠卖菜得钱要说挣钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花钱", "is_correct": true, "explanation": "正确：花钱，指付钱请人做事，与“请别人修电脑”的付费含义一致。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”指进食，与“请别人修电脑”没有关系，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“请别人”这样的兼语结构。"}, {"text": "喝水", "is_correct": false, "explanation": "语义：“喝水”指饮用，与修电脑无关，句子不通。"}], "explanations": {"花钱": "正确：花钱，指付钱请人做事，与“请别人修电脑”的付费含义一致。", "吃饭": "语义：“吃饭”指进食，与“请别人修电脑”没有关系，句子不通。", "睡觉": "配价：“睡觉”是不及物动词，不能带“请别人”这样的兼语结构。", "喝水": "语义：“喝水”指饮用，与修电脑无关，句子不通。"}, "sentence_index": 6, "correct_answer": "花钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我花钱哭了一场。", "explanation": "这里不是“用钱买东西”的意思，哭是情绪反应，不能用钱买。"}, {"text": "他花钱感动了一下。", "explanation": "这里不是“用钱买东西”的意思，感动是心理反应，不能用钱买。"}, {"text": "这台电脑是我花钱卖出去的。", "explanation": "这里应该用〈买〉。花钱是付出钱，卖出去是收钱，不能说花钱卖出去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买书了花钱。", "corrected_sentence": "他买书花了钱。", "error_description": "错误：“了”插在“买书”和“花钱”之间，位置错误。“了”应紧跟动词“花”，应说“他买书花了钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这个月没了花钱，还存下了工资。", "corrected_sentence": "他这个月没花钱，还存下了工资。", "error_description": "错误：“没”后多了一个“了”。“没”表示否定，不能与“了”同用，“没花钱”中“没”应直接接“花钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
