INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "绿色植物是指体内含有叶绿素、能进行光合作用的植物。", "primary_collocate": null, "pronunciation": "lǜ sè zhí wù", "ipa": "ly˥˩ sɤ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "城市规划者发现，有绿色植物的大楼更受人们欢迎。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "有绿色植物的地方，空气更干净。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "绿色植物白天吸收二氧化碳，放出氧气。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色植物需要阳光和水才能长大。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家窗台上放着几盆绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色植物的叶子里有叶绿素。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有很多绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里放一盆绿色植物，人会觉得舒服。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有绿色植物，动物就没有食物和氧气。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的绿色植物让夏天凉快了不少。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一盆绿色植物", "label": "量词"}, {"form": "一种绿色植物", "label": "量词"}], "register": "中性", "sense_fingerprint": "绿色植物：含叶绿素、能进行光合作用的植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿色植物", "is_correct": true, "explanation": "正确。“绿色植物”修饰“大楼”，说明楼里有植物，符合“更受人们欢迎”的语境。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾令人厌恶，不会让大楼更受人们欢迎，与后半句矛盾。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是害虫，楼里有蚊子不会吸引人，与“更受人们欢迎”矛盾。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“有噪音”描述的是困扰，与“更受人们欢迎”这类正面评价不搭配。"}], "explanations": {"绿色植物": "正确。“绿色植物”修饰“大楼”，说明楼里有植物，符合“更受人们欢迎”的语境。", "垃圾": "语义：垃圾令人厌恶，不会让大楼更受人们欢迎，与后半句矛盾。", "蚊子": "语义：蚊子是害虫，楼里有蚊子不会吸引人，与“更受人们欢迎”矛盾。", "噪音": "搭配：“有噪音”描述的是困扰，与“更受人们欢迎”这类正面评价不搭配。"}, "sentence_index": 0, "correct_answer": "绿色植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把墙刷成了绿色植物。", "explanation": "这里“绿色植物”被当成颜色词用，表示颜色应该用〈浅绿〉这类颜色词。“绿色植物”指能进行光合作用的植物，不能指颜色。"}, {"text": "我们公司推广绿色植物生产方式。", "explanation": "这里应该用〈环保〉。“绿色植物”指植物，不能表示环保、无污染的意思；修饰“生产方式”要用“环保”这类词。"}, {"text": "大象是绿色植物。", "explanation": "这里应该用〈哺乳动物〉。大象是动物，不是绿色植物，“绿色植物”不能用来指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿色植物", "is_correct": true, "explanation": "正确。森林里有很多植物，说“绿色植物”自然贴切。"}, {"text": "高楼", "is_correct": false, "explanation": "语义：森林里不会有很多高楼，与“森林”的场景矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是室内设备，不会在森林里成群出现。"}, {"text": "行道树", "is_correct": false, "explanation": "语义：“行道树”指种在城市道路两旁的树，森林里不会说有很多行道树，与场景矛盾。"}], "explanations": {"绿色植物": "正确。森林里有很多植物，说“绿色植物”自然贴切。", "高楼": "语义：森林里不会有很多高楼，与“森林”的场景矛盾。", "电脑": "语义：电脑是室内设备，不会在森林里成群出现。", "行道树": "语义：“行道树”指种在城市道路两旁的树，森林里不会说有很多行道树，与场景矛盾。"}, "sentence_index": 6, "correct_answer": "绿色植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把阳光变成养分的过程叫绿色植物。", "explanation": "这里应该用〈光合作用〉。“绿色植物”指植物这种生物，不能用来指一个过程；“光合作用”才指植物把阳光变成养分的过程。"}, {"text": "这种绿色物质能帮助植物吸收阳光，就是绿色植物。", "explanation": "这里应该用〈叶绿素〉。叶绿素是一种物质，“绿色植物”指植物这种生物，不能用来指物质。"}, {"text": "这根树枝是绿色植物。", "explanation": "这里应该用〈植株〉。“绿色植物”指整株植物，不能用来指树枝这样的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家窗台上的绿色植物长很好。", "corrected_sentence": "我家窗台上的绿色植物长得很好。", "error_description": "错误在“长”和补语之间缺少“得”。“长”后带补语要用“得”连接，应说“长得很好”，不说“长很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把绿色植物运在市场上。", "corrected_sentence": "农民把绿色植物运到市场上。", "error_description": "错误在“运”后的目的地要用介词“到”引出，应说“运到市场上”，不说“运在市场上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
