INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两层或两层以上的房屋；也指楼房的某一层，如“五楼”。", "primary_collocate": null, "pronunciation": "lóu", "ipa": "loʊ˧˥", "syllable_count": 1, "sentences": [{"text": "一些高楼的墙上种了植物。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "有植物的楼，房地产价值更高。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "种菜的楼需要好好设计。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座楼一共有二十层。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在三楼。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你上楼拿一下书。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那栋楼的旁边有一家小超市。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的楼很新，也很高。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校新盖了一栋楼。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我只好爬到十楼。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "栋", "label": "量词"}, {"form": "楼房", "label": "复合"}, {"form": "高楼", "label": "复合"}, {"form": "樓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多层房屋；楼房的某一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "楼", "is_correct": true, "explanation": "lóu 第二声，意思是楼房，是正确答案。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。"}, {"text": "搂", "is_correct": false, "explanation": "lǒu 与 lóu 声调不同（第三声与第二声），意思是搂抱。"}, {"text": "篓", "is_correct": false, "explanation": "lǒu 与 lóu 声调不同（第三声与第二声），意思是竹篓。"}, {"text": "留", "is_correct": false, "explanation": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是留下。"}], "explanations": {"楼": "lóu 第二声，意思是楼房，是正确答案。", "漏": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。", "搂": "lǒu 与 lóu 声调不同（第三声与第二声），意思是搂抱。", "篓": "lǒu 与 lóu 声调不同（第三声与第二声），意思是竹篓。", "留": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是留下。"}, "sentence_index": null, "correct_answer": "楼"}, "level_3": {"options": [{"text": "楼", "is_correct": true, "explanation": "“高楼”指多层的楼房，墙上可以种植物，符合句意。"}, {"text": "山", "is_correct": false, "explanation": "语义：山是天然地形，没有人造的墙，不能说“高山的墙上种了植物”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“高桌子”不是常见说法，桌子也没有墙。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有墙，“墙上种了植物”的说法对树不成立。"}], "explanations": {"楼": "“高楼”指多层的楼房，墙上可以种植物，符合句意。", "山": "语义：山是天然地形，没有人造的墙，不能说“高山的墙上种了植物”。", "桌子": "搭配：“高桌子”不是常见说法，桌子也没有墙。", "树": "语义：树没有墙，“墙上种了植物”的说法对树不成立。"}, "sentence_index": 0, "correct_answer": "楼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架一共有五楼。", "explanation": "这里应该用〈层〉。楼指整座房屋，书架的分层要用“层”，不能说“五楼”。"}, {"text": "我们买了一套三居室的楼，准备装修。", "explanation": "这里应该用〈房子〉。“一套三居室”说的是住宅单元，楼指整栋建筑，不能数成“一套”。"}, {"text": "我每天下班都走楼回家。", "explanation": "这里应该用〈楼梯〉。走楼梯是常见说法，楼是房屋，不是上下的通道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12603, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "楼", "is_correct": true, "explanation": "lóu 第二声，意思是楼房，是正确答案。"}, {"text": "劳", "is_correct": false, "explanation": "láo 与 lóu 韵母不同（ao 与 ou），声调相同，意思是劳动。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 lóu 韵母不同（u 与 ou），声调相同，意思是炉子。"}, {"text": "流", "is_correct": false, "explanation": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是流动。"}], "explanations": {"楼": "lóu 第二声，意思是楼房，是正确答案。", "劳": "láo 与 lóu 韵母不同（ao 与 ou），声调相同，意思是劳动。", "漏": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。", "炉": "lú 与 lóu 韵母不同（u 与 ou），声调相同，意思是炉子。", "流": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是流动。"}, "sentence_index": null, "correct_answer": "楼"}, "level_3": {"options": [{"text": "楼", "is_correct": true, "explanation": "“那栋楼”指一座楼房，旁边可以有超市，符合句意。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：量词“栋”只用于房屋，不能说“那栋桥”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是建筑，不能在它的旁边开一家超市。"}, {"text": "车", "is_correct": false, "explanation": "搭配：车用“辆”计量，“那栋车”不通顺。"}], "explanations": {"楼": "“那栋楼”指一座楼房，旁边可以有超市，符合句意。", "桥": "搭配：量词“栋”只用于房屋，不能说“那栋桥”。", "书": "语义：书不是建筑，不能在它的旁边开一家超市。", "车": "搭配：车用“辆”计量，“那栋车”不通顺。"}, "sentence_index": 6, "correct_answer": "楼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说一共有二十楼。", "explanation": "这里应该用〈章〉。楼指房屋或房屋的某一层，小说的篇章要用“章”，不能说“二十楼”。"}, {"text": "他把盒子的楼盖上了。", "explanation": "这里应该用〈盖子〉。楼指房屋，不能指盒子的盖子，能盖上的是“盖子”。"}, {"text": "这本书的楼很漂亮。", "explanation": "这里应该用〈封面〉。楼指房屋，不能指书的外观，书的外观要说“封面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我住的那只楼很大。", "corrected_sentence": "我住的那座楼很大。", "error_description": "量词错误：“楼”是房屋，应用“座”或“栋”，应说“那座楼”；这里用“只”（多用于动物等）是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爬到了十个楼。", "corrected_sentence": "我爬到了十楼。", "error_description": "量词错误：说楼层时“楼”前不加数量词“个”，应说“爬到了十楼”；“十个楼”指十栋楼房，与“爬到”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
