INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12605, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示认真、充分、尽情地做某事。", "primary_collocate": null, "pronunciation": "hǎo hǎo", "ipa": "xɑʊ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "种菜的楼需要好好设计。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "你今天太累了，回家好好休息吧。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试快到了，我要好好复习。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想在家好好睡一觉。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你好好想一想这个问题。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，我们要好好玩儿。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间好好打扫了一遍。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，好好洗一洗手。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我在学校好好学习。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病了，你要好好照顾她。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好好儿", "label": "儿化"}, {"form": "好好地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "认真、充分、尽情地做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好好", "is_correct": true, "explanation": "hǎo hǎo，意思是认真、充分地做某事，是正确答案。"}, {"text": "很好", "is_correct": false, "explanation": "hěn hǎo 与 hǎo hǎo 第一音节韵母不同（en 与 ao），意思是非常好。"}, {"text": "好找", "is_correct": false, "explanation": "hǎo zhǎo 与 hǎo hǎo 第二音节声母不同（zh 与 h），意思是容易找到。"}, {"text": "好考", "is_correct": false, "explanation": "hǎo kǎo 与 hǎo hǎo 第二音节声母不同（k 与 h），意思是容易通过考试。"}, {"text": "好吵", "is_correct": false, "explanation": "hǎo chǎo 与 hǎo hǎo 第二音节声母不同（ch 与 h），意思是很吵闹。"}], "explanations": {"好好": "hǎo hǎo，意思是认真、充分地做某事，是正确答案。", "很好": "hěn hǎo 与 hǎo hǎo 第一音节韵母不同（en 与 ao），意思是非常好。", "好找": "hǎo zhǎo 与 hǎo hǎo 第二音节声母不同（zh 与 h），意思是容易找到。", "好考": "hǎo kǎo 与 hǎo hǎo 第二音节声母不同（k 与 h），意思是容易通过考试。", "好吵": "hǎo chǎo 与 hǎo hǎo 第二音节声母不同（ch 与 h），意思是很吵闹。"}, "sentence_index": null, "correct_answer": "好好"}, "level_3": {"options": [{"text": "好好", "is_correct": true, "explanation": "“好好设计”表示认真、充分地设计，符合“需要”的语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经完成，与“需要…设计”的将来或必要相矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“需要”的要求相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语域：“随便”口语色彩重，且与正式设计的要求不合。"}], "explanations": {"好好": "“好好设计”表示认真、充分地设计，符合“需要”的语境。", "已经": "语义：“已经”表示已经完成，与“需要…设计”的将来或必要相矛盾。", "刚": "语义：“刚”表示刚刚发生，与“需要”的要求相矛盾。", "随便": "语域：“随便”口语色彩重，且与正式设计的要求不合。"}, "sentence_index": 0, "correct_answer": "好好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们好好在车站遇到了老同学。", "explanation": "这里应该用〈碰巧〉。好好表示认真、充分，不表示偶然，遇到老同学是偶然的，要说“碰巧”。"}, {"text": "他好好就做完了作业。", "explanation": "这里应该用〈很快〉。好好表示认真、充分，不表示速度，应说“很快就做完了作业”。"}, {"text": "我好好在路上捡到了一百块钱。", "explanation": "这里应该用〈居然〉。好好表示认真、充分，不表示意外，捡到钱是出乎意料的，要说“居然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好好", "is_correct": true, "explanation": "“好好打扫”表示认真、彻底地打扫，符合句意。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎没做，与“打扫了一遍”矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”强调持续，与“一遍”的一次性相矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”多用于否定句，与“打扫了一遍”的肯定陈述不合。"}], "explanations": {"好好": "“好好打扫”表示认真、彻底地打扫，符合句意。", "差点": "语义：“差点”表示几乎没做，与“打扫了一遍”矛盾。", "一直": "语义：“一直”强调持续，与“一遍”的一次性相矛盾。", "从来": "语义：“从来”多用于否定句，与“打扫了一遍”的肯定陈述不合。"}, "sentence_index": 6, "correct_answer": "好好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他好好地打了一个喷嚏。", "explanation": "这里应该用〈突然〉。好好表示认真、充分，打喷嚏是无意的生理反应，不能用“好好”修饰。"}, {"text": "他好好地吓了一跳。", "explanation": "这里应该用〈猛地〉。好好表示认真、充分，吓一跳是无意的反应，不能用“好好”修饰。"}, {"text": "他好好忘了带钥匙。", "explanation": "这里应该用〈不小心〉。好好表示认真，忘记是无意的，不能用“好好”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你好好好保护这只小猫。", "corrected_sentence": "请你好好保护这只小猫。", "error_description": "重叠形式错误：“好好”已是重叠形式，不能多写一个“好”成“好好好”，应说“好好保护”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
