INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑化", "is_correct": true, "explanation": "丑化：使变得难看，与“美化”意义相反。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运：搬动物品，与“美化”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：动脑想问题，与“美化”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：在水中活动，与“美化”没有反义关系。"}], "correct_answer": "丑化", "explanations": {"丑化": "丑化：使变得难看，与“美化”意义相反。", "搬运": "搬运：搬动物品，与“美化”没有反义关系。", "思考": "思考：动脑想问题，与“美化”没有反义关系。", "游泳": "游泳：在水中活动，与“美化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑化", "is_correct": true, "explanation": "丑化：使变得难看，与“美化”意义相反。"}, {"text": "查看", "is_correct": false, "explanation": "查看：察看情况，与“美化”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：慢慢走动，与“美化”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步：快速跑动，与“美化”没有反义关系。"}], "correct_answer": "丑化", "explanations": {"丑化": "丑化：使变得难看，与“美化”意义相反。", "查看": "查看：察看情况，与“美化”没有反义关系。", "散步": "散步：慢慢走动，与“美化”没有反义关系。", "跑步": "跑步：快速跑动，与“美化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过装饰或修改，使事物看起来更漂亮或更令人满意。", "primary_collocate": null, "pronunciation": "měi huà", "ipa": "meɪ̯˨˩˦ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "这些垂直农场不仅美化了环境，也对城市的可持续性发展有帮助。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工人在公园里种了花，美化环境。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在墙上画画，美化了教室。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想用花草美化小区。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府要美化街道，种更多的树。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了几盆花来美化阳台。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要乱扔垃圾，大家一起美化校园。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用彩灯美化了房间。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些画很好地美化了医院的走廊。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用窗帘和花瓶美化我们的家。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美化了", "label": "完成体"}, {"form": "美化过", "label": "经历体"}, {"form": "美化着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "通过装饰使环境或事物更漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb44a393-77f6-42c1-bc0b-0d5ca4c2aee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美化", "is_correct": true, "explanation": "měi huà（美化）指通过装饰或修改使事物更漂亮。"}, {"text": "梅花", "is_correct": false, "explanation": "méi huā 与 měi huà 两个音节的声调都不同，意思是梅花。"}, {"text": "买花", "is_correct": false, "explanation": "mǎi 与 měi 的韵母不同（ai 与 ei），意思是买花。"}, {"text": "米花", "is_correct": false, "explanation": "mǐ 与 měi 的韵母不同（i 与 ei），第二个音节声调也不同，意思是米花。"}], "explanations": {"美化": "měi huà（美化）指通过装饰或修改使事物更漂亮。", "梅花": "méi huā 与 měi huà 两个音节的声调都不同，意思是梅花。", "买花": "mǎi 与 měi 的韵母不同（ai 与 ei），意思是买花。", "米花": "mǐ 与 měi 的韵母不同（i 与 ei），第二个音节声调也不同，意思是米花。"}, "sentence_index": null, "correct_answer": "美化"}, "level_3": {"options": [{"text": "美化", "is_correct": true, "explanation": "美化与“不仅……也对城市发展有帮助”相符，指使环境变得更好看。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染环境与“也对城市的可持续性发展有帮助”相矛盾。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：破坏环境与“有帮助”相矛盾。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”多用于房屋，不说“装修环境”。"}], "explanations": {"美化": "美化与“不仅……也对城市发展有帮助”相符，指使环境变得更好看。", "污染": "语义：污染环境与“也对城市的可持续性发展有帮助”相矛盾。", "破坏": "语义：破坏环境与“有帮助”相矛盾。", "装修": "搭配：“装修”多用于房屋，不说“装修环境”。"}, "sentence_index": 0, "correct_answer": "美化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每个月都去美容院做美化。", "explanation": "此处“美化”指给人做容貌护理，这是误用；“美化”只用于环境和物品。"}, {"text": "工人正在美化破损的路面。", "explanation": "这里应该用〈修理〉。“美化”指使事物变得更好看，不指修补破损的东西。"}, {"text": "妈妈美化了漏水的水管。", "explanation": "这里应该用〈修理〉。“美化”指使事物变得更好看，不指修补漏水的设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美化", "is_correct": true, "explanation": "美化与“校园”搭配，符合“大家一起”保护环境的语境。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“请不要乱扔垃圾，大家一起……”要求积极的行动，“放弃校园”与语境矛盾。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”与“请不要乱扔垃圾”的语境相反，不能说“大家一起污染校园”。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割的对象是庄稼，与“校园”和语境都不符。"}], "explanations": {"美化": "美化与“校园”搭配，符合“大家一起”保护环境的语境。", "放弃": "语义：“请不要乱扔垃圾，大家一起……”要求积极的行动，“放弃校园”与语境矛盾。", "污染": "语义：“污染”与“请不要乱扔垃圾”的语境相反，不能说“大家一起污染校园”。", "收割": "语义：收割的对象是庄稼，与“校园”和语境都不符。"}, "sentence_index": 6, "correct_answer": "美化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去医院美化，想让脸变得更漂亮。", "explanation": "这里应该用〈整容〉。美化用于环境和物品，给人做整容手术要用〈整容〉。"}, {"text": "爸爸把坏了的门美化了一下，又继续用。", "explanation": "这里应该用〈修理〉。“美化”指使东西变好看，不指修好坏掉的门。"}, {"text": "他把被撞坏的车美化了一下，然后去上班。", "explanation": "这里应该用〈修理〉。“美化”指使东西变好看，不指修好被撞坏的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把花园美化很漂亮。", "corrected_sentence": "他把花园美化得很漂亮。", "error_description": "情态补语前要加“得”，应说“美化得很漂亮”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在彩旗美化了操场。", "corrected_sentence": "他们用彩旗美化了操场。", "error_description": "方式状语“用彩旗”的介词应为“用”，不能用“在”，应说“用彩旗美化了操场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
