INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以农业生产为主的劳动者聚居的地方。", "primary_collocate": null, "pronunciation": "nóng cūn", "ipa": "nʊŋ˧˥ tsʰuən˥", "syllable_count": 2, "sentences": [{"text": "蔬菜直接在城市里生产，不需要从很远的农村运来。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我爷爷奶奶住在农村，那里的空气很好。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的孩子放学后常常帮家里干活。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，农村的路修得越来越好了。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后回到农村当老师。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的晚上很安静，能看见很多星星。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我想去农村看看爷爷种的玉米。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多农村的老人也用手机买东西。", "target_word": "农村", "complexity_tier": "T3", "furigana": "xiàn zài hěn duō nóng cūn de lǎo rén yě yòng shǒu jī mǎi dōng xi", "sentence_source": "generated"}, {"text": "他在农村长大，所以很会做农活。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的房子一般比城市里的大。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農村", "label": "繁体"}, {"form": "农村地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "农村：以农业生产为主的劳动者聚居的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12883278-5600-40df-b779-2c94d6e49eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农村", "is_correct": true, "explanation": "农村是以农业生产为主的地方，与“从很远的……运来”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的屋子，蔬菜不会从很远的厨房运来，也与“直接在城市里生产”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“从……运来”的起点应是地点，冰箱是家用电器，不能作为蔬菜运来的起点。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是供人居住的房间，不是生产蔬菜的地方，与句意不符。"}], "explanations": {"农村": "农村是以农业生产为主的地方，与“从很远的……运来”的语境相符。", "厨房": "语义：厨房是做饭的屋子，蔬菜不会从很远的厨房运来，也与“直接在城市里生产”冲突。", "冰箱": "搭配：“从……运来”的起点应是地点，冰箱是家用电器，不能作为蔬菜运来的起点。", "宿舍": "语义：宿舍是供人居住的房间，不是生产蔬菜的地方，与句意不符。"}, "sentence_index": 0, "correct_answer": "农村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会做农村。", "explanation": "这里应该用〈农活〉。农村指地方，不能被做；做的是农活。"}, {"text": "他是一个农村。", "explanation": "这里应该用〈农民〉。农村指地方，指人要说农民。"}, {"text": "这些农村都很新鲜。", "explanation": "这里应该用〈蔬菜〉。农村指地方，不是食物；说东西新鲜要用蔬菜这类农产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超市", "is_correct": false, "explanation": "搭配：“去……看看爷爷种的玉米”不能用超市，超市里不种玉米。"}, {"text": "农村", "is_correct": true, "explanation": "农村是以农业生产为主的地方，正好是爷爷种玉米的地方，与句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，与爷爷种玉米的情境不符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产工业产品的地方，不种玉米，与“爷爷种的玉米”矛盾。"}], "explanations": {"超市": "搭配：“去……看看爷爷种的玉米”不能用超市，超市里不种玉米。", "农村": "农村是以农业生产为主的地方，正好是爷爷种玉米的地方，与句意相符。", "银行": "语义：银行是办理金融业务的地方，与爷爷种玉米的情境不符。", "工厂": "语义：工厂是生产工业产品的地方，不种玉米，与“爷爷种的玉米”矛盾。"}, "sentence_index": 6, "correct_answer": "农村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农村是国家的重要产业。", "explanation": "这里应该用〈农业〉。农村指地方，不指产业；说产业要用农业。"}, {"text": "现在正是农村季节。", "explanation": "这里应该用〈农忙〉。农村指地方，不能指一个季节；说农忙季节要用农忙。"}, {"text": "这些农村都放在仓库里。", "explanation": "这里应该用〈农具〉。农村是地方，不能像东西一样放进仓库。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一只农村教了三年书。", "corrected_sentence": "他在一个农村教了三年书。", "error_description": "量词错误：“农村”指地方，应说“一个农村”；“只”用于动物或小件物品，不能用来数农村。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他农村来，现在在城里工作。", "corrected_sentence": "他从农村来，现在在城里工作。", "error_description": "介词错误：表示起点时，“农村”前要加“从”，应说“他从农村来”，不能说“他农村来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运走", "is_correct": true, "explanation": "运走：把东西运到别处去，与“运来”的方向相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱获得物品，不涉及运送方向，不是“运来”的反义。"}, {"text": "储存", "is_correct": false, "explanation": "储存指把东西收藏起来，与运来没有反义关系。"}, {"text": "生产", "is_correct": false, "explanation": "生产指制造物品，与运送的方向无关，不是“运来”的反义。"}], "correct_answer": "运走", "explanations": {"运走": "运走：把东西运到别处去，与“运来”的方向相反。", "购买": "购买指用钱获得物品，不涉及运送方向，不是“运来”的反义。", "储存": "储存指把东西收藏起来，与运来没有反义关系。", "生产": "生产指制造物品，与运送的方向无关，不是“运来”的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运走", "is_correct": true, "explanation": "运走：把东西运到别处去，与“运来”的方向相反。"}, {"text": "卖出", "is_correct": false, "explanation": "卖出指把东西销售出去，与运送方向无关，不是“运来”的反义。"}, {"text": "冷藏", "is_correct": false, "explanation": "冷藏指用低温保存食物，与运来没有反义关系。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪指做饭做菜，与运送方向无关，不是“运来”的反义。"}], "correct_answer": "运走", "explanations": {"运走": "运走：把东西运到别处去，与“运来”的方向相反。", "卖出": "卖出指把东西销售出去，与运送方向无关，不是“运来”的反义。", "冷藏": "冷藏指用低温保存食物，与运来没有反义关系。", "烹饪": "烹饪指做饭做菜，与运送方向无关，不是“运来”的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用车、船等交通工具把东西运送过来。", "primary_collocate": null, "pronunciation": "yùn lái", "ipa": "yn˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "蔬菜直接在城市里生产，不需要从很远的农村运来。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "昨天下午，一船水果从南方运来了。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些大米是从北方运来的。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车给超市运来了很多新鲜牛奶。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的路不好走，货很难运来。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过节，商店从外地运来了很多花。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用大船把石头从河对岸运来。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天北方的超市用火车运来了南方的水果。", "target_word": "运来", "complexity_tier": "T3", "furigana": "dōng tiān běi fāng de chāo shì yòng huǒ chē yùn lái le nán fāng de shuǐ guǒ", "sentence_source": "generated"}, {"text": "等新的桌子运来，我们就可以开会了。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说今天会有一批新书运来。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運來", "label": "繁体"}, {"form": "运来了", "label": "体标"}], "register": "中性", "sense_fingerprint": "运来：用车船等把东西运送过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12883278-5600-40df-b779-2c94d6e49eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运来", "is_correct": true, "explanation": "运来表示用车船等把东西从远处运送过来，与“蔬菜”“从很远的农村”的语境相符。"}, {"text": "飞来", "is_correct": false, "explanation": "语义：蔬菜不会飞，“飞来”与蔬菜的运输无关，句意不通。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是把种子埋进土里让它生长，不是把东西从远处运来，与句意矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用于蔬菜的运送，与“从很远的农村”搭配不当。"}], "explanations": {"运来": "运来表示用车船等把东西从远处运送过来，与“蔬菜”“从很远的农村”的语境相符。", "飞来": "语义：蔬菜不会飞，“飞来”与蔬菜的运输无关，句意不通。", "种植": "语义：种植是把种子埋进土里让它生长，不是把东西从远处运来，与句意矛盾。", "修理": "搭配：“修理”的对象是器物，不能用于蔬菜的运送，与“从很远的农村”搭配不当。"}, "sentence_index": 0, "correct_answer": "运来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈从老家运来了一阵香味。", "explanation": "这里应该用〈飘来〉。运来指运送货物，香味不能被运送，应说飘来。"}, {"text": "他运来了一个好主意。", "explanation": "这里应该用〈想出〉。运来指运送实物，不能用来说想出主意。"}, {"text": "这件事运来了很多麻烦。", "explanation": "这里应该用〈招来〉。运来用于实物，不用于麻烦这类抽象结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：石头不能吃，“用大船把石头从河对岸吃掉”句意不通。"}, {"text": "运来", "is_correct": true, "explanation": "运来表示用大船把石头从对岸运送过来，与句意相符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”是把东西弄坏，与用大船运送石头的意思矛盾。"}, {"text": "修好", "is_correct": false, "explanation": "搭配：“修好”的对象是坏了的器物，不能用来描述运送石头。"}], "explanations": {"吃掉": "语义：石头不能吃，“用大船把石头从河对岸吃掉”句意不通。", "运来": "运来表示用大船把石头从对岸运送过来，与句意相符。", "摔碎": "语义：“摔碎”是把东西弄坏，与用大船运送石头的意思矛盾。", "修好": "搭配：“修好”的对象是坏了的器物，不能用来描述运送石头。"}, "sentence_index": 6, "correct_answer": "运来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司运来一名工程师。", "explanation": "这里应该用〈派来〉。运来用于货物，不用于人，派人要用派来。"}, {"text": "远处运来一阵歌声。", "explanation": "这里应该用〈传来〉。运来指运送实物，声音不能被运来。"}, {"text": "那部电影运来了很多观众。", "explanation": "这里应该用〈引来〉。运来用于运送实物，不指吸引人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天上午，一车煤从北边运来来了。", "corrected_sentence": "昨天上午，一车煤从北边运来了。", "error_description": "补语错误：“运来”中的“来”已是趋向补语，多写了一个“来”，应说“运来了”，不说“运来来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批水果从外地运来来。", "corrected_sentence": "这批水果从外地运来。", "error_description": "补语错误：“运来”中的“来”已是趋向补语，末尾多写了一个“来”，应删去，说“从外地运来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
