INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物的顶部。", "primary_collocate": null, "pronunciation": "lóu dǐng", "ipa": "lou˧˥ tiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民可以在楼顶或阳台种菜，不需要大片土地。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们爬上楼顶，看到了整个城市。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶上有一个小花园。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上他一个人坐在楼顶看月亮。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶的风很大，你要小心。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在楼顶修水箱。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，邻居们常常在楼顶乘凉。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶上晒着很多衣服。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跑到楼顶，下不来了。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的楼顶是红色的。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "樓頂", "label": "繁体"}, {"form": "楼顶花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "楼顶：建筑物的顶部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12883278-5600-40df-b779-2c94d6e49eb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楼顶", "is_correct": true, "explanation": "“楼顶”是建筑物的顶部，与“阳台”并列，可以用来种菜。"}, {"text": "楼梯", "is_correct": false, "explanation": "语义：楼梯是供人上下的通道，不能用来种菜。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的房间，不能用来种菜。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所是如厕的地方，不能用来种菜。"}], "explanations": {"楼顶": "“楼顶”是建筑物的顶部，与“阳台”并列，可以用来种菜。", "楼梯": "语义：楼梯是供人上下的通道，不能用来种菜。", "教室": "语义：教室是上课的房间，不能用来种菜。", "厕所": "语义：厕所是如厕的地方，不能用来种菜。"}, "sentence_index": 0, "correct_answer": "楼顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小木棚的楼顶是用铁皮做的。", "explanation": "这里应该用〈屋顶〉。“楼顶”指楼房的顶部，单层的小木棚没有楼层，应说“屋顶”。"}, {"text": "楼顶的邻居半夜总是弹钢琴，吵得我睡不着。", "explanation": "这里应该用〈楼上〉。“楼上”是我家的上一层，“楼顶”是最上面的顶部，不能指邻居所在的位置。"}, {"text": "楼顶一共有三十层，他住在最下面。", "explanation": "这里应该用〈楼房〉。楼房整栋可以说有几层，“楼顶”只是最上面的部分，不能说有几层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室是学校的场所，邻居不会在教室里乘凉。"}, {"text": "楼顶", "is_correct": true, "explanation": "“楼顶”是露天的高处，夏天在那里乘凉很常见。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是冷藏电器，不能钻进去乘凉。"}, {"text": "实验室", "is_correct": false, "explanation": "搭配：“乘凉”一般说在树下、屋顶、阳台等地方，“实验室”不搭配。"}], "explanations": {"教室": "语义：教室是学校的场所，邻居不会在教室里乘凉。", "楼顶": "“楼顶”是露天的高处，夏天在那里乘凉很常见。", "冰箱": "语义：冰箱是冷藏电器，不能钻进去乘凉。", "实验室": "搭配：“乘凉”一般说在树下、屋顶、阳台等地方，“实验室”不搭配。"}, "sentence_index": 6, "correct_answer": "楼顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子在楼顶，夏天特别热。", "explanation": "这里应该用〈顶楼〉。房子位于最上一层应说“顶楼”，“楼顶”指楼房最上面的顶部，不能说房子在楼顶。"}, {"text": "楼顶的小超市今天关门了，我们只好走远一点买东西。", "explanation": "这里应该用〈楼下〉。开在低层的超市应说“楼下”，“楼顶”是最上面的顶部，不能用来指超市所在的位置。"}, {"text": "这栋楼的楼顶很高，每层都有四米。", "explanation": "这里应该用〈楼层〉。说每层的高度要用“楼层”，“楼顶”只是最上面的部分，没有“每层”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一条楼顶上看到了日出。", "corrected_sentence": "我们在一个楼顶上看到了日出。", "error_description": "量词错误：“条”用于狭长的东西，不能用来数“楼顶”，应说“一个楼顶上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只鸟飞楼顶上，停了好久。", "corrected_sentence": "一只鸟飞到楼顶上，停了好久。", "error_description": "补语缺失：表示到达的“到”不能省略，应说“飞到楼顶上”，不能说“飞楼顶上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b491d0-23cf-4c85-bdb8-11cf085212bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
