INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12633, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物朝向外部的一面，通常指正面或侧面。", "primary_collocate": null, "pronunciation": "lì miàn", "ipa": "li˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "传统意义上被视为“非生产性空间”的公园、社区花园乃至建筑立面与屋顶的绿化系统，正通过多重价值链条深度嵌入城市资本循环。", "target_word": "立面", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座新建的美术馆，其立面的处理既尊重了周边的历史街区，又体现了当代建筑语言的克制与清晰。", "target_word": "立面", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "设计师重新设计了这栋楼的立面。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座教堂的立面装饰着精美的石雕。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃立面让整座大楼显得明亮通透。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建筑师把立面改成了简洁的白色。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古典建筑的立面讲究对称与秩序。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在修补这座老楼的立面。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼的立面覆盖着大面积的绿色植物。", "target_word": "立面", "complexity_tier": "T3", "furigana": "zhè dòng lóu de lìmiàn fùgài zhe dà miànjī de lǜsè zhíwù.", "sentence_source": "generated"}, {"text": "立面的比例决定了建筑给人的第一印象。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "立面图", "label": "复合"}, {"form": "正立面", "label": "复合"}, {"form": "侧立面", "label": "复合"}], "register": "书面", "sense_fingerprint": "建筑物朝向外部的一面，正面或侧面，建筑设计用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452fd2d3-7a84-49e7-98fa-c846ef7966d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立面", "is_correct": true, "explanation": "“建筑立面与屋顶”指建筑朝外的一面和屋顶，与绿化系统的语境相符。"}, {"text": "地基", "is_correct": false, "explanation": "语义：地基埋在地下，不是绿化系统的对象，“地基与屋顶的绿化系统”不通。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室位于地下，与“屋顶”并列进行绿化的语境矛盾。"}, {"text": "烟囱", "is_correct": false, "explanation": "搭配：“烟囱与屋顶的绿化系统”搭配不当，烟囱不是常见的绿化面。"}], "explanations": {"立面": "“建筑立面与屋顶”指建筑朝外的一面和屋顶，与绿化系统的语境相符。", "地基": "语义：地基埋在地下，不是绿化系统的对象，“地基与屋顶的绿化系统”不通。", "地下室": "语义：地下室位于地下，与“屋顶”并列进行绿化的语境矛盾。", "烟囱": "搭配：“烟囱与屋顶的绿化系统”搭配不当，烟囱不是常见的绿化面。"}, "sentence_index": 0, "correct_answer": "立面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这座教堂的立面里睡了一夜。", "explanation": "“立面”指建筑朝外的一面，不指可以住人的内部空间，这里应说〈内部〉。"}, {"text": "这栋楼有三只立面。", "explanation": "“立面”作为建筑的一面，量词应用〈个〉，不能用〈只〉。"}, {"text": "这把椅子的立面很平整，人可以坐在上面。", "explanation": "“立面”指建筑朝外的一面，不指椅子的座位，这里应说〈座面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立面", "is_correct": true, "explanation": "“古典建筑的立面讲究对称与秩序”指建筑外观讲究对称，与句意相符。"}, {"text": "地窖", "is_correct": false, "explanation": "语义：地窖在地下，不讲究外观的对称与秩序，与“古典建筑”的语境不符。"}, {"text": "管道", "is_correct": false, "explanation": "搭配：“管道讲究对称”的搭配不当，管道的功能与外观对称无关。"}, {"text": "下水道", "is_correct": false, "explanation": "语义：下水道不是建筑外观的讲究对象，与“对称与秩序”的语境冲突。"}], "explanations": {"立面": "“古典建筑的立面讲究对称与秩序”指建筑外观讲究对称，与句意相符。", "地窖": "语义：地窖在地下，不讲究外观的对称与秩序，与“古典建筑”的语境不符。", "管道": "搭配：“管道讲究对称”的搭配不当，管道的功能与外观对称无关。", "下水道": "语义：下水道不是建筑外观的讲究对象，与“对称与秩序”的语境冲突。"}, "sentence_index": 6, "correct_answer": "立面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的立面很薄，可以放进口袋里。", "explanation": "“立面”指建筑朝外的一面，体积很大，不能装进口袋，这里应说〈砖块〉这类小物件。"}, {"text": "老人家的立面很好看。", "explanation": "“立面”指建筑外墙，不指人的脸，这里应说〈面孔〉。"}, {"text": "这座公园的立面是一大片平坦的草地，孩子们在上面踢足球。", "explanation": "“立面”指建筑朝外的一面，不指平坦的场地，这里应说〈草坪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把这座楼的立面刷了成白色。", "corrected_sentence": "工人把这座楼的立面刷成了白色。", "error_description": "错误形式：“刷了成”。正确形式：“刷成了”。结果补语“成”紧跟动词“刷”，“了”放在补语之后，不能插在“刷”和“成”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人修补了这座老楼的一本立面。", "corrected_sentence": "工人修补了这座老楼的一个立面。", "error_description": "错误形式：“一本立面”。正确形式：“一个立面”。“本”用于书册类，不能用于建筑立面，“立面”的量词用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
