INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在土地上种植花草树木，改善环境，使空气更好、景色更美。", "primary_collocate": null, "pronunciation": "lǜ huà", "ipa": "ly˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "传统意义上被视为“非生产性空间”的公园、社区花园乃至建筑立面与屋顶，正通过多重价值链条被逐步绿化，并深度嵌入城市资本循环。", "target_word": "绿化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "市政府决定绿化这条老街。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在绿化学校后面的空地。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园旁边的路已经绿化好了。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市每年都绿化很多地方。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把河边的荒地绿化了。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿化后的小路，空气清新多了。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让环境更美，我们应该多绿化一些地方。", "target_word": "绿化", "complexity_tier": "T3", "furigana": "wèile ràng huánjìng gèng měi, wǒmen yīnggāi duō lǜhuà yìxiē dìfang.", "sentence_source": "generated"}, {"text": "小区门口绿化得很漂亮。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼前的空地需要绿化。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绿化了", "label": "体标"}, {"form": "绿化过", "label": "体标"}, {"form": "绿化带", "label": "复合"}, {"form": "綠化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "在土地上种花草树木以改善环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“被逐步绿化”指这些空间逐渐被种上植物，与句中“非生产性空间”被改造的语境相合。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“被砍伐”指树木被伐去，与“绿化”的改善环境之义相反，句意不通。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“被污染”与公园、花园的环境意象相反，句意不通。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：“被焚烧”指被烧毁，与改善环境的绿化之义相反。"}], "explanations": {"绿化": "正确：“被逐步绿化”指这些空间逐渐被种上植物，与句中“非生产性空间”被改造的语境相合。", "砍伐": "语义：“被砍伐”指树木被伐去，与“绿化”的改善环境之义相反，句意不通。", "污染": "语义：“被污染”与公园、花园的环境意象相反，句意不通。", "焚烧": "语义：“被焚烧”指被烧毁，与改善环境的绿化之义相反。"}, "sentence_index": 0, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在路边绿化了几棵梧桐。", "explanation": "这里应该用〈种植〉。绿化指使一片地方变绿，不指给某几棵树木种下去。"}, {"text": "园丁绿化了这棵树的枝叶。", "explanation": "这里应该用〈修剪〉。绿化是使地方变绿，不是对枝叶做整理。"}, {"text": "工程师绿化了这块地的面积。", "explanation": "这里应该用〈测量〉。绿化是在土地上种花草树木，不能用于测量面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“绿化后”说明经过绿化处理，与“空气清新多了”的结果相合。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”会使空气变脏，与“空气清新多了”的结果相反。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：被烧毁的小路不会使空气清新，与句中的结果不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”不能带“小路”作宾语，“唱歌后的小路”说不通。"}], "explanations": {"绿化": "正确：“绿化后”说明经过绿化处理，与“空气清新多了”的结果相合。", "污染": "语义：“污染”会使空气变脏，与“空气清新多了”的结果相反。", "烧毁": "语义：被烧毁的小路不会使空气清新，与句中的结果不符。", "唱歌": "配价：“唱歌”不能带“小路”作宾语，“唱歌后的小路”说不通。"}, "sentence_index": 6, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "园艺师栽培了一盆兰花，又绿化了这盆兰花。", "explanation": "这里应该用〈养护〉。绿化是在土地上种花草树木以改善环境，不是对某盆植物的养护。"}, {"text": "农民在地里绿化了小麦。", "explanation": "这里应该用〈播种〉。绿化指让地方变绿，不指种庄稼。"}, {"text": "工人绿化了这块石头。", "explanation": "这里应该用〈抛光〉。绿化是在土地上种植花草树木，不能用于石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条河边的小路已经绿化了好。", "corrected_sentence": "那条河边的小路已经绿化好了。", "error_description": "语序错误：结果补语“好”应放在“绿化”后、“了”前，应说“绿化好了”，不能说“绿化了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把那块空地绿化。", "corrected_sentence": "他们把那块空地绿化了。", "error_description": "结构错误：“把”字句的动词后需要其他成分，如“了”，应说“把那块空地绿化了”，不能只说“把那块空地绿化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
