INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12637, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "资本在运动中依次经过购买、生产、销售三个阶段，并相应采取货币资本、生产资本、商品资本三种职能形式，使价值得到增值，最后回到原来出发点的全过程。", "primary_collocate": null, "pronunciation": "zī běn xún huán", "ipa": "tsɨ˥ pən˨˩˦ ɕyn˧˥ xwan˧˥", "syllable_count": 4, "sentences": [{"text": "传统意义上被视为“非生产性空间”的公园、社区花园乃至建筑立面与屋顶的绿化系统，正通过多重价值链条深度嵌入城市资本循环。", "target_word": "资本循环", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "资本循环要经过购买、生产和销售三个阶段。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货币变成商品，再变回货币，就是资本循环。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家正在研究资本循环的速度。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本循环越快，企业赚钱的机会越多。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书中用一章讲了资本循环的三种形式。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本循环让价值在运动中不断增加。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马克思分析过资本循环的全过程。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的资本循环出现了问题。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本循环停止了，工厂也就没有资金了。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产业资本循环", "label": "复合"}, {"form": "货币资本循环", "label": "复合"}, {"form": "资本循环论", "label": "复合"}], "register": "书面", "sense_fingerprint": "资本经过购买、生产、销售三阶段并增值后回到起点的全过程，政治经济学术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452fd2d3-7a84-49e7-98fa-c846ef7966d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本循环", "is_correct": true, "explanation": "资本循环指资本依次经过购买、生产、销售并回到起点，与“价值链条”“深度嵌入”的经济语境相合。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”是日常休息，与“价值链条”的城市经济语境无关，句中不能说“嵌入城市午睡”。"}, {"text": "星座运势", "is_correct": false, "explanation": "语义：“星座运势”属占卜话题，与“价值链条”的城市经济语境无关，句意不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”口语化，与“深度嵌入”的书面语域不符。"}], "explanations": {"资本循环": "资本循环指资本依次经过购买、生产、销售并回到起点，与“价值链条”“深度嵌入”的经济语境相合。", "午睡": "语义：“午睡”是日常休息，与“价值链条”的城市经济语境无关，句中不能说“嵌入城市午睡”。", "星座运势": "语义：“星座运势”属占卜话题，与“价值链条”的城市经济语境无关，句意不通。", "八卦": "语域：“八卦”口语化，与“深度嵌入”的书面语域不符。"}, "sentence_index": 0, "correct_answer": "资本循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大量资本循环到了新兴市场。", "explanation": "这里应该用〈资本流动〉。资本循环指资本经过购买、生产、销售后回到出发点，不表示资本流向某个地方。"}, {"text": "这家公司把资本循环存进了银行。", "explanation": "这里应该用〈资金〉。资本循环是钱变货、货变钱的过程，不是可以存放的东西；存进银行的是资金。"}, {"text": "仓库里的资本循环很多，卖不出去。", "explanation": "这里应该用〈库存〉。资本循环是过程，不能堆在仓库里；仓库里积压的是库存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本循环", "is_correct": true, "explanation": "资本循环是资本运动的过程，能够让价值在运动中增加，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能让价值在运动中不断增加，与经济过程无关。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不会使价值增加，句中讲的是经济运动。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“让价值增加”通常说投资或劳动带来增值，不说阳光让价值增加。"}], "explanations": {"资本循环": "资本循环是资本运动的过程，能够让价值在运动中增加，符合句意。", "天气": "语义：天气不能让价值在运动中不断增加，与经济过程无关。", "心情": "语义：心情不会使价值增加，句中讲的是经济运动。", "阳光": "搭配：“让价值增加”通常说投资或劳动带来增值，不说阳光让价值增加。"}, "sentence_index": 6, "correct_answer": "资本循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的资本循环正在逐步对外开放。", "explanation": "这里应该用〈资本市场〉。资本循环是资本运动的过程，不是可以对外开放的市场。"}, {"text": "这家公司的资本循环很雄厚，不缺资金。", "explanation": "这里应该用〈资本〉。资本循环指过程，不能用“雄厚”形容；说资金实力强要说“资本雄厚”。"}, {"text": "这笔投资的资本循环很高，利润翻了一番。", "explanation": "这里应该用〈回报率〉。资本循环是过程，不能用“高”来修饰；说回报的高低要用回报率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司完成了三个资本循环。", "corrected_sentence": "这家公司完成了三次资本循环。", "error_description": "量词错误：“资本循环”应用“次”计量，应说“三次资本循环”，不说“三个资本循环”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "资本循环慢起来了，工厂的资金也紧张了。", "corrected_sentence": "资本循环慢下来了，工厂的资金也紧张了。", "error_description": "补语错误：表示速度逐渐减缓要说“慢下来”，“慢起来”不符合用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低端", "is_correct": true, "explanation": "“低端”指档次低，与“高端”构成反义。"}, {"text": "保守", "is_correct": false, "explanation": "不构成反义：“保守”指求稳、不冒进的作风，与“高端”的档次高低无直接对立。"}, {"text": "粗糙", "is_correct": false, "explanation": "不构成反义：“粗糙”指质地不精细，与高端的档次无关。"}, {"text": "陈旧", "is_correct": false, "explanation": "不构成反义：“陈旧”指过时，不是“高端”的反义。"}], "correct_answer": "低端", "explanations": {"低端": "“低端”指档次低，与“高端”构成反义。", "保守": "不构成反义：“保守”指求稳、不冒进的作风，与“高端”的档次高低无直接对立。", "粗糙": "不构成反义：“粗糙”指质地不精细，与高端的档次无关。", "陈旧": "不构成反义：“陈旧”指过时，不是“高端”的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低端", "is_correct": true, "explanation": "“低端”指档次低，与“高端”构成反义。"}, {"text": "厚重", "is_correct": false, "explanation": "不构成反义：“厚重”指分量大或沉稳，与“高端”的档次高低不构成对立。"}, {"text": "陈腐", "is_correct": false, "explanation": "不构成反义：“陈腐”指陈旧守旧，与“高端”的档次无关。"}, {"text": "简朴", "is_correct": false, "explanation": "不构成反义：“简朴”指不奢华，与“高端”的档次高低不构成对立。"}], "correct_answer": "低端", "explanations": {"低端": "“低端”指档次低，与“高端”构成反义。", "厚重": "不构成反义：“厚重”指分量大或沉稳，与“高端”的档次高低不构成对立。", "陈腐": "不构成反义：“陈腐”指陈旧守旧，与“高端”的档次无关。", "简朴": "不构成反义：“简朴”指不奢华，与“高端”的档次高低不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物在同类中处于较高水平或档次。", "primary_collocate": null, "pronunciation": "gāo duān", "ipa": "kau˥ twan˥", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "高端", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "土地用途的混合开发（mixed-use development）正被重新定义：商业综合体整合垂直农场不再仅是企业社会责任的展示，而成为吸引高端租户、提升品牌粘性的商业策略。", "target_word": "高端", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司专门生产高端手机。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高端市场对产品质量要求很严格。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家银行为高端客户提供专属服务。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店主要接待高端商务客人。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高端人才是各国企业争抢的对象。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市正在发展高端制造业。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高端住宅通常有更好的景观和服务。", "target_word": "高端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司决定把产品定位在高端市场。", "target_word": "高端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高端产品", "label": "复合"}, {"form": "高端市场", "label": "复合"}, {"form": "高端化", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物在同类中水平或档次较高，多作定语修饰产品、客户、市场等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452fd2d3-7a84-49e7-98fa-c846ef7966d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高端", "is_correct": true, "explanation": "“高端房地产项目”指档次高的项目，与“市场溢价”“景观资源”的语境相合。"}, {"text": "廉价", "is_correct": false, "explanation": "语义：“廉价”与“市场溢价”的高价值语境相反。"}, {"text": "古老", "is_correct": false, "explanation": "语义：“古老”与“景观资源驱动”“价值提升”的现代房地产语境不符。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：“慢性”一般只修饰疾病，不修饰房地产项目。"}], "explanations": {"高端": "“高端房地产项目”指档次高的项目，与“市场溢价”“景观资源”的语境相合。", "廉价": "语义：“廉价”与“市场溢价”的高价值语境相反。", "古老": "语义：“古老”与“景观资源驱动”“价值提升”的现代房地产语境不符。", "慢性": "搭配：“慢性”一般只修饰疾病，不修饰房地产项目。"}, "sentence_index": 0, "correct_answer": "高端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树很高端，有二十米。", "explanation": "这里应该用〈高〉。高端指档次，不用于说树的高矮；说树高要用“高”。"}, {"text": "他的品德很高端，大家都敬佩他。", "explanation": "这里应该用〈高尚〉。高端指事物的档次，不用于形容人的品德。"}, {"text": "这台机器的效率很高端。", "explanation": "这里应该用〈高效〉。高端不修饰效率，说效率高要用“高效”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高端", "is_correct": true, "explanation": "“高端人才”指档次高的人才，与“争抢的对象”的语境相合。"}, {"text": "低端", "is_correct": false, "explanation": "语义：“低端人才”不会成为各国企业争抢的对象，与句意相悖。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”形容条件或设施，不修饰人才。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时，与“争抢”的语境冲突。"}], "explanations": {"高端": "“高端人才”指档次高的人才，与“争抢的对象”的语境相合。", "低端": "语义：“低端人才”不会成为各国企业争抢的对象，与句意相悖。", "简陋": "搭配：“简陋”形容条件或设施，不修饰人才。", "陈旧": "语义：“陈旧”指过时，与“争抢”的语境冲突。"}, "sentence_index": 6, "correct_answer": "高端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩很高端，老师很满意。", "explanation": "这里应该用〈优秀〉。高端指档次，不用于形容成绩好坏。"}, {"text": "这座城市的人口很高端，增长得很快。", "explanation": "这里应该用〈多〉。高端指档次，不用于说人口的多少；说人口多要用“多”。"}, {"text": "这个地区的资源很高端，开发价值很大。", "explanation": "这里应该用〈丰富〉。高端指档次，不用于说资源多少；资源多要用“丰富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款很高端手表很受欢迎。", "corrected_sentence": "这款很高端的手表很受欢迎。", "error_description": "结构助词“的”漏掉：“很高端”修饰名词“手表”时中间要加“的”，应说“很高端的手表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司正在推进产品高端。", "corrected_sentence": "这家公司正在推进产品高端化。", "error_description": "词形不完整：表示使产品向高档方向发展要说“高端化”，漏掉“化”不符合用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb70ffd-246b-4cfe-b671-c3c48a09625f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指商品或证券的实际成交价格超出其面值或正常价值的部分。", "primary_collocate": null, "pronunciation": "yì jià", "ipa": "i˥˩ tɕia˥˩", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "溢价", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的股票以溢价发行，每股比面值高两元。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新股上市首日，溢价达到了百分之三十。", "target_word": "溢价", "complexity_tier": "T3", "furigana": "xīn gǔ shàng shì shǒu rì, yì jià dá dào le bǎi fēn zhī sān shí.", "sentence_source": "generated"}, {"text": "这套房子的学区溢价很高，价格比邻近楼盘贵。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收购方愿意付出溢价，因为想控制这家公司。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只债券的成交价高于面值，溢价部分是五元。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "品牌带来的溢价，让这款包卖得更贵。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司以高出市价一成的溢价回购了股份。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资者担心这只基金的溢价太高，风险很大。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次增发的溢价不高，股民都愿意买。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "溢價", "label": "繁体"}, {"form": "溢价率", "label": "复合"}, {"form": "溢价发行", "label": "复合"}], "register": "书面", "sense_fingerprint": "溢价：商品或证券成交价高出面值或正常价值的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b4509d-b7bc-4e10-b48e-a01079069c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：溢价指成交价高出面值或正常价值的部分。"}, {"text": "衣架", "is_correct": false, "explanation": "「溢」与「衣」声调不同（第四声与第一声），意思是挂衣服的架子。"}, {"text": "意见", "is_correct": false, "explanation": "「价」与「见」韵母不同（jià 与 jiàn），意思是对事情的看法。"}, {"text": "一家", "is_correct": false, "explanation": "「价」与「家」声调不同（第四声与第一声），意思是一个家庭。"}, {"text": "移家", "is_correct": false, "explanation": "两个音节声调都不同（「溢」第四声、「移」第二声；「价」第四声、「家」第一声），意思是搬家。"}], "explanations": {"溢价": "正确：溢价指成交价高出面值或正常价值的部分。", "衣架": "「溢」与「衣」声调不同（第四声与第一声），意思是挂衣服的架子。", "意见": "「价」与「见」韵母不同（jià 与 jiàn），意思是对事情的看法。", "一家": "「价」与「家」声调不同（第四声与第一声），意思是一个家庭。", "移家": "两个音节声调都不同（「溢」第四声、「移」第二声；「价」第四声、「家」第一声），意思是搬家。"}, "sentence_index": null, "correct_answer": "溢价"}, "level_3": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：溢价指超出正常价值的部分，可以修饰「机制」，与景观驱动价值提升相符。"}, {"text": "户型", "is_correct": false, "explanation": "语义：户型指房屋的格局，与驱动价值提升的市场机制无关。"}, {"text": "朝向", "is_correct": false, "explanation": "语义：朝向指房屋面对的方向，并不是推动价格上涨的机制。"}, {"text": "税费", "is_correct": false, "explanation": "搭配：税费不能作为驱动价值提升的机制，与景观资源的驱动不搭配。"}], "explanations": {"溢价": "正确：溢价指超出正常价值的部分，可以修饰「机制」，与景观驱动价值提升相符。", "户型": "语义：户型指房屋的格局，与驱动价值提升的市场机制无关。", "朝向": "语义：朝向指房屋面对的方向，并不是推动价格上涨的机制。", "税费": "搭配：税费不能作为驱动价值提升的机制，与景观资源的驱动不搭配。"}, "sentence_index": 0, "correct_answer": "溢价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故后，公司给我们很高的溢价。", "explanation": "这里应该用〈赔偿〉。赔偿是因损失而给的钱，溢价指成交价超出正常价值的部分，不能用来指事故后的赔偿。"}, {"text": "银行存款的溢价很高，存钱很划算。", "explanation": "这里应该用〈利息〉。溢价只用于商品或证券成交价高出面值的部分，存款的收益不能说溢价。"}, {"text": "参加这个俱乐部，每年要交很多溢价。", "explanation": "这里应该用〈会费〉。会费是加入组织后定期交的钱，溢价只用于商品或证券成交价超出正常价值的部分，不能指会费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：品牌带来的超出正常价格的部分，让这款包卖得更贵。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：尺寸与价格高低没有直接关系，不是品牌带来的价格部分。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：品牌带来的是价值，不能说带来重量，与「卖得更贵」也不搭。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色本身不会让包卖得更贵，与前文品牌的作用不符。"}], "explanations": {"溢价": "正确：品牌带来的超出正常价格的部分，让这款包卖得更贵。", "尺寸": "语义：尺寸与价格高低没有直接关系，不是品牌带来的价格部分。", "重量": "搭配：品牌带来的是价值，不能说带来重量，与「卖得更贵」也不搭。", "颜色": "语义：颜色本身不会让包卖得更贵，与前文品牌的作用不符。"}, "sentence_index": 6, "correct_answer": "溢价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "租房子要交溢价，退房时再还给你。", "explanation": "这里应该用〈押金〉。押金退房时要退还，溢价是成交价超出面值的部分，不能用来表示押金。"}, {"text": "他每个月拿溢价，生活很稳定。", "explanation": "这里应该用〈工资〉。工资是劳动报酬，溢价是商品或证券成交价超出正常价值的部分，不能用来指工资。"}, {"text": "给服务员一点溢价，表示感谢。", "explanation": "这里应该用〈小费〉。小费是给服务的额外钱，溢价指成交价高出正常价值的部分，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只溢价一共是五元。", "corrected_sentence": "这笔溢价一共是五元。", "error_description": "量词错误：溢价应该用量词「笔」，写成「只」是误用。「只」多用于动物或成对物品中的一个，不能修饰溢价。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "收购方愿意溢价，比市价高。", "corrected_sentence": "收购方愿意付出溢价，比市价高。", "error_description": "漏词错误：「愿意」后面缺少动词「付出」，名词「溢价」不能直接接在「愿意」之后。补上「付出」即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
