INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一定区域内的自然景色或人工建筑的整体面貌。", "primary_collocate": null, "pronunciation": "jǐng guān", "ipa": "tɕiŋ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "景观", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个公园的自然景观很美，吸引了很多游客。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河穿过城市，形成了独特的城市景观。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼越来越多，老城的景观变了很多。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湿地的景观有山有水，很适合拍照。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想保护古镇的历史景观。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的景观随着季节不断变化。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是江边最有名的人文景观。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂建在湖边，破坏了这里的自然景观。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区修了新公路，当地的景观有了变化。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "景觀", "label": "繁体"}, {"form": "处", "label": "量词"}, {"form": "景观设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "景观：一定区域内自然景色或人工建筑构成的整体面貌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b4509d-b7bc-4e10-b48e-a01079069c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "景观", "is_correct": true, "explanation": "正确：「景观资源」指一定区域内的自然景色，能驱动价值提升，与绿地的描写相符。"}, {"text": "噪声", "is_correct": false, "explanation": "语义：噪声会降低住宅价值，不能驱动价值提升，与前文的意思相反。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染会降低房产价值，与「驱动价值提升」的意思矛盾。"}, {"text": "户型", "is_correct": false, "explanation": "搭配：户型是房屋的格局，不能说「户型资源」。"}], "explanations": {"景观": "正确：「景观资源」指一定区域内的自然景色，能驱动价值提升，与绿地的描写相符。", "噪声": "语义：噪声会降低住宅价值，不能驱动价值提升，与前文的意思相反。", "污染": "语义：污染会降低房产价值，与「驱动价值提升」的意思矛盾。", "户型": "搭配：户型是房屋的格局，不能说「户型资源」。"}, "sentence_index": 0, "correct_answer": "景观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的景观很好看，大家都夸他。", "explanation": "这里应该用〈外貌〉。景观指一定区域的自然景色或建筑面貌，形容人的样子不能用景观。"}, {"text": "这道菜的景观很鲜，大家都爱吃。", "explanation": "这里应该用〈味道〉。景观指地区的景色或建筑面貌，不能用来形容菜的味道。"}, {"text": "这件衣服的景观很漂亮。", "explanation": "这里应该用〈外观〉。外观指物品的样子和形状，景观指地区的景色或建筑面貌，不能用来形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景观", "is_correct": true, "explanation": "正确：草原上的景色随季节变化，符合句子的意思。"}, {"text": "股价", "is_correct": false, "explanation": "语义：股价属于证券市场，与草原的季节变化无关。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：学历不会随季节变化，不能和「随着季节不断变化」搭配。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，与草原的季节变化无关。"}], "explanations": {"景观": "正确：草原上的景色随季节变化，符合句子的意思。", "股价": "语义：股价属于证券市场，与草原的季节变化无关。", "学历": "搭配：学历不会随季节变化，不能和「随着季节不断变化」搭配。", "字体": "语义：字体是文字的样式，与草原的季节变化无关。"}, "sentence_index": 6, "correct_answer": "景观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛他的景观很好，拿了第一名。", "explanation": "这里应该用〈成绩〉。景观指地区的景色或建筑面貌，不能用来形容比赛的成绩。"}, {"text": "他说话的景观很快，大家都听得很清楚。", "explanation": "这里应该用〈语速〉。景观指地区的景色，不能形容说话的快慢。"}, {"text": "这首歌的景观很好听，我常常唱。", "explanation": "这里应该用〈歌声〉。景观指地区的景色，不能形容歌声好不好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖边这只景观很美，游客常来拍照。", "corrected_sentence": "湖边这处景观很美，游客常来拍照。", "error_description": "量词错误：景观应该用量词「处」，写成「只」是误用。「只」用于动物或成对物品中的一个，不能修饰景观。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古塔是城里最有名的一条人文景观。", "corrected_sentence": "这座古塔是城里最有名的一处人文景观。", "error_description": "量词错误：景观应该用量词「处」，「条」多用于河流、道路等长条形事物，不能修饰景观。正确：「一处人文景观」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
