INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12641, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指相邻，紧挨着，互相连接。", "primary_collocate": null, "pronunciation": "pí lín", "ipa": "pʰi˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "毗邻", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这所大学毗邻一条大河，风景很美。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越南北部毗邻中国的广西和云南。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院毗邻地铁站，交通很方便。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香港毗邻深圳，两地来往很频繁。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家毗邻一座公园，每天都能散步。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毗邻海边的酒店，价格往往比较高。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区毗邻商场，买东西不用走远。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个省份毗邻，经济联系非常紧密。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机场毗邻高速公路，去市区只要半小时。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毗鄰", "label": "繁体"}, {"form": "毗邻着", "label": "体标"}], "register": "书面", "sense_fingerprint": "毗邻：两地或两处相邻，紧挨着并相互连接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b4509d-b7bc-4e10-b48e-a01079069c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毗邻", "is_correct": true, "explanation": "正确：“毗邻”指紧挨着、相连，此处说住宅单元与高品质绿地相邻，符合句意。"}, {"text": "远离", "is_correct": false, "explanation": "语义：远离与毗邻意思相反，远离绿地不会带来价值提升。"}, {"text": "污染", "is_correct": false, "explanation": "搭配：“污染”不能与“高品质绿地”搭配，句中讲的是绿地的价值。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：“损坏”指使东西受损，与“价值提升”相矛盾。"}], "explanations": {"毗邻": "正确：“毗邻”指紧挨着、相连，此处说住宅单元与高品质绿地相邻，符合句意。", "远离": "语义：远离与毗邻意思相反，远离绿地不会带来价值提升。", "污染": "搭配：“污染”不能与“高品质绿地”搭配，句中讲的是绿地的价值。", "损坏": "语义：“损坏”指使东西受损，与“价值提升”相矛盾。"}, "sentence_index": 0, "correct_answer": "毗邻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他慢慢毗邻我走了过来。", "explanation": "这里应该用〈靠近〉。毗邻指两处位置挨在一起、固定相连，不能描述人主动走近。"}, {"text": "期末考试毗邻了，他更加努力地复习。", "explanation": "这里应该用〈临近〉。毗邻只用于空间上的挨着，不能说时间上的接近。"}, {"text": "他毗邻我坐下，一直没说话。", "explanation": "这里应该用〈挨着〉。毗邻是书面语，指地点相连，不用于两人并排坐下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毗邻", "is_correct": true, "explanation": "正确：“毗邻”指挨着海边，说明酒店的位置，与“价格往往比较高”的语境一致。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指毁坏，与“价格往往比较高”的语境相矛盾。"}, {"text": "遗弃", "is_correct": false, "explanation": "语义：“遗弃”指丢下不管，与酒店价格高的说法无法相合。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”多用于人或动物，不能与“酒店”搭配。"}], "explanations": {"毗邻": "正确：“毗邻”指挨着海边，说明酒店的位置，与“价格往往比较高”的语境一致。", "破坏": "语义：“破坏”指毁坏，与“价格往往比较高”的语境相矛盾。", "遗弃": "语义：“遗弃”指丢下不管，与酒店价格高的说法无法相合。", "驱赶": "搭配：“驱赶”多用于人或动物，不能与“酒店”搭配。"}, "sentence_index": 6, "correct_answer": "毗邻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的头毗邻我的肩膀，很温暖。", "explanation": "这里应该用〈靠〉。毗邻指两个地点相连，不能用来形容人的头部倚靠在别人肩上。"}, {"text": "周末我去毗邻奶奶。", "explanation": "这里应该用〈看望〉。毗邻只表示地点挨着，不能表示去探望某人。"}, {"text": "他毗邻栏杆慢慢走。", "explanation": "这里应该用〈沿着〉。毗邻表示两处位置相连、静止地挨着，不能表示人顺着栏杆移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所小学很毗邻一片树林，环境很安静。", "corrected_sentence": "这所小学毗邻一片树林，环境很安静。", "error_description": "错误：“很”修饰动词“毗邻”。正确：去掉“很”，说“这所小学毗邻一片树林”。“毗邻”是动词，不能直接被程度副词修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼在毗邻一片花园，视野很好。", "corrected_sentence": "这栋楼毗邻一片花园，视野很好。", "error_description": "错误：“在”表示动作正在进行，而“毗邻”表示静态的相邻关系，不能加“在”。正确：去掉“在”，说“这栋楼毗邻一片花园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
