INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12642, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指质量优良、水平高的。", "primary_collocate": null, "pronunciation": "gāo pǐn zhì", "ipa": "kɑʊ˥ pʰin˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "高品质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店卖的都是高品质的茶叶。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一台高品质的相机。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店为客人提供高品质的住宿环境。", "target_word": "高品质", "complexity_tier": "T3", "furigana": "zhè jiā jiǔdiàn wèi kèrén tígōng gāo pǐn zhì de zhùsù huánjìng。", "sentence_source": "generated"}, {"text": "他们公司只做高品质的家具。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种高品质的牛奶价格有点贵。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的酒店要给客人高品质的服务。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢用高品质的材料做蛋糕。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高品质的产品不会很快坏掉。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了高品质的生活，他努力工作。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高品質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "质量优良、水平高的，多作定语，修饰产品、服务、生活等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b4509d-b7bc-4e10-b48e-a01079069c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高品质", "is_correct": true, "explanation": "正确：“高品质”修饰“绿地”，指质量优良，与“高端房地产”和“价值提升”的语境相符。"}, {"text": "劣质", "is_correct": false, "explanation": "语义：“劣质”指质量低劣，与“高端”和“价值提升”正相反。"}, {"text": "低档", "is_correct": false, "explanation": "语义：“低档”指等级低，与“高端房地产项目”的语境冲突。"}, {"text": "廉价", "is_correct": false, "explanation": "搭配：“廉价”多修饰商品或价格，不说“廉价绿地”。"}], "explanations": {"高品质": "正确：“高品质”修饰“绿地”，指质量优良，与“高端房地产”和“价值提升”的语境相符。", "劣质": "语义：“劣质”指质量低劣，与“高端”和“价值提升”正相反。", "低档": "语义：“低档”指等级低，与“高端房地产项目”的语境冲突。", "廉价": "搭配：“廉价”多修饰商品或价格，不说“廉价绿地”。"}, "sentence_index": 0, "correct_answer": "高品质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被提拔为公司的高品质经理。", "explanation": "这里应该用〈高级〉。高品质说的是质量好，不用于说职位高低，职位要说“高级”。"}, {"text": "这个孩子的学习成绩很高品质。", "explanation": "这里应该用〈优秀〉。高品质用于物品或服务的质量，不用于评价学生的成绩。"}, {"text": "这个主意很高品质，大家都很佩服。", "explanation": "这里应该用〈高明〉。高品质只说质量好，不用于评价想法或主意的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高品质", "is_correct": true, "explanation": "正确：“高品质”修饰“服务”，指质量好，与“好的酒店”的语境相符。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指不细致、不精致，与“好的酒店”的语境相反。"}, {"text": "低俗", "is_correct": false, "explanation": "语义：“低俗”指格调低，与“好的酒店”给客人提供的服务相矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多修饰负担、压力，不说“沉重的服务”。"}], "explanations": {"高品质": "正确：“高品质”修饰“服务”，指质量好，与“好的酒店”的语境相符。", "粗糙": "语义：“粗糙”指不细致、不精致，与“好的酒店”的语境相反。", "低俗": "语义：“低俗”指格调低，与“好的酒店”给客人提供的服务相矛盾。", "沉重": "搭配：“沉重”多修饰负担、压力，不说“沉重的服务”。"}, "sentence_index": 6, "correct_answer": "高品质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的品德很高品质，大家都尊敬他。", "explanation": "这里应该用〈高尚〉。高品质只用于物品或服务的质量，不用于形容人的品德。"}, {"text": "这个办法很高品质，大家都在用。", "explanation": "这里应该用〈高效〉。高品质说质量好，不用来说方法的效率高。"}, {"text": "他这次数学考试考了高品质的分数。", "explanation": "这里应该用〈高分〉。高品质用于物品或服务的质量，不用于形容考试的分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批钢材的品质是高品质的。", "corrected_sentence": "这批钢材是高品质的。", "error_description": "语义重复：「品质」与「高品质」重复。正确：去掉「的品质」，说「这批钢材是高品质的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她希望全家人过上高品质着的生活。", "corrected_sentence": "她希望全家人过上高品质的生活。", "error_description": "错误：“着”不能用在定语“高品质”后面。正确：去掉“着”，说“高品质的生活”，“的”用来连接定语和后面的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
