INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中种植花草树木、供人们休闲或改善环境的场地。", "primary_collocate": null, "pronunciation": "lǜ dì", "ipa": "ly˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "在当代大都市的发展图景中，城市绿地与垂直农场已超越其单纯的生态功能，演变为重塑经济地理格局的战略性要素。", "target_word": "绿地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "绿地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "绿地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家旁边有一大片绿地。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末，孩子们在绿地上玩球。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的绿地让空气更好。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府在小区门口建了一块绿地。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的绿地越来越多。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班后，他常去小区的绿地散步。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人们坐在绿地旁边聊天。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "城市绿地", "label": "复合"}, {"form": "綠地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里种花草树木、供休闲和改善环境的场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b4509d-b7bc-4e10-b48e-a01079069c55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12643, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。绿地指城市中种植花草树木、供人休闲的场地，读作 lǜ dì。"}, {"text": "陆地", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是陆上的地面，与城市绿地无关。"}, {"text": "绿堤", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是河岸或湖边的堤坝。"}, {"text": "绿带", "is_correct": false, "explanation": "dài 与 dì 韵母不同，意思是带状的绿色区域，不是供人休闲的场地。"}], "explanations": {"绿地": "正确。绿地指城市中种植花草树木、供人休闲的场地，读作 lǜ dì。", "陆地": "lù 与 lǜ 韵母不同（u 与 ü），意思是陆上的地面，与城市绿地无关。", "绿堤": "dī（第一声）与 dì（第四声）声调不同，意思是河岸或湖边的堤坝。", "绿带": "dài 与 dì 韵母不同，意思是带状的绿色区域，不是供人休闲的场地。"}, "sentence_index": null, "correct_answer": "绿地"}, "level_3": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。句中指城市里种植花草树木的场地，与「生态功能」「战略性要素」的语境相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通设施，没有可以「超越」的生态功能，句意不通。"}, {"text": "垃圾场", "is_correct": false, "explanation": "语义：垃圾场与「生态功能」的正面语境相反，不能作为「重塑经济地理格局」的要素。"}, {"text": "大院", "is_correct": false, "explanation": "语域：「大院」是口语化说法，与这段书面语的语域不符，也不指城市中的生态空间。"}], "explanations": {"绿地": "正确。句中指城市里种植花草树木的场地，与「生态功能」「战略性要素」的语境相符。", "地铁": "语义：地铁是交通设施，没有可以「超越」的生态功能，句意不通。", "垃圾场": "语义：垃圾场与「生态功能」的正面语境相反，不能作为「重塑经济地理格局」的要素。", "大院": "语域：「大院」是口语化说法，与这段书面语的语域不符，也不指城市中的生态空间。"}, "sentence_index": 0, "correct_answer": "绿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家旁边有一座大绿地。", "explanation": "这里应该用〈片〉或〈块〉。座多用于山、楼、桥等大型实体，绿地是一片场地，不用「座」。"}, {"text": "我们小区里有一棵大绿地。", "explanation": "这里应该用〈片〉或〈块〉。棵用于树等单株植物，绿地是一片场地，不是一棵植物。"}, {"text": "我家窗外有一朵大绿地。", "explanation": "这里应该用〈片〉或〈块〉。朵用于花、云等，绿地是城市中的场地，不用「朵」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。「建了一块」指修建出的一片场地，只有绿地符合。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是票据，不能被修建成一块场地，句意不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯设备，不能被修建成一块场地。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，不是可以被修建出来的地方，句意不通。"}], "explanations": {"绿地": "正确。「建了一块」指修建出的一片场地，只有绿地符合。", "发票": "语义：发票是票据，不能被修建成一块场地，句意不通。", "电话": "语义：电话是通讯设备，不能被修建成一块场地。", "诗歌": "语义：诗歌是文学作品，不是可以被修建出来的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "绿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅里摆着一块漂亮的绿地。", "explanation": "这里应该用〈盆景〉。盆景是可以搬进室内的小型植物造景，绿地是城市里固定的公共场地，不能摆进客厅。"}, {"text": "阳台上摆了很多绿地。", "explanation": "这里应该用〈绿植〉。绿植是可以搬动的盆栽植物，绿地是固定在城市中的场地，不能摆在阳台上。"}, {"text": "他把绿地插进了花瓶里。", "explanation": "这里应该用〈花束〉。插进花瓶的是花束，绿地是场地，不能插进花瓶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园旁边有一座绿地。", "corrected_sentence": "公园旁边有一块绿地。", "error_description": "「绿地」的量词应为「块」（或「片」），不应用「座」。「座」用于山、楼、桥等大型固定建筑或物体，错用「座」是学习者常见的量词误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些绿地们都很干净。", "corrected_sentence": "这些绿地都很干净。", "error_description": "「们」只用于指人或有生命的群体，绿地是无生命的场所，名词后不能加「们」，应直接说「这些绿地」。学习者常把「们」套用到所有名词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d65fa-eb1f-4f7b-82f1-c1bd6e6bb0e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
