INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指整体中相对独立、自成系统的部分，常指房屋、课程或组织的组成单位。", "primary_collocate": null, "pronunciation": "dān yuán", "ipa": "tan˥˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "单元", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家住在三号楼二单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书一共有十个单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个单元学完，老师都会考试。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单元有两个卧室和一个客厅。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，五单元怎么走？", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼每个单元都有电梯。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第三单元讲的是环境问题。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司分成三个单元，各有各的工作。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一单元门口等我。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "单元楼", "label": "复合"}, {"form": "单元房", "label": "复合"}], "register": "中性", "sense_fingerprint": "单元|整体中相对独立的组成部分（房屋、课程、组织）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“住宅单元”指住宅楼中一个相对独立的住户部分，与句中的“住宅”“价值提升”相合。"}, {"text": "厂房", "is_correct": false, "explanation": "搭配：“住宅”不修饰“厂房”，且厂房与句中“毗邻高品质绿地”带来的价值提升无关。"}, {"text": "垃圾站", "is_correct": false, "explanation": "语义：垃圾站与“高品质绿地”“价值提升”的意思相反，句子无法成立。"}, {"text": "工地", "is_correct": false, "explanation": "语义：住宅工地是施工场所，不是能够“实现价值提升”的住宅单位。"}], "explanations": {"单元": "正确：“住宅单元”指住宅楼中一个相对独立的住户部分，与句中的“住宅”“价值提升”相合。", "厂房": "搭配：“住宅”不修饰“厂房”，且厂房与句中“毗邻高品质绿地”带来的价值提升无关。", "垃圾站": "语义：垃圾站与“高品质绿地”“价值提升”的意思相反，句子无法成立。", "工地": "语义：住宅工地是施工场所，不是能够“实现价值提升”的住宅单位。"}, "sentence_index": 0, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本单元一共有五层楼。", "explanation": "量词〈本〉用于书籍，不能修饰“单元”，这里应该用〈个〉。"}, {"text": "那只单元里住着三户人家。", "explanation": "量词〈只〉用于动物，不能修饰表示住宅组成部分的“单元”，这里应该用〈个〉。"}, {"text": "长度的单元是米。", "explanation": "这里应该用〈单位〉。计量标准说“单位”，“单元”不用于度量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“每个单元”指楼中的一个住户部分，都可以配有电梯，与句意相合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是楼内的居住空间，电梯属于楼或单元，说“每个房间都有电梯”不合常理。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”与“电梯”没有“拥有”的关系，“每个窗户都有电梯”不成立。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶不是可以配备电梯的建筑部分，与句意不合。"}], "explanations": {"单元": "正确：“每个单元”指楼中的一个住户部分，都可以配有电梯，与句意相合。", "房间": "语义：房间是楼内的居住空间，电梯属于楼或单元，说“每个房间都有电梯”不合常理。", "窗户": "搭配：“窗户”与“电梯”没有“拥有”的关系，“每个窗户都有电梯”不成立。", "垃圾桶": "语义：垃圾桶不是可以配备电梯的建筑部分，与句意不合。"}, "sentence_index": 6, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个单元有五条街，离地铁很近。", "explanation": "这里应该用〈小区〉。“单元”是楼内的一部分，不能包含多条街；整片住宅区要说“小区”。"}, {"text": "这辆单元的门口停着三辆自行车。", "explanation": "量词〈辆〉用于车辆，不能修饰“单元”，这里应该用〈个〉。"}, {"text": "这台单元有电梯。", "explanation": "量词〈台〉用于机器、设备，不用于住宅的组成部分，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只单元的门口每天都很热闹。", "corrected_sentence": "这个单元的门口每天都很热闹。", "error_description": "量词错误：“单元”应搭配通用量词“个”，“只”是动物量词，不能修饰住宅的组成部分。正确说法是“这个单元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座单元里住着二十户人家。", "corrected_sentence": "那个单元里住着二十户人家。", "error_description": "量词错误：“单元”是楼中的一部分，应用“个”。“座”多用于大型建筑、山桥，不能修饰“单元”。正确说法是“那个单元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
