INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中可用于建设的有限空间，具有高经济价值", "primary_collocate": null, "pronunciation": "tǔ dì", "ipa": "tʰu˨˩˦ ti˥˩", "syllable_count": 2, "sentences": [{"text": "城市中心的土地很贵。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块土地要建一所新学校。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的土地越来越少了。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司花了很多钱买下这块土地。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的土地价格每年都在涨。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府准备把这块土地卖给开发商。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心已经没有空的土地了。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想在这块土地上盖一座商场。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买土地要花很多钱，所以房子也贵。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地少，所以城市里的楼越盖越高。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "土地使用权", "label": "复合"}], "register": "中性", "sense_fingerprint": "城市建设用地，有限且昂贵的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0895758-7575-4f3f-b486-94a8a11fbda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。土地 tǔ dì 指城市中可用于建设的有限空间。"}, {"text": "徒弟", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。"}, {"text": "土堤", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是泥土筑成的堤坝。"}, {"text": "土质", "is_correct": false, "explanation": "zhì 与 dì 声母不同（zh 与 d），意思是土壤的性质。"}], "explanations": {"土地": "正确答案。土地 tǔ dì 指城市中可用于建设的有限空间。", "徒弟": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。", "土堤": "dī（第一声）与 dì（第四声）声调不同，意思是泥土筑成的堤坝。", "土质": "zhì 与 dì 声母不同（zh 与 d），意思是土壤的性质。"}, "sentence_index": null, "correct_answer": "土地"}, "level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。土地指可用于建设的城市空间，“城市中心的土地很贵”成立。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不在城市中心，也不是可以用价格衡量的空间，句子不成立。"}, {"text": "森林", "is_correct": false, "explanation": "搭配：“很贵”多用于可以买卖的东西，森林一般不说价格很贵。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是城市中心的一块空间，也不能说很贵。"}], "explanations": {"土地": "正确答案。土地指可用于建设的城市空间，“城市中心的土地很贵”成立。", "大海": "语义：大海不在城市中心，也不是可以用价格衡量的空间，句子不成立。", "森林": "搭配：“很贵”多用于可以买卖的东西，森林一般不说价格很贵。", "老虎": "语义：老虎是动物，不是城市中心的一块空间，也不能说很贵。"}, "sentence_index": 0, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车到站时，这块土地上下来了很多乘客。", "explanation": "这里应该用〈站台〉。土地指可用于建设的城市空间，不能用作乘客上下车的地方，说乘客上下车要用“站台”。"}, {"text": "这块土地每天生产上千台机器。", "explanation": "这里应该用〈工厂〉。土地指可用于建设的空间，本身不能生产东西，说生产机器的地方要用“工厂”。"}, {"text": "我花钱买了一头土地。", "explanation": "这里应该用〈块〉。“头”用于大型牲畜，不能用于土地；计量土地常用“块”或“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12646, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。土地 tǔ dì 指城市中可用于建设的有限空间。"}, {"text": "徒弟", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。"}, {"text": "土气", "is_correct": false, "explanation": "qì 与 dì 声母不同（q 与 d），意思是样式不时髦。"}, {"text": "吐气", "is_correct": false, "explanation": "首字 tǔ 相同，但 qì 与 dì 声母不同，意思是呼出气息。"}], "explanations": {"土地": "正确答案。土地 tǔ dì 指城市中可用于建设的有限空间。", "徒弟": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。", "土气": "qì 与 dì 声母不同（q 与 d），意思是样式不时髦。", "吐气": "首字 tǔ 相同，但 qì 与 dì 声母不同，意思是呼出气息。"}, "sentence_index": null, "correct_answer": "土地"}, "level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。“市中心已经没有空的土地了”成立，土地指可用于建设的空间。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是可以“空”出来供建设的空间，句子不成立。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“空的”多用来形容空间或位置，蛋糕不能说空的。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能用来指市中心可建设的空间。"}], "explanations": {"土地": "正确答案。“市中心已经没有空的土地了”成立，土地指可用于建设的空间。", "河流": "语义：河流不是可以“空”出来供建设的空间，句子不成立。", "蛋糕": "搭配：“空的”多用来形容空间或位置，蛋糕不能说空的。", "钢琴": "语义：钢琴是乐器，不能用来指市中心可建设的空间。"}, "sentence_index": 6, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块土地写得很好，大家都很喜欢。", "explanation": "这里应该用〈文章〉。土地指可用于建设的空间，不能作为作品被评价；说作品写得好要用“文章”。"}, {"text": "这块土地里有很多人在游泳。", "explanation": "这里应该用〈游泳池〉。土地指可用于建设的空间，不能用来游泳，说在水里游泳要用“游泳池”。"}, {"text": "他们花钱买了一个土地。", "explanation": "这里应该用〈块〉。“个”是通用量词，不用于计量土地，土地常用“块”或“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司在郊区买了一个土地。", "corrected_sentence": "这家公司在郊区买了一块土地。", "error_description": "量词错误：“土地”应该用“块”计量。“个”是通用量词，不能用于土地，应说“一块土地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府在城外划出了一只土地。", "corrected_sentence": "政府在城外划出了一块土地。", "error_description": "量词错误：“只”多用于动物，土地应该用“块”计量，应说“一块土地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确答案。充足指数量足够，与“稀缺”构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软描写质地，与稀缺的数量含义无关，不构成反义。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰描写清楚的程度，与稀缺没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭描写地势，与稀缺没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确答案。充足指数量足够，与“稀缺”构成反义。", "柔软": "柔软描写质地，与稀缺的数量含义无关，不构成反义。", "清晰": "清晰描写清楚的程度，与稀缺没有反义关系。", "陡峭": "陡峭描写地势，与稀缺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确答案。充足指数量足够，与“稀缺”构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙描写表面质地，与稀缺没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "漫长描写时间的长度，与稀缺没有反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮描写声音，与稀缺没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确答案。充足指数量足够，与“稀缺”构成反义。", "粗糙": "粗糙描写表面质地，与稀缺没有反义关系。", "漫长": "漫长描写时间的长度，与稀缺没有反义关系。", "响亮": "响亮描写声音，与稀缺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容东西很少，不够人们需要。", "primary_collocate": null, "pronunciation": "xī quē", "ipa": "ɕi˥ tɕʰɥe˥", "syllable_count": 2, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "稀缺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "沙漠里水很稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药现在很稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小岛上，新鲜蔬菜非常稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师越来越稀缺了。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的时候，这里的水果特别稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为资源稀缺，大家都要节约用水。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越稀缺的东西，价格越高。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里，停车位十分稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候粮食很稀缺，人们吃不饱。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稀缺性", "label": "复合"}, {"form": "稀缺资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西数量少，满足不了需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0895758-7575-4f3f-b486-94a8a11fbda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺", "is_correct": true, "explanation": "正确答案。“土地稀缺的一线城市核心区”成立，表示供应不足、价格高。"}, {"text": "充足", "is_correct": false, "explanation": "语义：土地充足与句子中“价值提升、尤为突出”的语境矛盾，句子不成立。"}, {"text": "干燥", "is_correct": false, "explanation": "体貌：“干燥”描写土质或环境状态，与土地的供应状况无关。"}, {"text": "肥沃", "is_correct": false, "explanation": "搭配：“肥沃”修饰土壤，不用来修饰城市土地的供应状况。"}], "explanations": {"稀缺": "正确答案。“土地稀缺的一线城市核心区”成立，表示供应不足、价格高。", "充足": "语义：土地充足与句子中“价值提升、尤为突出”的语境矛盾，句子不成立。", "干燥": "体貌：“干燥”描写土质或环境状态，与土地的供应状况无关。", "肥沃": "搭配：“肥沃”修饰土壤，不用来修饰城市土地的供应状况。"}, "sentence_index": 0, "correct_answer": "稀缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很稀缺，大家都不怕他。", "explanation": "这里应该用〈温和〉。稀缺指供不应求，不能用来形容脾气；形容脾气好要用“温和”。"}, {"text": "这个房间的温度很稀缺，大家都觉得冷。", "explanation": "这里应该用〈低〉。稀缺指供不应求，不能用来形容温度；温度不高要用“低”。"}, {"text": "这条路的坡度很稀缺，走起来很累。", "explanation": "这里应该用〈陡〉。稀缺指供不应求，不能用来形容坡度；坡度大要用“陡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺", "is_correct": true, "explanation": "正确答案。“因为资源稀缺，大家都要节约用水”成立。"}, {"text": "丰富", "is_correct": false, "explanation": "语义：资源丰富就不需要节约用水，与句子的因果关系矛盾。"}, {"text": "过剩", "is_correct": false, "explanation": "语义：资源过剩时不必节约，句子不成立。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“资源”的供应状况说“稀缺”或“充足”，不说便宜。"}], "explanations": {"稀缺": "正确答案。“因为资源稀缺，大家都要节约用水”成立。", "丰富": "语义：资源丰富就不需要节约用水，与句子的因果关系矛盾。", "过剩": "语义：资源过剩时不必节约，句子不成立。", "便宜": "搭配：“资源”的供应状况说“稀缺”或“充足”，不说便宜。"}, "sentence_index": 6, "correct_answer": "稀缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的态度很稀缺，大家都很讨厌。", "explanation": "这里应该用〈恶劣〉。稀缺指供不应求，不能用来形容态度；态度差要用“恶劣”。"}, {"text": "今天的天气很稀缺，我们都没出门。", "explanation": "这里应该用〈糟糕〉。稀缺指供不应求，不能用来形容天气；天气不好要用“糟糕”。"}, {"text": "这座山的高度很稀缺，很快就能爬上去。", "explanation": "这里应该用〈低〉。稀缺指供不应求，不能用来形容高度；山不高要用“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛上的淡水没稀缺。", "corrected_sentence": "这个岛上的淡水不稀缺。", "error_description": "否定词错误：形容词“稀缺”表示状态，否定要用“不”，不能用“没”。应说“这个岛上的淡水不稀缺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带的粮食被稀缺了。", "corrected_sentence": "这一带的粮食稀缺了。", "error_description": "语态错误：形容词“稀缺”表示状态，不能用“被”构成被动句，应去掉“被”，说“这一带的粮食稀缺了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
