INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指事物的中心或最重要的区域，常用来形容政治、经济或军事上的关键地带。", "primary_collocate": null, "pronunciation": "hé xīn qū", "ipa": "xɤ˧˥ ɕin˥ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "高端房地产项目的市场溢价机制显著受到景观资源的驱动，毗邻或整合高品质绿地的住宅单元往往实现20%以上的价值提升，这一现象在土地稀缺的一线城市核心区尤为突出。", "target_word": "核心区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市的核心区很热闹。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司都想把办公室放在核心区。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核心区的房子比郊区贵很多。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想保护古城的核心区。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上红色的地方是核心区。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队守住了战场的核心区。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济核心区的人口增长得很快。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车进核心区要先办证。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政治核心区就在首都。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心區", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "政治、经济或军事上最关键的中心地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0895758-7575-4f3f-b486-94a8a11fbda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "核心区", "is_correct": true, "explanation": "正确。核心区指城市中最关键的中心地段，与“一线城市”“土地稀缺”的语境相符。"}, {"text": "农村", "is_correct": false, "explanation": "语义：农村与“一线城市”“土地稀缺”的城市语境相矛盾，句子说的是城市内部的土地价值。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原不在一线城市里，句中所说的房地产溢价不能发生在草原上。"}, {"text": "郊区", "is_correct": false, "explanation": "语义：郊区土地相对宽裕，与“土地稀缺”的语境矛盾，句子说的是城市中心地段的溢价。"}], "explanations": {"核心区": "正确。核心区指城市中最关键的中心地段，与“一线城市”“土地稀缺”的语境相符。", "农村": "语义：农村与“一线城市”“土地稀缺”的城市语境相矛盾，句子说的是城市内部的土地价值。", "草原": "语义：草原不在一线城市里，句中所说的房地产溢价不能发生在草原上。", "郊区": "语义：郊区土地相对宽裕，与“土地稀缺”的语境矛盾，句子说的是城市中心地段的溢价。"}, "sentence_index": 0, "correct_answer": "核心区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们公司的核心区，大家都很佩服他。", "explanation": "这里应该用〈骨干〉。核心区指地域的中心，不用来指人；指公司里的关键人员要用“骨干”。"}, {"text": "这次会议的核心区是下午三点。", "explanation": "这里应该用〈时间〉。核心区指地域的中心，不指时间；会议的时刻要用“时间”。"}, {"text": "我们去了一条核心区。", "explanation": "核心区是地域，量词应用“个”或“片”；“条”用于细长的东西，不能用于地域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核心区", "is_correct": true, "explanation": "正确。“守住”要求对象是需要防守的要地，核心区正好是战场上的关键地带。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是战场上需要防守的地带，“战场的厨房”与句子的军事语境矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不属于战场，“战场的教室”与句子的军事语境矛盾。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“守住”通常搭配阵地、要地等需要防守的地方，停车场不能作为需要守住的对象。"}], "explanations": {"核心区": "正确。“守住”要求对象是需要防守的要地，核心区正好是战场上的关键地带。", "厨房": "语义：厨房不是战场上需要防守的地带，“战场的厨房”与句子的军事语境矛盾。", "教室": "语义：教室不属于战场，“战场的教室”与句子的军事语境矛盾。", "停车场": "搭配：“守住”通常搭配阵地、要地等需要防守的地方，停车场不能作为需要守住的对象。"}, "sentence_index": 6, "correct_answer": "核心区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告的核心区是一百页。", "explanation": "这里应该用〈篇幅〉。核心区指地域的中心，不用来计量页数；报告的长短要用“篇幅”。"}, {"text": "他在地图上画了一台核心区。", "explanation": "核心区是地域，量词应用“块”或“个”；“台”用于机器、设备，不能用于地域。"}, {"text": "这篇文章的核心区是三千字。", "explanation": "这里应该用〈字数〉。核心区指地域的中心，不用来计量字数；文章的长度要用“字数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军队已经控制了城市的一条核心区。", "corrected_sentence": "军队已经控制了城市的核心区。", "error_description": "错误：“一条核心区”，正确：“核心区”或“一个核心区”。核心区是地域，不能用细长事物的量词“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把资金集中核心区。", "corrected_sentence": "政府把资金集中在核心区。", "error_description": "错误：缺少介词“在”。正确：“集中在核心区”。“集中”后要用“在”或“到”引出地点，不能直接接处所名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
