INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一地区或空间所处的位置。", "primary_collocate": null, "pronunciation": "qū wèi", "ipa": "tɕʰy˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "区位", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其区位临近消费终端的特性，极大压缩了物流损耗与碳足迹，形成对脆弱全球供应链的韧性替代。", "target_word": "区位", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店的区位很好，靠近地铁站。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选地点时，要先看区位。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的区位优势很明显。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的区位离港口很近。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "区位不同，房子的价格也不同。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把新仓库的区位定在了河边。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的区位能让商店多赚钱。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家分析了这块地的区位。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "区位优势", "label": "复合"}, {"form": "区位条件", "label": "复合"}], "register": "正式", "sense_fingerprint": "某一地区或空间所处的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0895758-7575-4f3f-b486-94a8a11fbda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区位", "is_correct": true, "explanation": "语义正确：“区位”指地点的位置，与“建筑面积”并列，是房产评估的因素。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是教育支出，不是房产评估的因素，与“建筑面积”并列不合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体指标，不能用来评估房产。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“评估”后接的是价值、风险一类指标，不与“颜色”搭配作房产的评估项。"}], "explanations": {"区位": "语义正确：“区位”指地点的位置，与“建筑面积”并列，是房产评估的因素。", "学费": "语义：学费是教育支出，不是房产评估的因素，与“建筑面积”并列不合。", "体重": "语义：体重是人的身体指标，不能用来评估房产。", "颜色": "搭配：“评估”后接的是价值、风险一类指标，不与“颜色”搭配作房产的评估项。"}, "sentence_index": 0, "correct_answer": "区位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花的区位很香。", "explanation": "这里应该用〈香味〉。区位指地区或空间的位置，不能用来形容气味。"}, {"text": "我的区位是一米八。", "explanation": "这里应该用〈身高〉。区位指地区或空间的位置，不能用来说人的身高。"}, {"text": "这只区位很好。", "explanation": "量词错误：区位是抽象名词，不能用“只”计量，应说“这个区位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区位", "is_correct": true, "explanation": "语义正确：“区位不同，房子的价格也不同”说的是地点的位置影响价格，只有“区位”符合。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数与房子的价格没有关系，“字数不同，价格也不同”不成立。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历用于人，不能影响房子的价格。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”一般用于人或动物，不能用来描述房子。"}], "explanations": {"区位": "语义正确：“区位不同，房子的价格也不同”说的是地点的位置影响价格，只有“区位”符合。", "字数": "语义：字数与房子的价格没有关系，“字数不同，价格也不同”不成立。", "学历": "语义：学历用于人，不能影响房子的价格。", "脾气": "搭配：“脾气”一般用于人或动物，不能用来描述房子。"}, "sentence_index": 6, "correct_answer": "区位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家分析了这个人的区位。", "explanation": "这里应该用〈背景〉。区位指地区或空间的位置，分析一个人应说“背景”，人没有“区位”。"}, {"text": "这道题的区位很难。", "explanation": "这里应该用〈难度〉。区位指地点的位置，题目的难易应说“难度”。"}, {"text": "他把快递的区位写成了一个人的名字。", "explanation": "这里应该用〈地址〉。区位指地区或空间的位置，快递上应填写的是“地址”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座仓库的区位的比较偏。", "corrected_sentence": "这座仓库的区位比较偏。", "error_description": "错误在于“区位”后多加了“的”。“区位”后应直接接谓语“比较偏”，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的区位有很好，交通也方便。", "corrected_sentence": "这个城市的区位很好，交通也方便。", "error_description": "错误在于“区位”后多加了“有”。“区位”后应直接接谓语“很好”，不能加“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
