INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12659, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种不使用土壤，将植物根系直接浸泡在营养液中进行栽培的方法。", "primary_collocate": null, "pronunciation": "shuǐ péi", "ipa": "ʂweɪ̯˨˩ pʰeɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "水培", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水培不用土，只用营养液。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蔬菜是用水培方法种出来的。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培比土培更干净，也更省水。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家阳台上有一套水培设备。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培生菜长得很快，一个月就能吃。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的科学课介绍了水培的原理。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培需要定期更换营养液。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对水培技术很感兴趣。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培和土培有什么不同？", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水培法", "label": "复合"}, {"form": "水培蔬菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "无土栽培方法，根系泡在营养液中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eda4a4b-09a8-44af-a6eb-f0f9370b7407') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水培", "is_correct": true, "explanation": "正确：“水培”是一种无土栽培技术，与“多层、气雾栽培”并列，符合语境。"}, {"text": "养殖", "is_correct": false, "explanation": "语义：养殖针对动物，不是植物的栽培方法。"}, {"text": "仓储", "is_correct": false, "explanation": "搭配：“仓储”指存放货物，不能与“气雾栽培”并列为栽培方式。"}, {"text": "冷库", "is_correct": false, "explanation": "语义：冷库用于保存食品，不是种植技术。"}], "explanations": {"水培": "正确：“水培”是一种无土栽培技术，与“多层、气雾栽培”并列，符合语境。", "养殖": "语义：养殖针对动物，不是植物的栽培方法。", "仓储": "搭配：“仓储”指存放货物，不能与“气雾栽培”并列为栽培方式。", "冷库": "语义：冷库用于保存食品，不是种植技术。"}, "sentence_index": 0, "correct_answer": "水培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在水培里种了一排生菜。", "explanation": "这里应该用〈大棚〉。水培是一种栽培方法，不是种植的场所，不能说“在水培里种”。"}, {"text": "妈妈用水培把碗筷洗干净了。", "explanation": "这里应该用〈清洗〉。洗碗筷是用水冲洗餐具；水培指让植物根系浸在营养液里的栽培方法，不能用来洗东西。"}, {"text": "他在水培里摘了几个苹果。", "explanation": "这里应该用〈果园〉。水培是栽培方法，不是地点；摘苹果要到果园里去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水培", "is_correct": true, "explanation": "正确：“水培的原理”指无土栽培的科学道理，与科学课的语境相合。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说讲的是情节和人物，不谈“原理”，不能说“小说的原理”。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学体裁，不存在可以讲解的“原理”，说不通。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是人际间的情感，没有可以讲解的“原理”，“友谊的原理”说不通。"}], "explanations": {"水培": "正确：“水培的原理”指无土栽培的科学道理，与科学课的语境相合。", "小说": "语义：小说讲的是情节和人物，不谈“原理”，不能说“小说的原理”。", "诗歌": "语义：诗歌是文学体裁，不存在可以讲解的“原理”，说不通。", "友谊": "语义：友谊是人际间的情感，没有可以讲解的“原理”，“友谊的原理”说不通。"}, "sentence_index": 6, "correct_answer": "水培"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民用水培给农田浇水。", "explanation": "这里应该用〈滴灌〉。滴灌是一种浇水方式；水培是让植物根系浸在营养液里的栽培方法，不能用来灌溉。"}, {"text": "妈妈用水培把饺子煮熟了。", "explanation": "这里应该用〈煮〉。煮饺子要用水煮；水培是栽培植物的方法，不能用来加热食物。"}, {"text": "这座水培里种满了番茄。", "explanation": "这里应该用〈温室〉。水培是栽培方法，不是场所；指地点要说温室或大棚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想尝试一棵水培。", "corrected_sentence": "我想尝试一种水培。", "error_description": "量词错误：水培是一种栽培方法，应说“一种水培”，不能用“棵”（“棵”用于具体的植物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班去参观了一个很水培农场。", "corrected_sentence": "我们班去参观了一个水培农场。", "error_description": "程度副词错误：“水培农场”中“水培”作名词性定语，不能被“很”修饰，应说“一个水培农场”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
