INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "液体或固体的小颗粒悬浮在气体中形成的分散体系，常呈雾状或烟状。", "primary_collocate": null, "pronunciation": "qì wù", "ipa": "tɕʰi˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "气雾", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "喷头里喷出细细的气雾。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里充满了消毒气雾。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气雾会慢慢散开。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药瓶能喷出气雾。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人戴着口罩，避免吸入气雾。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气雾里有很多小颗粒。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室用仪器测量气雾的浓度。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气雾遇到冷空气会凝结成水。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对气雾过敏。", "target_word": "气雾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一团气雾", "label": "量词"}, {"form": "气雾剂", "label": "复合"}], "register": "中性", "sense_fingerprint": "小颗粒悬浮在气体中形成的雾状分散体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eda4a4b-09a8-44af-a6eb-f0f9370b7407') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气雾", "is_correct": true, "explanation": "正确：气雾（qì wù）指悬浮在气体中的雾状小颗粒。"}, {"text": "起雾", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，起雾指雾升起来，是动宾短语。"}, {"text": "去雾", "is_correct": false, "explanation": "qù 与 qì 韵母不同，去雾指消除雾，意思不同。"}, {"text": "启悟", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，启悟指启发领悟，偏书面。"}, {"text": "其物", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，其物意为那个东西，与雾无关。"}], "explanations": {"气雾": "正确：气雾（qì wù）指悬浮在气体中的雾状小颗粒。", "起雾": "qǐ（第三声）与 qì（第四声）声调不同，起雾指雾升起来，是动宾短语。", "去雾": "qù 与 qì 韵母不同，去雾指消除雾，意思不同。", "启悟": "qǐ（第三声）与 qì（第四声）声调不同，启悟指启发领悟，偏书面。", "其物": "qí（第二声）与 qì（第四声）声调不同，其物意为那个东西，与雾无关。"}, "sentence_index": null, "correct_answer": "气雾"}, "level_3": {"options": [{"text": "气雾", "is_correct": true, "explanation": "正确：气雾栽培指让植物根部悬浮在雾状营养液中生长的种植方式，这里应填“气雾”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是种植的方式或条件，与“水培”并列的种植方法不成立。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油不能作为种植条件，“石油栽培”不是现实的种植方法。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“X栽培”限于种植方式，不能说“电视栽培”。"}], "explanations": {"气雾": "正确：气雾栽培指让植物根部悬浮在雾状营养液中生长的种植方式，这里应填“气雾”。", "音乐": "语义：音乐不是种植的方式或条件，与“水培”并列的种植方法不成立。", "石油": "语义：石油不能作为种植条件，“石油栽培”不是现实的种植方法。", "电视": "搭配：“X栽培”限于种植方式，不能说“电视栽培”。"}, "sentence_index": 0, "correct_answer": "气雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他端着一杯气雾喝了下去。", "explanation": "这里应该用〈水〉。气雾指悬浮在空中的雾状颗粒，不是液体，不能端起来喝。"}, {"text": "他有一股大丈夫的气雾。", "explanation": "这里应该用〈气概〉。气概指人的精神风貌，气雾只指空中的雾状颗粒，不能用来形容人的品格。"}, {"text": "前途笼罩着一层气雾。", "explanation": "这里应该用〈迷雾〉。迷雾可比喻困难、不明朗的局面，气雾只指空气中的雾状颗粒，不能比喻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气雾", "is_correct": true, "explanation": "正确：气雾指空气中的小颗粒悬浮物，“气雾里有很多小颗粒”成立。"}, {"text": "信念", "is_correct": false, "explanation": "语义：信念是抽象概念，不能包含可见的小颗粒。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象关系，“友谊里有很多小颗粒”说不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“小颗粒”指物理上的小粒子，不能说“诗歌里有很多小颗粒”。"}], "explanations": {"气雾": "正确：气雾指空气中的小颗粒悬浮物，“气雾里有很多小颗粒”成立。", "信念": "语义：信念是抽象概念，不能包含可见的小颗粒。", "友谊": "语义：友谊是抽象关系，“友谊里有很多小颗粒”说不通。", "诗歌": "搭配：“小颗粒”指物理上的小粒子，不能说“诗歌里有很多小颗粒”。"}, "sentence_index": 6, "correct_answer": "气雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日的气雾很热闹。", "explanation": "这里应该用〈气氛〉。气氛指热闹、紧张等感受，气雾指空中的雾状颗粒，不能形容热闹。"}, {"text": "这支球队打比赛时很有气雾。", "explanation": "这里应该用〈气势〉。气势指声势和气派，气雾只指空中的雾状颗粒，不能用来描述球队的声势。"}, {"text": "这里的气雾很温暖。", "explanation": "这里应该用〈气候〉。气候指一地长期的冷暖干湿状况，气雾只指小颗粒，不能说温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上，院子里飘着一只气雾。", "corrected_sentence": "早上，院子里飘着一团气雾。", "error_description": "量词错误：“只”多指动物或某些单件器物，气雾是成团的雾状物，应用量词“团”，应说“一团气雾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房间里弥漫着一块气雾。", "corrected_sentence": "房间里弥漫着一团气雾。", "error_description": "量词错误：“块”用于有形的块状物，气雾应用“团”或“层”，应说“一团气雾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
