INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种植并培育植物，也比喻培养、造就人才。", "primary_collocate": null, "pronunciation": "zāi péi", "ipa": "tsaɪ̯˥ pʰeɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "栽培", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在山坡上栽培茶树。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很难栽培。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用心栽培每一个学生。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大棚里栽培蔬菜。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "栽培草莓需要很多阳光。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢您多年来的栽培。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司很重视栽培年轻人。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品种适合在南方栽培。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直想栽培儿子成为医生。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽培了", "label": "体标"}, {"form": "栽培过", "label": "体标"}, {"form": "栽培法", "label": "复合"}], "register": "中性", "sense_fingerprint": "种植培育植物，引申为培养人才", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eda4a4b-09a8-44af-a6eb-f0f9370b7407') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "正确：“气雾栽培”是一种种植方式，这里应填“栽培”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭，不是种植方式，与“水培”并列不成立。"}, {"text": "审判", "is_correct": false, "explanation": "语域：“审判”是司法用语，与这段农业技术说明的语域不合，且不构成种植方式。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“气雾装修”不是固定说法，“装修”也不能修饰种植方式。"}], "explanations": {"栽培": "正确：“气雾栽培”是一种种植方式，这里应填“栽培”。", "烹饪": "语义：烹饪是做饭，不是种植方式，与“水培”并列不成立。", "审判": "语域：“审判”是司法用语，与这段农业技术说明的语域不合，且不构成种植方式。", "装修": "搭配：“气雾装修”不是固定说法，“装修”也不能修饰种植方式。"}, "sentence_index": 0, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场里栽培了很多鸡。", "explanation": "这里应该用〈养殖〉。养殖用于饲养动物，栽培用于种植植物，鸡不能说“栽培”。"}, {"text": "他每天栽培坏掉的自行车。", "explanation": "这里应该用〈修理〉。修理是把损坏的器物修好，栽培指种植培育植物，不能用于自行车。"}, {"text": "艺术家用刻刀栽培石像。", "explanation": "这里应该用〈雕刻〉。雕刻是用工具把石料刻成形状，栽培指种植培育，不能用于石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "正确：“感谢您多年来的栽培”指长期的培养与扶持，这里只能填“栽培”。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“感谢……的电池”不是可以用来感谢的对象，电池与感谢的语境不搭。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠是负面的睡眠状态，不能作为感谢的对象。"}, {"text": "锁链", "is_correct": false, "explanation": "语义：锁链带有束缚的负面色彩，与感谢的语境冲突。"}], "explanations": {"栽培": "正确：“感谢您多年来的栽培”指长期的培养与扶持，这里只能填“栽培”。", "电池": "搭配：“感谢……的电池”不是可以用来感谢的对象，电池与感谢的语境不搭。", "失眠": "语义：失眠是负面的睡眠状态，不能作为感谢的对象。", "锁链": "语义：锁链带有束缚的负面色彩，与感谢的语境冲突。"}, "sentence_index": 6, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里栽培晚饭。", "explanation": "这里应该用〈烹饪〉。烹饪是做饭，栽培指种植培育，不能用于晚饭。"}, {"text": "他能把这篇文章栽培成英文。", "explanation": "这里应该用〈翻译〉。翻译是把一种语言转换成另一种语言，栽培指种植培育，不能这样用。"}, {"text": "工人正在栽培墙面。", "explanation": "这里应该用〈粉刷〉。粉刷是在墙面涂上涂料，栽培指种植培育，不能用于墙面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候在农场里栽培了过茶树。", "corrected_sentence": "他小时候在农场里栽培过茶树。", "error_description": "体标错误：“过”表示曾经有过的经历，与“了”不能同时用在动词后。应说“栽培过”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "果农把苹果树栽培很好。", "corrected_sentence": "果农把苹果树栽培得很好。", "error_description": "补语错误：“栽培”后接程度补语须用“得”，应说“栽培得很好”，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fae31343-36b1-4e84-89c0-56e8b4a4ff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
