INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为满足某种需要而建立或设置的建筑、设备、场所等。", "primary_collocate": null, "pronunciation": "shè shī", "ipa": "ʂɤ⁵¹ ʂɿ⁵⁵", "syllable_count": 2, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座城市的公共设施越来越完善。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的体育设施已经向市民开放了。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的医疗设施都很先进。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在更新旧的教学设施。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区增加了不少服务设施。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府投入资金改善农村的生活设施。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，受损的设施很快得到了修复。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的设施齐全，环境也很好。", "target_word": "设施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项设施", "label": "量词"}, {"form": "一套设施", "label": "量词"}, {"form": "公共设施", "label": "复合"}, {"form": "设施", "label": "简体"}, {"form": "設施", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为某种需要建立的建筑、设备、场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb45f3-2334-4b4f-b7f2-26752ccc9cbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设施", "is_correct": true, "explanation": "为满足某种需要而建立或设置的建筑、设备、场所等。"}, {"text": "摄氏", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，“摄氏”是温标名称，意思不是设施。"}, {"text": "摄食", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，“摄食”指进食，意思不同。"}, {"text": "社史", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，“社史”指一个团体的历史。"}], "explanations": {"设施": "为满足某种需要而建立或设置的建筑、设备、场所等。", "摄氏": "shì（第四声）与 shī（第一声）声调不同，“摄氏”是温标名称，意思不是设施。", "摄食": "shí（第二声）与 shī（第一声）声调不同，“摄食”指进食，意思不同。", "社史": "shǐ（第三声）与 shī（第一声）声调不同，“社史”指一个团体的历史。"}, "sentence_index": null, "correct_answer": "设施"}, "level_3": {"options": [{"text": "设施", "is_correct": true, "explanation": "设施：为某种需要建立的建筑、设备、场所等，与“生态基础”搭配，指生态方面的基础建设。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是建立起来的设施，“生态基础乐器”讲不通，也无法被视为杠杆。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品不是建造出来的设施，“生态基础食品”讲不通，也无法被视为资产流动性的杠杆。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是建立起来的设施，“生态基础天气”讲不通，也无法被视为杠杆。"}], "explanations": {"设施": "设施：为某种需要建立的建筑、设备、场所等，与“生态基础”搭配，指生态方面的基础建设。", "乐器": "语义：乐器不是建立起来的设施，“生态基础乐器”讲不通，也无法被视为杠杆。", "食品": "语义：食品不是建造出来的设施，“生态基础食品”讲不通，也无法被视为资产流动性的杠杆。", "天气": "语义：天气不是建立起来的设施，“生态基础天气”讲不通，也无法被视为杠杆。"}, "sentence_index": 0, "correct_answer": "设施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的设施很热情。", "explanation": "这里应该用〈服务〉。“热情”形容人的态度，设施指场所或装置，不能说“设施热情”。"}, {"text": "这次活动的设施很精彩。", "explanation": "这里应该用〈内容〉。“精彩”形容活动、节目的内容，设施指建造或安装的装置，不能说“设施精彩”。"}, {"text": "导游的设施很生动。", "explanation": "这里应该用〈讲解〉。“生动”形容讲解、描述，设施是建造物或装置，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设施", "is_correct": true, "explanation": "设施：景区为游客提供服务的建筑、设备等，与“服务”搭配。"}, {"text": "景点", "is_correct": false, "explanation": "搭配：“服务”后面不接“景点”，景点是景区本身，不能说“服务景点”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以增加的服务项目，“服务天气”讲不通。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价不是服务本身，“服务票价”说不通，句子也没有这个意思。"}], "explanations": {"设施": "设施：景区为游客提供服务的建筑、设备等，与“服务”搭配。", "景点": "搭配：“服务”后面不接“景点”，景点是景区本身，不能说“服务景点”。", "天气": "语义：天气不是可以增加的服务项目，“服务天气”讲不通。", "票价": "语义：票价不是服务本身，“服务票价”说不通，句子也没有这个意思。"}, "sentence_index": 6, "correct_answer": "设施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校给每个学生发了新的文具设施。", "explanation": "这里应该用〈用品〉。设施指建造或安装的装置，文具是学生用的小物件，应说“文具用品”，不能说“文具设施”。"}, {"text": "这首歌的设施很动听。", "explanation": "这里应该用〈旋律〉。“动听”形容声音、旋律，设施指建造或放置的装置，不能用来形容歌曲。"}, {"text": "运动员比赛时戴的设施很专业。", "explanation": "这里应该用〈器材〉。运动员戴的是器材，设施指固定建造的场所或装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们学校新增了一只公共设施。", "corrected_sentence": "这个月我们学校新增了一项公共设施。", "error_description": "量词错误：“设施”一般用“项”或“套”计数，不用“只”。正确说法是“一项公共设施”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家酒店的一根设施很齐全。", "corrected_sentence": "这家酒店的一套设施很齐全。", "error_description": "量词错误：“设施”一般用“套”或“项”计数，“根”用于细长的东西，不能用来数设施。正确说法是“一套设施”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
