INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示事物数量的概念。", "primary_collocate": null, "pronunciation": "shù", "ipa": "ʂu⁵¹", "syllable_count": 1, "sentences": [{"text": "数可以告诉我们东西有多少。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先学会认数，再学加法。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数是用来表示多少的。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一、二、三都是数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数比十大，比二十小。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写一个比五大的数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有数的概念，我们就没法算钱。", "target_word": "数", "complexity_tier": "T3", "furigana": "méi yǒu shù de gài niàn wǒ men jiù méi fǎ suàn qián", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数太大了，我读不出来。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数越大，表示的东西就越多。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数", "label": "量词"}, {"form": "數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示事物数量的概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb45f3-2334-4b4f-b7f2-26752ccc9cbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "表示事物数量的概念。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书。"}, {"text": "素", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}], "explanations": {"数": "表示事物数量的概念。", "书": "shū（第一声）与 shù（第四声）声调不同，意思是书。", "素": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。", "暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示事物数量的概念，可以告诉我们有多少。"}, {"text": "字", "is_correct": false, "explanation": "语义：字不是表示数量的概念，不能告诉我们东西有多少。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有多少”说的是可以计数的东西，颜色不能这样计数。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言不表示多少，不能告诉我们东西的数量。"}], "explanations": {"数": "数：表示事物数量的概念，可以告诉我们有多少。", "字": "语义：字不是表示数量的概念，不能告诉我们东西有多少。", "颜色": "搭配：“有多少”说的是可以计数的东西，颜色不能这样计数。", "语言": "语义：语言不表示多少，不能告诉我们东西的数量。"}, "sentence_index": 0, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的数很开朗。", "explanation": "这里应该用〈同学〉。“开朗”形容人的性格，“数”指抽象的数量概念，不能用来形容班里的人。"}, {"text": "他这次考试的数很高。", "explanation": "这里应该用〈分数〉。“高”形容分数，“数”指抽象的数量概念，不能说考试的数高。"}, {"text": "他跑步的数很多。", "explanation": "这里应该用〈次数〉。“很多”形容次数，“数”指抽象的数量概念，不能用来说跑了多少次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "表示事物数量的概念。"}, {"text": "诉", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}], "explanations": {"数": "表示事物数量的概念。", "诉": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。", "叔": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。", "薯": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示事物数量的概念，没有它就没法计算钱。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐与计算钱没有关系，“没有音乐的概念”无法支撑后面的算钱。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“概念”一般不跟“影子”搭配，句中也不表示数量。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离是长短的概念，不能用来计算钱。"}], "explanations": {"数": "数：表示事物数量的概念，没有它就没法计算钱。", "音乐": "语义：音乐与计算钱没有关系，“没有音乐的概念”无法支撑后面的算钱。", "影子": "搭配：“概念”一般不跟“影子”搭配，句中也不表示数量。", "距离": "语义：距离是长短的概念，不能用来计算钱。"}, "sentence_index": 6, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的数很合适。", "explanation": "这里应该用〈尺寸〉。“合适”说衣服的大小，“数”是抽象的数量概念，不能指尺寸。"}, {"text": "他忘记了手机的数。", "explanation": "这里应该用〈号码〉。手机号码是用来拨打的编号，“数”表示数量的概念，不能指号码。"}, {"text": "这个仓库的货物数很重。", "explanation": "这里应该用〈重量〉。说货物有多重要用重量，“数”是抽象的数量概念，不能指重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只数相加得到的是和。", "corrected_sentence": "两个数相加，得到的是和。", "error_description": "量词错误：“数”应该用“个”计数，“只”用于动物等，不能用来数数字。正确说法是“两个数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "的数概念很抽象，孩子要慢慢学。", "corrected_sentence": "数的概念很抽象，孩子要慢慢学。", "error_description": "语序错误：“数的”是定语结构，“的”要在“数”后面，应说“数的概念”，不能说“的数概念”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平面", "is_correct": true, "explanation": "正确。平面只有长和宽，与“有长、宽、高”的立体相对，构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无关：花园是名词，与立体没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：河流与立体没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "无关：书包与立体没有反义关系。"}], "correct_answer": "平面", "explanations": {"平面": "正确。平面只有长和宽，与“有长、宽、高”的立体相对，构成反义。", "花园": "无关：花园是名词，与立体没有反义关系。", "河流": "无关：河流与立体没有反义关系。", "书包": "无关：书包与立体没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平面", "is_correct": true, "explanation": "正确。平面只有长和宽，与“有长、宽、高”的立体相对，构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：海洋是名词，与立体没有反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "无关：课本与立体没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房与立体没有反义关系。"}], "correct_answer": "平面", "explanations": {"平面": "正确。平面只有长和宽，与“有长、宽、高”的立体相对，构成反义。", "海洋": "无关：海洋是名词，与立体没有反义关系。", "课本": "无关：课本与立体没有反义关系。", "厨房": "无关：厨房与立体没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体具有长、宽、高三个维度，不是平面的。", "primary_collocate": null, "pronunciation": "lì tǐ", "ipa": "li⁵¹ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这张立体地图很清楚。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢看立体书。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个立体停车场能停五百辆车。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸做了一个立体的房子。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是立体的，可以拿在手上转。", "target_word": "立体", "complexity_tier": "T3", "furigana": "lì tǐ", "sentence_source": "generated"}, {"text": "这块积木是立体的，不是平的。", "target_word": "立体", "complexity_tier": "T3", "furigana": "lì tǐ", "sentence_source": "generated"}, {"text": "球是立体的，圆是平面的。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "立体的图形有长、宽、高。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里有立体交通，比如高架桥。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立体图形", "label": "复合"}, {"form": "立體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有长宽高三个维度，不是平面的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb45f3-2334-4b4f-b7f2-26752ccc9cbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体（lì tǐ）指物体有长、宽、高三个维度，不是平面的。"}, {"text": "例题", "is_correct": false, "explanation": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。"}, {"text": "离题", "is_correct": false, "explanation": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。"}, {"text": "离体", "is_correct": false, "explanation": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。"}, {"text": "立替", "is_correct": false, "explanation": "立替（lì tì）与立体（lì tǐ）第二个音节声调不同（tì 与 tǐ），意思是先替人垫付。"}], "explanations": {"立体": "正确。立体（lì tǐ）指物体有长、宽、高三个维度，不是平面的。", "例题": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。", "离题": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。", "离体": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。", "立替": "立替（lì tì）与立体（lì tǐ）第二个音节声调不同（tì 与 tǐ），意思是先替人垫付。"}, "sentence_index": null, "correct_answer": "立体"}, "level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。“立体空间”指有长、宽、高的三维空间，与“多层水培”相合。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”指地面平整没有起伏，与“多层”栽培相矛盾。"}, {"text": "单薄", "is_correct": false, "explanation": "搭配：“单薄”多形容纸张、身体等薄弱，不用来修饰“空间”。"}, {"text": "狭小", "is_correct": false, "explanation": "语义：“狭小”与“数万平方米”的规模相矛盾。"}], "explanations": {"立体": "正确。“立体空间”指有长、宽、高的三维空间，与“多层水培”相合。", "平坦": "语义：“平坦”指地面平整没有起伏，与“多层”栽培相矛盾。", "单薄": "搭配：“单薄”多形容纸张、身体等薄弱，不用来修饰“空间”。", "狭小": "语义：“狭小”与“数万平方米”的规模相矛盾。"}, "sentence_index": 0, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的立体很大。", "explanation": "这里应该用〈空间〉。房间的大小要说空间，立体指有长、宽、高的形状，不指房间的容积。"}, {"text": "这张桌面的立体很平。", "explanation": "这里应该用〈平整〉。桌面平不平要用平整来说；立体指有长、宽、高的三维形状。"}, {"text": "这栋楼的立体有三十米。", "explanation": "这里应该用〈高度〉。楼有多高要说高度，立体指有长、宽、高的形状，不指高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体的积木有长、宽、高，与“不是平的”前后呼应。"}, {"text": "平整", "is_correct": false, "explanation": "语义：“平整”与“不是平的”直接矛盾。"}, {"text": "扁平", "is_correct": false, "explanation": "体貌：“扁平”描述外形薄而平，与“不是平的”所说的外形相冲突。"}, {"text": "平面", "is_correct": false, "explanation": "语义：“平面”与“不是平的”直接矛盾，句子无法成立。"}], "explanations": {"立体": "正确。立体的积木有长、宽、高，与“不是平的”前后呼应。", "平整": "语义：“平整”与“不是平的”直接矛盾。", "扁平": "体貌：“扁平”描述外形薄而平，与“不是平的”所说的外形相冲突。", "平面": "语义：“平面”与“不是平的”直接矛盾，句子无法成立。"}, "sentence_index": 6, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面镜子的立体很光滑。", "explanation": "这里应该用〈光滑〉。镜面是平的，说它表面要用光滑；立体指有长、宽、高的形状。"}, {"text": "这片草原的立体很平坦。", "explanation": "这里应该用〈平坦〉。草原地势平坦，说地形要用平坦；立体用于有长、宽、高的物体。"}, {"text": "这个房间打扫得很立体。", "explanation": "这里应该用〈干净〉。房间干不干净要说干净，立体指有长、宽、高的物体，不指清洁程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的插图是立体地，翻开会跳出来。", "corrected_sentence": "这本书的插图是立体的，翻开会跳出来。", "error_description": "错误：“立体”作谓语时后面要用“的”，不能用“地”。正确形式：是立体的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画的人物画的很立体。", "corrected_sentence": "这幅画的人物画得很立体。", "error_description": "错误：表示程度补语要用结构助词“得”，不用“的”。正确形式：画得很立体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
