INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叶菜是指以嫩叶、叶柄或叶球为食用部分的蔬菜，如菠菜、白菜等。", "primary_collocate": null, "pronunciation": "yè cài", "ipa": "jɛ˥˩ tsʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "叶菜", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我今天在市场买了两斤叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶菜要多洗几遍再吃。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菠菜和白菜都是叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天叶菜长得特别快。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用叶菜做了一碗汤。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的叶菜很新鲜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶菜放在冰箱里能保存几天。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，多吃叶菜对身体好。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在阳台上种了一些叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "斤", "label": "量词"}, {"form": "葉菜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以叶为食用部分的蔬菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb45f3-2334-4b4f-b7f2-26752ccc9cbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶菜", "is_correct": true, "explanation": "正确：“叶菜”指可食用的叶类蔬菜，与“新鲜叶菜与药用植物”这个水培设施的产出相符。"}, {"text": "肉类", "is_correct": false, "explanation": "语义：水培、气雾栽培生产的是植物，“肉类”不是这类设施的产出。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材不能由水培设施产出，与句中的“新鲜”和植物产出不符。"}, {"text": "白酒", "is_correct": false, "explanation": "搭配：“新鲜”不能修饰白酒，二者搭配不当。"}], "explanations": {"叶菜": "正确：“叶菜”指可食用的叶类蔬菜，与“新鲜叶菜与药用植物”这个水培设施的产出相符。", "肉类": "语义：水培、气雾栽培生产的是植物，“肉类”不是这类设施的产出。", "木材": "语义：木材不能由水培设施产出，与句中的“新鲜”和植物产出不符。", "白酒": "搭配：“新鲜”不能修饰白酒，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "叶菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "番茄是叶菜。", "explanation": "这里应该用〈果菜〉。叶菜指以叶子、叶柄为食用部分的蔬菜，番茄吃的是果实，不能归入叶菜。"}, {"text": "我用叶菜写了一封信。", "explanation": "这里误把〈叶菜〉当成〈纸张〉来用。叶菜是可以吃的蔬菜，不能拿来写字。"}, {"text": "秋天的叶菜落了一地。", "explanation": "这里应该用〈树叶〉。叶菜指可以吃的蔬菜，不能用来指树上掉落的叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶菜", "is_correct": true, "explanation": "正确：“叶菜”是可以新鲜出售的食物，与“这家店的……很新鲜”的搭配相符。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“新鲜”用于食物，不能用来形容钢铁。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“新鲜”不能修饰家具，二者搭配不当。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭不是可以“新鲜”的商品，句意与“新鲜”的食物意义不符。"}], "explanations": {"叶菜": "正确：“叶菜”是可以新鲜出售的食物，与“这家店的……很新鲜”的搭配相符。", "钢铁": "搭配：“新鲜”用于食物，不能用来形容钢铁。", "家具": "搭配：“新鲜”不能修饰家具，二者搭配不当。", "煤炭": "语义：煤炭不是可以“新鲜”的商品，句意与“新鲜”的食物意义不符。"}, "sentence_index": 6, "correct_answer": "叶菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把叶菜穿在身上。", "explanation": "这个词不这么用。“穿”的对象应是衣物，叶菜是食物，这个动宾搭配不对。"}, {"text": "我每天都要喝叶菜。", "explanation": "这个词不这么用。“喝”的对象应是液体，叶菜是固体蔬菜，这个搭配不对。"}, {"text": "这个孩子爱听叶菜。", "explanation": "这个词不这么用。“听”的对象应是声音或话语，叶菜不能用“听”来搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天在市场买了两张叶菜。", "corrected_sentence": "我今天在市场买了两把叶菜。", "error_description": "叶菜应用“把”或“斤”计量，“张”用于纸张、桌子等平面的东西，不能用来数叶菜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些叶菜们放在冰箱里能保存三天。", "corrected_sentence": "这些叶菜放在冰箱里能保存三天。", "error_description": "“叶菜”是指蔬菜的名词，一般不加“们”。“们”通常只加在指人或某些指人的名词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5daa035-0555-44be-a6a1-12e5f2d5c776') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
