INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接近、靠近某个时间或地点。", "primary_collocate": null, "pronunciation": "lín jìn", "ipa": "lin˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "其区位临近消费终端的特性，极大压缩了物流损耗与碳足迹，形成对脆弱全球供应链的韧性替代。", "target_word": "临近", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家临近地铁站，上班很方便。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校临近河边，空气特别好。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近春节，街上的人越来越多。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近考试，同学们都在认真复习。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院临近公园，病人可以去散步。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近中午，厨房里传来了饭菜的香味。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的酒店临近海边，晚上能听到海浪声。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近毕业，他开始认真找工作。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店临近关门，里面已经没什么人了。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "临近了", "label": "体标"}, {"form": "臨近", "label": "繁体"}], "register": "中性", "sense_fingerprint": "接近、靠近某个时间或地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7495a4d-72ab-465f-85aa-3d63cd57a817') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临近", "is_correct": true, "explanation": "正确。“临近”表示靠近，与“压缩物流损耗”的因果一致。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”表示距离遥远，与“压缩物流损耗”的结论相反。"}, {"text": "偏离", "is_correct": false, "explanation": "搭配：“偏离”多接方向、路线，不说“区位偏离……的特性”。"}, {"text": "脱离", "is_correct": false, "explanation": "语义：“脱离”指离开、摆脱，与句子说的靠近消费终端相反。"}], "explanations": {"临近": "正确。“临近”表示靠近，与“压缩物流损耗”的因果一致。", "远离": "语义：“远离”表示距离遥远，与“压缩物流损耗”的结论相反。", "偏离": "搭配：“偏离”多接方向、路线，不说“区位偏离……的特性”。", "脱离": "语义：“脱离”指离开、摆脱，与句子说的靠近消费终端相反。"}, "sentence_index": 0, "correct_answer": "临近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和老师临近，有问题总爱去问。", "explanation": "这里应该用〈亲近〉。临近只用于时间和地点，不用于形容人与人之间的感情。"}, {"text": "他的成绩临近满分，大家都很佩服。", "explanation": "这里应该用〈接近〉。临近用于时间和地点，不用于分数或程度。"}, {"text": "两根木棍的长度临近，放在一起看不出差别。", "explanation": "这里应该用〈相近〉。临近只用于时间和地点快到，不用于说两样东西的长度相似。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临近", "is_correct": true, "explanation": "正确。“临近”表示快到某个时间，与“中午”搭配，符合句意。"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“离开”后接地点或人，不接时间，不说“离开中午”。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”的对象是事物，与时间无关，句子无法成立。"}, {"text": "洗刷", "is_correct": false, "explanation": "搭配：“洗刷”接的是物体，不能用于时间。"}], "explanations": {"临近": "正确。“临近”表示快到某个时间，与“中午”搭配，符合句意。", "离开": "搭配：“离开”后接地点或人，不接时间，不说“离开中午”。", "发明": "语义：“发明”的对象是事物，与时间无关，句子无法成立。", "洗刷": "搭配：“洗刷”接的是物体，不能用于时间。"}, "sentence_index": 6, "correct_answer": "临近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对兄弟的关系临近，几乎形影不离。", "explanation": "这里应该用〈亲密〉。临近只用于时间和地点，不用于描写人际关系。"}, {"text": "他的身高临近一米八，站在人群里很显眼。", "explanation": "这里应该用〈达到〉。临近只用于时间和地点，不用于数量。"}, {"text": "老奶奶的态度临近，对谁都温和。", "explanation": "这里应该用〈亲切〉。临近不用来形容态度或感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家被临近车站，走路五分钟就到。", "corrected_sentence": "我家临近车站，走路五分钟就到。", "error_description": "被动用法错误：“临近”表示靠近，不能用“被”构成被动句，应说“我家临近车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校临近到河边，走几步就能看到水。", "corrected_sentence": "我们学校临近河边，走几步就能看到水。", "error_description": "多余的补语：“临近”后不能接“到”，应说“我们学校临近河边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
