INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物品因使用、时间或自然原因而减少或失去原有价值。", "primary_collocate": null, "pronunciation": "sǔn hào", "ipa": "suən˨˩˦ xɑu˥˩", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "其区位临近消费终端的特性，极大压缩了物流损耗与碳足迹，形成对脆弱全球供应链的韧性替代。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "机器用久了，零件会有损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑的电池损耗很大。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运输时，水果会有一些损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法减少水管的损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎用了三年，损耗已经很明显。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都会计算仓库的损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服经常洗，也会有自然损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料很结实，损耗比较小。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然损耗", "label": "复合"}, {"form": "损耗率", "label": "复合"}], "register": "中性", "sense_fingerprint": "物品因使用或时间而减少、失去价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：蒸发减少的是水分，“温度”不会因蒸发而被“减少”。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。“减少了蒸发损耗”指蒸发造成的水分流失，符合这段语境。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“减少”一般不与“宣传”搭配，“蒸发宣传”也说不通。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“蒸发”造成的是水分减少，不能说减少“节奏”。"}], "explanations": {"温度": "语义：蒸发减少的是水分，“温度”不会因蒸发而被“减少”。", "损耗": "正确。“减少了蒸发损耗”指蒸发造成的水分流失，符合这段语境。", "宣传": "搭配：“减少”一般不与“宣传”搭配，“蒸发宣传”也说不通。", "节奏": "搭配：“蒸发”造成的是水分减少，不能说减少“节奏”。"}, "sentence_index": 0, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司上个月损耗了三十万元。", "explanation": "这里应该用〈损失〉。损耗指物品因使用或时间而减少，钱款的亏损要说损失。"}, {"text": "这次事故损耗了他的右腿。", "explanation": "这里应该用〈损伤〉。损耗指物品因使用、时间慢慢减少，身体部位在事故中受伤要说损伤。"}, {"text": "这场地震损耗了整座大楼。", "explanation": "这里应该用〈损坏〉。损耗指东西慢慢变少或变坏，地震造成的突然破坏要说损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：轮胎用了三年不会产生需要“明显”的香味，这里指的是磨损。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。“损耗已经很明显”指轮胎因使用而磨损，符合语境。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”需要有生命的主体，“轮胎”不能有脾气。"}, {"text": "名气", "is_correct": false, "explanation": "语义：“名气”与轮胎的使用年限无关，不能说“已经很明显”。"}], "explanations": {"香味": "语义：轮胎用了三年不会产生需要“明显”的香味，这里指的是磨损。", "损耗": "正确。“损耗已经很明显”指轮胎因使用而磨损，符合语境。", "脾气": "配价：“脾气”需要有生命的主体，“轮胎”不能有脾气。", "名气": "语义：“名气”与轮胎的使用年限无关，不能说“已经很明显”。"}, "sentence_index": 6, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在网上损耗大量时间。", "explanation": "这里应该用〈浪费〉。损耗指物品因使用而减少，时间白白花掉要说浪费。"}, {"text": "他的意志在生活的磨难中被损耗得更坚强。", "explanation": "这里应该用〈磨练〉。损耗指东西因使用而减少或变坏，意志在磨难中变得坚强要说磨练，不能说损耗。"}, {"text": "那位老人损耗得很厉害，走路都困难。", "explanation": "这里应该用〈衰老〉。损耗用于物品因使用而减少，不能用来形容人的身体变老。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里有一只不小的损耗，需要查清原因。", "corrected_sentence": "仓库里有一笔不小的损耗，需要查清原因。", "error_description": "量词错误：“损耗”作为数量应说“一笔”，不能说“一只”。“只”用于动物或单个物品，改为“一笔”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批机器用了十年，损耗的很厉害。", "corrected_sentence": "这批机器用了十年，损耗很厉害。", "error_description": "多余的“的”：“损耗”作主语，后面直接接“很厉害”，不加“的”，应去掉“的”，写作“损耗很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主粮指一个国家或地区人们日常饮食中最主要、消费量最大的粮食作物，如水稻、小麦等。", "primary_collocate": null, "pronunciation": "zhǔ liáng", "ipa": "ʈʂu˨˩˦ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "主粮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在中国南方，大米是人们的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人常把小麦做成面条和馒头，小麦是主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水稻和小麦是中国最重要的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视主粮的生产，不让农民少种粮食。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米在有些地方也是人们每天吃的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆不是我们的主粮，我们一般当菜吃。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年下雨多，主粮的价格没有变化。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲有些国家把木薯当作主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，以前农村人的主粮是玉米面。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主粮产区", "label": "复合"}, {"form": "主糧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一国或一地区日常饮食中最主要的粮食作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7495a4d-72ab-465f-85aa-3d63cd57a817') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。主粮 zhǔ liáng 指一个国家或地区人们主要吃的粮食作物。"}, {"text": "储粮", "is_correct": false, "explanation": "chǔ（第三声）与 zhǔ（第三声）声母不同，ch 与 zh 相混；储粮意思是储存粮食，不是主粮。"}, {"text": "粗粮", "is_correct": false, "explanation": "cū（第一声）与 zhǔ（第三声）声母和声调都不同，意思是粗粮，如玉米、小米。"}, {"text": "猪粮", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）只有声调不同，意思是养猪用的粮食。"}, {"text": "出粮", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调不同，意思是产出粮食。"}], "explanations": {"主粮": "正确。主粮 zhǔ liáng 指一个国家或地区人们主要吃的粮食作物。", "储粮": "chǔ（第三声）与 zhǔ（第三声）声母不同，ch 与 zh 相混；储粮意思是储存粮食，不是主粮。", "粗粮": "cū（第一声）与 zhǔ（第三声）声母和声调都不同，意思是粗粮，如玉米、小米。", "猪粮": "zhū（第一声）与 zhǔ（第三声）只有声调不同，意思是养猪用的粮食。", "出粮": "chū（第一声）与 zhǔ（第三声）声母与声调不同，意思是产出粮食。"}, "sentence_index": null, "correct_answer": "主粮"}, "level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“主粮产区”指粮食作物的产区，填入“主粮”后与“产区”搭配，句意通顺。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“城市产区”不成立，产区指集中生产某种产品的地区，城市不是可以集中生产的产品。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被生产成一个产区，与句中“食品生产网络”的语境相冲突。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁产区”不能成立，地铁是交通设施，不是可以集中生产的产品。"}], "explanations": {"主粮": "正确。“主粮产区”指粮食作物的产区，填入“主粮”后与“产区”搭配，句意通顺。", "城市": "搭配：“城市产区”不成立，产区指集中生产某种产品的地区，城市不是可以集中生产的产品。", "空气": "语义：空气不能被生产成一个产区，与句中“食品生产网络”的语境相冲突。", "地铁": "搭配：“地铁产区”不能成立，地铁是交通设施，不是可以集中生产的产品。"}, "sentence_index": 0, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的主粮是房地产和物流。", "explanation": "这里应该用〈主营〉。主粮只指水稻、小麦等粮食作物，说公司的主要业务要用主营，不能用主粮。"}, {"text": "我们村今年种的主粮是棉花和甘蔗。", "explanation": "这里应该用〈经济作物〉。棉花、甘蔗属于经济作物，主粮专指水稻、小麦等口粮作物，不能用来指它们。"}, {"text": "我最喜欢的主粮是炸鸡。", "explanation": "这里应该用〈食物〉。炸鸡是食物，但不是粮食作物，不能说成主粮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“不是我们的主粮，我们一般当菜吃”形成对照，符合句意。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“不是蔬菜”与后半句“当菜吃”自相矛盾。"}, {"text": "菜肴", "is_correct": false, "explanation": "语义：“不是菜肴”与后半句“当菜吃”自相矛盾。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“不是菜”与后半句“当菜吃”自相矛盾。"}], "explanations": {"主粮": "正确。“不是我们的主粮，我们一般当菜吃”形成对照，符合句意。", "蔬菜": "语义：“不是蔬菜”与后半句“当菜吃”自相矛盾。", "菜肴": "语义：“不是菜肴”与后半句“当菜吃”自相矛盾。", "菜": "语义：“不是菜”与后半句“当菜吃”自相矛盾。"}, "sentence_index": 6, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天喝的主粮是牛奶。", "explanation": "这里应该用〈饮料〉。牛奶是饮品，主粮指水稻、小麦等粮食作物，不能用来喝。"}, {"text": "这道菜的主粮是盐和酱油。", "explanation": "这里应该用〈调料〉。盐和酱油是调味品，不是粮食作物，不能作主粮。"}, {"text": "这顿饭的主粮是烤鸭。", "explanation": "这里应该用〈主菜〉。烤鸭是菜肴，主粮指粮食作物，不能指菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家买了一只主粮。", "corrected_sentence": "我们家买了一袋主粮。", "error_description": "“主粮”是粮食类名词，量词应用“袋”，不能用“只”。正确说法是“一袋主粮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片地区只种一个主粮。", "corrected_sentence": "这片地区只种一种主粮。", "error_description": "“主粮”指一类粮食，量词应用“种”，不能用“个”。正确说法是“一种主粮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
